import { Component, OnInit, OnDestroy, HostListener, ChangeDetectionStrategy } from '@angular/core';
import { NavController, NavParams } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';
import 'rxjs/add/observable/of';
import 'rxjs/add/operator/do';
import 'rxjs/add/operator/map';
import * as $ from 'jquery';

// Page components.
import { UserPage } from '../user/user';

// Service/provider components.
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';

@Component({
  selector: 'page-user-list',
  templateUrl: 'user-list.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class UserListPage implements OnInit, OnDestroy {

  asyncResults: Observable<any>;
  p: number = 1;
  total: number;
  itemsPerPage: number;

  searchTerm = null;
  search: string = null;

  loading: boolean = true;
  noResult: boolean = true;
  gettingPage = false;

  btnEnabled: boolean = true;

  // Permissions.
  newUserEnabled: boolean = false;

  ready: boolean = false;
  selectEnabled: boolean = true;
  users: Array<any> = [];
  csSubs: Subscription = null;
  filteredUsers: Array<any> = [];
  roles: Array<any> = [];
  selectedRole: string = 'ALL';
  pageTitle: string = 'USER_LIST_TITLE';

  virKeyboardSubs: Subscription = null;

  constructor(private navParams: NavParams,
              private navCtrl: NavController,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession) {
    this.newUserEnabled = this.userSession.getPermission('user-insert');

    this.csSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'user-list') return;

        switch (res.cmd) {
          case 'refresh':
            this.getPage(1);
            break;
        }
      }
    );

    this.backendApi.getRoles().subscribe(
      res => {
        if (this.selectEnabled) {
          this.roles = res.filter(role => (role.role !== 'client' && role.role !== 'vending'));
        } else {
          this.roles = res;
        }
      },
      err => {},
    );
  }

  ngOnInit() {
    let role = this.navParams.get('role');
    let title = this.navParams.get('title');
    if (role) {
      this.selectedRole = role;
      this.selectEnabled = false;
      if (role === 'client') {
        this.newUserEnabled = false;
        this.selectedRole = null;
      }
    }
    if (title) {
      this.pageTitle = title;
    }
    
    this.getPage(1);
  }

  ngOnDestroy() {
    if (this.csSubs) this.csSubs.unsubscribe();
  }

  add() {
    if (this.pageTitle === 'USER_LIST_TITLE') {
      this.navCtrl.push(UserPage, { user: null, roles: this.roles.filter(el => (el.role !== 'client')), userRole: null });
    } else {
      this.navCtrl.push(UserPage, { user: null, roles: this.roles.filter(el => (el.role === 'client')), title: 'CLIENT_TITLE', userRole: null });
    }
  }

  select(user) {
    if (!this.btnEnabled) return;

    this.btnEnabled = false;
    // Get user details.
    this.backendApi.getUserDetails(user.userId).subscribe(
      res => {
        this.navCtrl.push(UserPage, { user: res, roles: this.roles.filter(el => (el.role !== 'client')), userRole: user.role.role });
        this.btnEnabled = true;
      },
      err => this.btnEnabled = true
    );
  }

  getPage(page: number) {
    $('page-user-list .scroll-content').animate({ scrollTop: 0 }, "slow");

    this.gettingPage = true;
    this.asyncResults = this.backendApi.getUsersPage(page, this.searchTerm, this.selectedRole)
    .do(res => {
      if (this.selectEnabled) {  // Not client
        res.rows.forEach(el => {
          if (el.address.mobileNumber && el.address.mobileNumber !== '') {
            el['phone'] = el.address.mobileNumber;
          } else if (el.address.mobileNumber && el.address.phoneNumber !== '') {
            el['phone'] = el.address.phoneNumber;
          } else {
            el['phone'] = '---';
          }
          el['email'] = (el.address.email && el.address.email !== '') ? el.address.email : '---';
        });
      }

      if (!this.itemsPerPage) this.itemsPerPage = res.rows.length;
      this.total = res.totalPages * this.itemsPerPage;
      this.p = page;

      if (res.rows.length === 0) {
        this.noResult = true;
      } else {
        this.noResult = false;
      }
      this.loading = false;
      this.gettingPage = false;
    }, err => {
      this.gettingPage = false;
      this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
    })
    .map(res => res.rows);
  }

  filterResults(e) {
    if (this.search.length === 0) {
      this.searchTerm = null;
      this.getPage(1);
    }
    if (this.search.length > 2) {
      this.searchTerm = (this.search === '') ? null : this.search;
      this.getPage(1);
    }
  }

  showAllResults(clearEv) {
    if (clearEv.type === 'click') {
      this.searchTerm = null;
      this.getPage(1);
    }
  }

  onRoleChange(ev) {
    if (this.selectedRole !== ev) {
      this.selectedRole = ev;
      this.getPage(1);
    }
  }
}



