import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs/Rx';


@Injectable()
export class SocketProvider {

  connectionId: string;
  success: boolean;
  incomingSocketMsg: string;
  incomingSocketMsgObs: BehaviorSubject<string>;

  constructor() {
    this.connectionId = '';
    this.success = false;
    this.incomingSocketMsg = '';

    this.incomingSocketMsgObs = new BehaviorSubject(this.incomingSocketMsg);

    // Event listener for incoming messages.
    (<any>document).addEventListener(
      (<any>window).tlantic.plugins.socket.receiveHookName,
      ev => {
        this.incomingSocketMsgObs.next(ev.metadata.data);
      }
    );
  }

  getIncomingMsg() {
    return this.incomingSocketMsgObs.asObservable();
  }

  connect(host: string, port: string) {
    (<any>window).tlantic.plugins.socket.connect(
      // Success.
      connectionId => {
        this.connectionId = connectionId;
        this.success = true;
      },
      // Failure.
      d => {
          this.success = false;
      },
      host,
      port
    );
    return this.success;
  }

  disconnect() {
    (<any>window).tlantic.plugins.socket.disconnect(
      () => { this.success = true; },
      () => { this.success = false; },
      this.connectionId
    );
    return this.success;
  }

  send(data) {
    (<any>window).tlantic.plugins.socket.send(
      () => { this.success = true; },
      () => { this.success = false; },
      this.connectionId,
      {
        cl: JSON.stringify(data).length,
        c: data,
      }
    );
    return this.success;
  }

}



