import { Component, OnDestroy, HostListener } from '@angular/core';
import { NavParams, ModalController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { PeripheralConfigurationPage } from '../peripheral-configuration/peripheral-configuration';
import { ListSeletionPage } from '../list-seletion/list-seletion';
import { TaskEditorPage } from '../task-editor/task-editor';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-drying-machines',
  templateUrl: 'drying-machines.html'
})
export class DryingMachinesPage  implements OnDestroy {

  // Permissions.
  newMacEnabled: boolean = false;
  readMacEnabled: boolean = false;
  updMacEnabled: boolean = false;
  delMacEnabled: boolean = false;

  dryConfigs: Array<any> = null;
  intConfigs: Array<any> = null;
  wasConfigs: Array<any> = null;
  dryTemplate: any = null;

  dryTemplate_V2: any = null;

  dataSubs: Subscription = null;
  ready: boolean = false;
  firstConfig: boolean = true;
  status: Array<any> = [];

  laundryId: string = null;

  configEnabled: boolean = true;
  issueEnabled: boolean = true;

  storage: any = new Storage();      
  middlewareSubs: Subscription = null;  
  mwCloudSubs: Subscription = null;  
  cloudMode: boolean = false;

  constructor(private navParams: NavParams,
              private modalCtrl: ModalController,
              private backendApi: BackendApiProvider,
              private translate: TranslateService,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud) {
    // Enable/disable insert new laundry option.
    this.newMacEnabled = this.userSession.getPermission('machine-insert');
    this.updMacEnabled = this.userSession.getPermission('machine-update');
    this.delMacEnabled = this.userSession.getPermission('machine-delete');
    this.issueEnabled = this.userSession.getPermission('maintenance-insert');
    this.readMacEnabled = this.userSession.getPermission('machine-read');

    this.laundryId = this.navParams.data;

    // Handle incoming data.
    this.dataSubs = this.cs.getData().subscribe(
      res => {
        if (res.dest !== 'drying-machines') return;
        switch(res.target) {
          case 'drying-machines':
            // Store drying machine configurations.
            this.dryConfigs = res.data;
            if (this.firstConfig) {
              // Create status array.
              this.dryConfigs.forEach(el => {
                let statusObj = {
                  intId: el.config.intId,
                  channel: el.peripheral_has_machines[0].channel,
                  value: 'NOK',
                };
                this.status.push(statusObj);
              });
              this.firstConfig = false;
            } else {
              // Manage status array (remove status entry of deleted items).
              let status = [];
              this.dryConfigs.forEach(el1 => {
                let statusObj = this.status.find(el2 => (el2.intId === el1.config.intId && el2.channel === el1.peripheral_has_machines[0].channel));
                if (statusObj) status.push(statusObj);
              });
              this.status = status;
            }
            break;
          case 'washing-machines':
            // Store washing machine configurations.
            this.wasConfigs = res.data;
            break;
          case 'interfaces':
            // Store interfaces configurations.
            this.intConfigs = res.data;
            break;
        }
      }
    );

    // Get drying machine template.
    this.backendApi.getMachineTemplate('dry').subscribe(
      res => {
        this.dryTemplate = res[0];
        this.dryTemplate_V2 = res;

        this.ready = true;
      },
      err => {}
    );

    // Send configurations request.
    this.cs.setCommand({ src: 'drying-machines', dest:'laundry-configuration', cmd: 'get-dry-configs' });
    this.cs.setCommand({ src: 'drying-machines', dest:'laundry-configuration', cmd: 'get-was-configs' });
    this.cs.setCommand({ src: 'drying-machines', dest:'laundry-configuration', cmd: 'get-int-configs' });
  
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (!laundryInfo || (laundryInfo && laundryInfo.laundryId !== this.laundryId)) {
        this.cloudMode = true;
        // Subscribe to incomming packages from middleware cloud.
        this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
          pkg => {
            if (typeof pkg === 'object') {
              if (!pkg.hasOwnProperty('code')) {
                switch (pkg.op) {
                  case 'status_int':
                    // Update status array.
                    this.setStatus(pkg.dev);
                    break;
                }
              }
            }
          }
        );
      } else {
        // Handle incoming data from the vending machine CPU.
        this.middlewareSubs = this.middleware.getPkg().subscribe(
          pkg => {
            if (!pkg) return;

            if (!pkg.hasOwnProperty('code')) {
              switch (pkg.op) {
                case 'status_int':
                  // Update status array.
                  this.setStatus(pkg.dev);
                  break;
              }
            }
          }
        );
      }
      this.statusRequest();
    });
  }

  ngOnDestroy() {
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
    if (this.dataSubs) this.dataSubs.unsubscribe();
  }

  statusRequest() {
    let pkg = {
      op: 'status_int',
    };
    if (this.cloudMode) {
      // Send status request to interfaces component.
      this.middlewareCloud.send(pkg);
    } else {
      this.middleware.send(pkg);        
    }
  }

  add() {
    let modalArgs = null;
    let modalPage = null;
    let dryParams = null;
    let ports = null;
    let options = null;

    ports = this.getAvailablePorts();
    options = this.getPortOptions(ports);
    // Present error alert if there is no available ports.
    if (options.length === 0) {
      swal({
        title: this.translate.getTranslation('ALERT_NO_PORTS_TITLE'),
        text: this.translate.getTranslation('ALERT_NO_PORTS_MSG'),
        type: 'error',
        showConfirmButton: false,
        timer: 2000,
      })
      .then().catch(swal.noop);
    } else {
      dryParams = this.cf.getCopy(this.dryTemplate.data.params);

      // Add available interface channels.
      dryParams.push({
        key: 'interface-channel',
        label: 'INTERFACE_CHANNEL',
        value: '',
        options: options,
      });

      // Setup modal for drying machine type selection.
      modalArgs = {
        title: 'SELECT_DRYING_MACHINE_TITLE',
        srcPage: 'DRY_MACHINE',
        list: this.dryTemplate_V2,
        titleKey: '',
        subTitleKey: '',
        getTitle: function(obj) {
          let type = this.translate.getTranslation('TYPE');
          return `${type}: ${obj.type}`;
        },
        getSubtitle: function(obj) {
          let capacity = this.translate.getTranslation('CAPACITY');
          return `${capacity}: ${obj.capacity} Kg`;
        },
      };
      modalPage = this.modalCtrl.create(ListSeletionPage, modalArgs);
      modalPage.onDidDismiss(
        res => {
          if (!res) return;
          let selectedWM = res;

          // Setup modal for drying machine configuration.
          modalArgs = {
            params: dryParams,
            img: this.dryTemplate.data.imgPath,
            delete: this.delMacEnabled,
            update: this.updMacEnabled,
          };
          modalPage = this.modalCtrl.create(PeripheralConfigurationPage, modalArgs);
          modalPage.onDidDismiss(
            res => {
              let i = null;
              let dryConfig = null;
              let statusObj = null;
              if (!res || res.action === 'delete') return;

              // Store new configuration.
              i = options.indexOf(res.params.find(el => el.key === 'interface-channel').value);
              dryConfig = this.getDryMachineConfigs(res.params, 'insert', ports[i].channel, ports[i].id, selectedWM.programs);
              dryConfig.config.capacity = selectedWM.capacity;
              this.dryConfigs.push(dryConfig);
              statusObj = {
                intId: dryConfig.config.intId,
                channel: dryConfig.peripheral_has_machines[0].channel,
                value: 'NOK',
              }
              
              this.status.push(statusObj);
              // Send configuration
              this.cs.setData({ src:'drying-machines', dest: 'laundry-configuration', data: this.dryConfigs });
              // Send save request.
              this.save();
            }
          );
          modalPage.present();
        }
      );
      modalPage.present();
    }
  }

  configDryMachine(dryMachineConfigs) {
    // Check user permission to interface configuration.
    if (!this.readMacEnabled || !this.configEnabled) return;

    let modalArgs = null;
    let modalPage = null;
    let dryParams = this.getDryMachineParams(dryMachineConfigs);

    let port = [{
      id: dryMachineConfigs.config.intId,
      channel: dryMachineConfigs.peripheral_has_machines[0],
    }];

    let ports = null;
    let availableP = this.getAvailablePorts();
    if (availableP.find(el => (el.id === port[0].id && el.channel.channel === port[0].channel.channel))) {
      ports = availableP.filter(el => (!el.channel.hasOwnProperty('connected') || (el.channel.hasOwnProperty('connected') && !el.channel.connected)));
    } else {
      let conn = true;
      this.dryConfigs.forEach(el => {
        if (el.machineId !== dryMachineConfigs.machineId && el.config.intId === port[0].id && el.peripheral_has_machines[0].channel === port[0].channel.channel && el.peripheral_has_machines[0].connected) {
          conn = false;
        }
      });
      if (conn) {
        ports = port.concat(availableP.filter(el => (!el.channel.hasOwnProperty('connected') || (el.channel.hasOwnProperty('connected') && !el.channel.connected))));
      } else {
        ports = availableP.filter(el => (!el.channel.hasOwnProperty('connected') || (el.channel.hasOwnProperty('connected') && !el.channel.connected)));
      }
    }

    let options = this.getPortOptions(ports);

    // Add available interface channels.
    dryParams.push({
      key: 'interface-channel',
      label: 'INTERFACE_CHANNEL',
      value: options[0],
      options: options,
    });

    if (dryMachineConfigs.peripheral_has_machines[0].hasOwnProperty('connected') && !dryMachineConfigs.peripheral_has_machines[0].connected) {
      dryParams.forEach(el => {
        if (el.key === 'interface-channel') {
          el.value = '';
        }
      });
    } else {
      dryMachineConfigs.peripheral_has_machines[0].connected = true;
    }

    // Setup modal for drying machine configuration.
    modalArgs = {
      params: dryParams,
      img: this.dryTemplate.data.imgPath,
      delete: this.delMacEnabled,
      update: this.updMacEnabled,
    };
    modalPage = this.modalCtrl.create(PeripheralConfigurationPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        let i = null;
        let j = null;
        if (!res || (res.action === 'delete' && !this.delMacEnabled)) return;
        // Update new configuration.
        i = this.dryConfigs.indexOf(dryMachineConfigs);
        j = options.indexOf(res.params.find(el => el.key === 'interface-channel').value);
        this.dryConfigs[i] = this.getDryMachineConfigs(res.params, res.action, ports[j].channel, ports[j].id, null);
        this.dryConfigs[i].machineId = dryMachineConfigs.machineId;
        this.dryConfigs[i].config.capacity = dryMachineConfigs.config.capacity;

        // Interface and/or port changed (update status array).
        if (dryMachineConfigs.config.intId !== this.dryConfigs[i].config.intId ||
            dryMachineConfigs.peripheral_has_machines[0].channel !== this.dryConfigs[i].peripheral_has_machines[0].channel) {
          // Update status array.
          this.status.forEach(el => {
            if (el.intId === dryMachineConfigs.config.intId && el.channel === dryMachineConfigs.peripheral_has_machines[0].channel) {
              el.intId = this.dryConfigs[i].config.intId;
              el.channel = this.dryConfigs[i].peripheral_has_machines[0].channel;
            }
          });
        }

        this.dryConfigs[i].peripheral_has_machines[0].machine_machineId = this.dryConfigs[i].machineId;

        let int = res.params.find(el => (el.key === 'interface-channel'));
        if (int.hasOwnProperty('connected') && !int.connected) {
          this.dryConfigs[i].peripheral_has_machines[0].connected = false;
        } else {
          this.dryConfigs[i].peripheral_has_machines[0].connected = true;
        }

        // Send configuration
        this.cs.setData({ src:'drying-machines', dest: 'laundry-configuration', data: this.dryConfigs });
        this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', target: 'drying-machines', data: this.dryConfigs });

        if (res.action === 'delete') this.delete();
      }
    );
    modalPage.present();
  }

  save() {
    // Send save request.
    this.cs.setCommand({ src: 'drying-machines', dest: 'laundry-configuration', cmd: 'save' });
  }

  delete() {
    // Send delete request.
    this.cs.setCommand({ src: 'drying-machines', dest: 'laundry-configuration', cmd: 'delete' });
  }

  // Create a drying machine configuration object (format defined by the
  // backend api) based on the drying machine parameters object.
  getDryMachineConfigs(dryMachineParams, action, channel, intId, programs): any {
    let int = dryMachineParams.find(el => (el.key === 'interface-channel'));
    if (int.hasOwnProperty('connected') && !int.connected) {
      channel.channel = null;
      intId = null;
    }
    let dryMachineConfigs = {
      action: action,
      type: this.dryTemplate.type,
      laundry_laundryId: '',
      peripheral_has_machines: [channel],
      config: {
        intId: intId
      },
    };
    if (programs) {
      dryMachineConfigs['programs'] = programs.programs;
    }
    dryMachineParams.forEach(el => {
      (el.config) ? dryMachineConfigs.config[el.key] = el.value : dryMachineConfigs[el.key] = el.value;
    });
    return dryMachineConfigs;
  }

  // Create a drying machine parameters object (formated for form presentation)
  // based on the drying machine configuration object.
  getDryMachineParams(dryMachineConfigs): Array<any> {
    let dryMachineParams = this.cf.getCopy(this.dryTemplate.data.params);
    dryMachineParams.forEach(el => {
      (el.config) ? el.value = dryMachineConfigs.config[el.key] : el.value = dryMachineConfigs[el.key];
    });
    return dryMachineParams;
  }

  getAvailablePorts(): Array<any> {
    let availablePorts = [];
    this.intConfigs.forEach(int => {
      int.peripheral_has_machines.forEach(port => {
        let portObj = {};
        let isAvailable = true;

        // Check port availablility.
        if (this.wasConfigs.find(el => (el.config.intId === int.config.id && el.peripheral_has_machines[0].channel === port.channel)) ||
            this.dryConfigs.find(el => (el.config.intId === int.config.id && el.peripheral_has_machines[0].channel === port.channel))) {
          isAvailable = false;
        }

        let wasAux = this.wasConfigs.find(el => (el.config.intId === int.config.id && el.peripheral_has_machines[0].channel === port.channel));
        let dryAux = this.dryConfigs.find(el => (el.config.intId === int.config.id && el.peripheral_has_machines[0].channel === port.channel));
        if ((wasAux && wasAux.peripheral_has_machines[0].hasOwnProperty('connected') && !wasAux.peripheral_has_machines[0].connected) ||
            (dryAux && dryAux.peripheral_has_machines[0].hasOwnProperty('connected') && !dryAux.peripheral_has_machines[0].connected)) {
          isAvailable = true;
        }

        if (isAvailable) {
          portObj['id'] = int.config.id;
          portObj['channel'] = port;
          availablePorts.push(portObj);
        }
      });
    });
    return availablePorts;
  }

  getPortOptions(ports): Array<string> {
    let interfaceStr = this.translate.getTranslation('INTERFACE');
    let portStr = this.translate.getTranslation('PORT');
    let options = [];
    ports.forEach(port => {
      if (port.id && port.channel.channel) {
        let str = `${interfaceStr}: ${port.id}, ${portStr}: ${port.channel.channel}`;
        options.push(str);
      }
    });
    return options;
  }

  getStatusClass(dryMachine) {
    let status = this.status.find(el => (el.intId === dryMachine.config.intId && el.channel === dryMachine.peripheral_has_machines[0].channel));
    if (status) {
      switch(status.value) {
        case 'NOK':
          return 'machine-n-ok';
        case 'WORKING':
          return 'machine-ok';
        case 'OK':
          return 'machine-working';
      }
    } else {
      return 'machine-ok';
    }
  }

  activationRequest(dryMachine) {
    this.configEnabled = false;
    setTimeout(() => { this.configEnabled = true }, 1000);

    swal({
      title: this.translate.getTranslation('ALERT_ACTIVATION_TITLE'),
      type: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',
      confirmButtonText: this.translate.getTranslation('YES'),
      cancelButtonText: this.translate.getTranslation('NO'),
    }).then(() => {
      if (dryMachine.config.intId) {
        let pkg = {
          op: 'activate_int',
          dev: [{
            id: dryMachine.config.intId,
            chn: dryMachine.peripheral_has_machines[0].channel,
            impulses: '1',
          }],
        };
        if (this.cloudMode) {
          // Send status request to interfaces component.
          this.middlewareCloud.send(pkg);
        } else {
          this.middleware.send(pkg);        
        }
        this.backendApi.setActivationReg(this.laundryId, dryMachine.machineId).subscribe(
          res => {},
          err => {}
        );
      }
    }).catch(swal.noop);
  }

  setStatus(status) {
    let newStatusObj = null;
    let len = null;
    this.status.forEach(el1 => {
      newStatusObj = status.find(el2 => (el2.id === el1.intId));
      if (newStatusObj) {
        len = newStatusObj.status.length;

        if (newStatusObj.active === '1') {
          if (newStatusObj.status[len - Number(el1.channel)] === '1') {
            // Machine working.
            el1.value = 'WORKING';
          } else {
            // Machine idle.
            el1.value = 'OK';
          }
        } else {
          // Disconnected interface.
          el1.value = 'NOK';
        }
      }
    });
  }

  reportIssue(dryMachine) {
    this.configEnabled = false;
    let issueData = {
      laundryId: this.laundryId,
      deviceId: dryMachine.machineId,
      device: 'MACHINE',
    };
    let taskModal = this.modalCtrl.create(TaskEditorPage, issueData);
    taskModal.onDidDismiss(
      res => {
        this.configEnabled = true;
        if (!res) return;

        if (res.cmd === 'REFRESH') {
          // Do something...
        }
      }
    )
    taskModal.present();
  }

}



