import { Component, ChangeDetectorRef, OnDestroy, HostListener } from '@angular/core';
import { NavController, NavParams, ModalController, PopoverController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { WashingAppPage } from '../washing-app/washing-app';
import { DryingAppPage } from '../drying-app/drying-app';
import { BillConfirmationPage } from '../bill-confirmation/bill-confirmation';
import { NifConfirmationPage } from '../nif-confirmation/nif-confirmation';
import { BuyCardPage } from '../buy-card/buy-card';
import { RechargeCardPage } from '../recharge-card/recharge-card';
import { HelpPage } from '../help/help';
import { AlertPage } from '../alert/alert';

// Service/provider components.
import { AppSettings } from '../../providers/app-settings';
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { Orders } from '../../providers/orders';
import { Client } from '../../providers/client';
import { Middleware } from '../../providers/middleware';
import { Inactivity } from '../../providers/inactivity';
import { OfflineData } from '../../providers/offline-data';
import { Machines } from '../../providers/machines'
import { HelpTour } from '../../providers/help-tour'


@Component({
  selector: 'page-vending-app',
  templateUrl: 'vending-app.html'
})
export class VendingAppPage implements OnDestroy {


  dryMachineImgs: Array<string> = [
    'assets/img/S1.png',
    'assets/img/S2.png',
    'assets/img/S3.png',
    'assets/img/S4.png'
  ];
  wasMachineImgs: Array<string> = [
    'assets/img/L1.png',
    'assets/img/L2.png',
    'assets/img/L3.png',
  ];
  wasAnimationInd: number = 0;
  dryAnimationInd: number = 0;


  selectedTour: string = null;
  helpSubs: Subscription = null;

  wasMachineImg: string = 'assets/img/L1.png';
  dryMachineImg: string = 'assets/img/S1.png';

  cardImg: string = 'assets/img/card.png';
  cardGroupImg: string = 'assets/img/card-group.png';
  cartImg: string = 'assets/img/carrinho.png';

  smCardImg: string = 'assets/img/sm-card.png';
  smCoinsImg: string = 'assets/img/sm-coins.png';

  adminMode: boolean = false;

  storage = new Storage();
  client: Client = null;
  clientSubs: Subscription = null;
  timerSubs: Subscription = null;
  wasMachines: Array<any> = [];
  dryMachines: Array<any> = [];
  programs: Array<any> = [];
  orderCount: number = 0;
  orderCountSubs: Subscription = null;
  cmdSubs: Subscription = null;
  totalCost: number = 0.0;

  popover: any = null;
  moneyPopover: any = null;

  clientCard: boolean = false;
  orderTotal: any = null;
  orderTotalSubs: Subscription = null;

  useOfflineData: boolean = false;

  laundryId: string = null;

  middlewareSubs: Subscription = null;

  clientCardAvailable: boolean = false;


  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private appSettings: AppSettings,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private changeDetector: ChangeDetectorRef,
              private orders: Orders,
              private clientInt: Client,
              private middleware: Middleware,
              private machines: Machines,
              private inactivityTimer: Inactivity,
              private popoverCtrl: PopoverController,
              private offlineData: OfflineData,
              private help: HelpTour) {
    this.animateWasMachine();
    this.animateDryMachine();

    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        switch (pkg.op) {
          case 'has-card':
            if (pkg.code === "200") {
              this.clientCardAvailable = true; 
            } else {
              this.clientCardAvailable = false;              
            }
            break;
          case 'card-inserted':
            if (pkg.data.hasOwnProperty('admin') && pkg.data.admin === 'true') {
              this.adminMode = true;                  
            }
            break;
          case 'admin-mode':
            if (pkg.enabled === 'true') this.adminMode = true;
            break;
        }
    });

    this.adminMode = this.navParams.data.adminMode;
    this.laundryId = this.navParams.data.laundryId;

    // Check for internet connection.
    this.useOfflineData = this.offlineData.useOfflineData;

    // Subscribe to inactivity timer event.
    this.helpSubs = this.help.getStatus().subscribe(
      res => {
        if (res.status === 'OFF') this.selectedTour = null;
      }
    ); 

    // Subscribe to inactivity timer event.
    this.timerSubs = this.inactivityTimer.getInactivitySignal().subscribe(signal => {
      if (signal.state === 'INACTIVE') {
        // Release client inserted coins (if any).
        if (this.clientInt.getBalance() > 0) {
          this.balanceRequest();
        }

        // Reset client and orders data.
        this.orders.reset();
        this.clientInt.reset();

        // Go to application start page.
        this.navCtrl.popToRoot();
      }
    });

    if (!this.useOfflineData) {
      this.machines.getMachines(this.laundryId);
      this.offlineData.setWashingMachinesConfig(this.machines.getWasMachines());
      this.offlineData.setDryingMachinesConfig(this.machines.getDryMachines());
      setTimeout(() => {
        this.offlineData.setProgramsConfig(this.machines.getPrograms('WASH').concat(this.machines.getPrograms('DRY')));
        this.programs = this.machines.getPrograms('WASH').concat(this.machines.getPrograms('DRY'));
      }, 500);
    } else {
      this.wasMachines = this.offlineData.getData('wasMachines');
      this.dryMachines = this.offlineData.getData('dryMachines');
      this.programs = this.offlineData.getData('programs');
    }

    // Handle commands sent by other components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'all' && res.dest !== 'vending-app') return;

        // Handle inccoming commands from billing-info  popover.
        if (res.src === 'billing-info') {
          switch(res.cmd) {
            case 'cancel':
              let pkg = {
                op: 'cancel-orders'
              };
              this.machines.updateMachineState(pkg);
              this.orders.reset();
              break;
            case 'finish':
              this.navCtrl.push(BillConfirmationPage);
              break;
          }
        }

        if (res.src === 'money-recovery' && res.cmd === 'money-recovery') {
          // Realease money and reset vending app
          this.inactivityTimer.setInactivitySignal();
        }
      }
    );

    // Initialize client object.
    this.client = this.clientInt.client;

    if (this.client['cardNumber']) {
      this.toggleClientCard();
    }

    // Handle client updates.
    this.clientSubs = this.clientInt.getClient().subscribe(
      client => {
        this.client = client;
        if ((this.client['cardNumber'] !== null) !== this.clientCard) {
          this.toggleClientCard();
        }
        this.changeDetector.detectChanges();
      }
    );

    // Initialize order count.
    this.orderCount = this.orders.get().length;
    // Handle order count updates.
    this.orderCountSubs = this.orders.getCount().subscribe(
      count => {
        this.orderCount = count;
      }
    );

    // Initialize order price.
    this.orderTotal = this.orders.total;
    // Get total order price
    this.orderTotalSubs = this.orders.getTotalPrice().subscribe(
      totalPrice => {
        this.orderTotal = totalPrice;
      }
    );
  }

  animateWasMachine() {
    setTimeout(() => {
      if (this.wasAnimationInd === this.wasMachineImgs.length - 1) {
        this.wasAnimationInd = 0;
      } else {
        this.wasAnimationInd++;
      }
      this.wasMachineImg = this.wasMachineImgs[this.wasAnimationInd];
      this.animateWasMachine();
    }, 700);
  }
  animateDryMachine() {
    setTimeout(() => {
      if (this.dryAnimationInd === this.dryMachineImgs.length - 1) {
        this.dryAnimationInd = 0;
      } else {
        this.dryAnimationInd++;
      }
      this.dryMachineImg = this.dryMachineImgs[this.dryAnimationInd];
      this.animateDryMachine();
    }, 700);
  }

  ionViewWillEnter() {
    // Send request to check for card availability in the dispenser.
    this.checkCardsAvailability();
    this.sendStatusRequest();

    if (!this.useOfflineData) {
      this.machines.getMachines(this.laundryId);
      this.offlineData.setWashingMachinesConfig(this.machines.getWasMachines());
      this.offlineData.setDryingMachinesConfig(this.machines.getDryMachines());
      setTimeout(() => {
        this.offlineData.setProgramsConfig(this.machines.getPrograms('WASH').concat(this.machines.getPrograms('DRY')));
        this.programs = this.machines.getPrograms('WASH').concat(this.machines.getPrograms('DRY'));
      }, 500);

      this.backendApi.getLaundryInfo({ laundryId: this.laundryId }).subscribe(
        res => {
          let ownerName = null;
          let ownerNif = null;
          let ownerPhone = null;
          let ownerEmail = null;
          if (res.hasOwnProperty('userLaundries') && res.userLaundries) {
            if (res.userLaundries[0].user.hasOwnProperty('address')) {
              ownerEmail = (res.userLaundries[0].user.address.email !== '') ? res.userLaundries[0].user.address.email : null;
              ownerName = (res.userLaundries[0].user.name !== '') ? res.userLaundries[0].user.name : null;
              if (res.userLaundries[0].user.address.phoneNumber !== '') {
                ownerPhone = res.userLaundries[0].user.address.phoneNumber;
              }
              if (res.userLaundries[0].user.address.mobileNumber !== '') {
                ownerPhone = res.userLaundries[0].user.address.mobileNumber;
              }
            }
            if (res.userLaundries[0].user.nif) {
              ownerNif = res.userLaundries[0].user.nif;
            }
          }

          if (!res.obj.hasOwnProperty('autoCharge')) {
            res.obj.autoCharge = false;
          }
          this.storage.set('laundryInfo', {
            laundryId: this.laundryId,
            name: res.name,
            addr: `${res.address.addressLine1}, ${res.address.postalCode}, ${res.address.city}, ${res.address.country}`,

            ownerId: res.userLaundries[0].user_userId,

            ownerName: ownerName,
            nif: ownerNif,
            phone: ownerPhone,
            email: ownerEmail,

            autoCharge: res.obj.autoCharge,
            changeEnabled: res.obj.changeEnabled,
            minCharge: res.obj.minCharge,
            minRecharge: res.obj.minRecharge,
            pricingObj: res.obj,            
            vm: res.vendingMachines,
          });
        },
        err => {}
      );
    }
  }

  ngOnDestroy() {
    this.clientSubs.unsubscribe();
    this.orderCountSubs.unsubscribe();
    this.cmdSubs.unsubscribe();
    this.orderTotalSubs.unsubscribe();
    this.timerSubs.unsubscribe();
    if (this.helpSubs) this.helpSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    this.clickOnPage();
  }

  toggleClientCard() {
    this.clientCard = !this.clientCard;
  }

  goToWashingMenu() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (this.selectedTour === 'WASHING' || this.selectedTour === null) {
      this.help.next();

      this.wasMachines = this.machines.getWasMachines();      

      this.navCtrl.push(WashingAppPage, {
        wasMachines: this.wasMachines,
        programs: this.programs.filter(el => (el.program.type === 'WASH')),
      });
      this.selectedTour = null;
    }
  }

  goToDryingMenu() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (this.selectedTour === 'DRYING' || this.selectedTour === null) {
      this.help.next();

      this.dryMachines = this.machines.getDryMachines();

      this.navCtrl.push(DryingAppPage, {
        dryMachines: this.dryMachines,
        programs: this.programs.filter(el => (el.program.type === 'DRY')),
      });
      this.selectedTour = null;
    }
  }

  buyCard() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (!this.clientCardAvailable) {
      // Present alert (Not client card in dispenser).
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'NO_CARDS_TITLE', msg: 'NO_CARDS_MSG' });
      modalPage.onDidDismiss(res => { this.checkCardsAvailability(); });
      modalPage.present();
    } else{
      if (this.selectedTour === 'BUY_CARD' || this.selectedTour === 'BUY_CARD_ALT' || this.selectedTour === null) {
        this.help.next();
        this.navCtrl.push(BuyCardPage);
        this.selectedTour = null;
      }  
    }
  }

  rechargeCard() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    // Check if client card is inserted.
    if (this.clientInt.getCardNumber() !== null && this.clientInt.client.hasOwnProperty('admin') && !this.clientInt.client.admin) {
      if (this.selectedTour === 'RECHARGE_CARD' || this.selectedTour === 'RECHARGE_CARD_ALT' || this.selectedTour === null) {
        this.help.next();
        this.navCtrl.push(RechargeCardPage);
        this.selectedTour = null;
      }  
    } else {
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'warning-ok-btn', title: 'INSERT_CLIENT_CARD_TITLE', msg: 'INSERT_CLIENT_CARD_MSG' });
      modalPage.present();
    }
  }



tooltipRecHidden: boolean = true;
openMoneyRecovery(event) {
  if (!this.tooltipHidden) return;

  this.headerClickEnabled = false;
  setTimeout(() => { this.headerClickEnabled = true; }, 250);

  if (this.tooltipRecHidden) {
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (this.client['balance'] > 0 && laundryInfo.changeEnabled) {
        this.tooltipRecHidden = false;  
      }
    });
  } else {
    this.tooltipRecHidden = true;
  }
}
getMoney() {
  this.cs.setCommand({ src: 'money-recovery', dest: 'vending-app', cmd: 'money-recovery' });
}

tooltipHidden: boolean = true;
headerClickEnabled: boolean = true;
cartTotalPrice: number = 0.00;
cartTotalPriceCard: number = 0.00;
cartDeleteOrderImg: string = 'assets/img/remover.png';
cartCardImg: string = 'assets/img/cartao-icon.png';
cartCoinImg: string = 'assets/img/moedas-icon.png';
openShoppingCard(event) {
  if (!this.tooltipRecHidden) return;

  this.headerClickEnabled = false;
  setTimeout(() => { this.headerClickEnabled = true; }, 250);

  if (this.tooltipHidden) {
    if (this.orders.get().length > 0) {
      this.cartTotalPrice = this.orders.get().map(el => el.program['selPrice']).reduce((prevVal, el) => prevVal + Number(el), 0.00);
      this.cartTotalPriceCard = this.orders.get().map(el => el.program['selPriceCard']).reduce((prevVal, el) => prevVal + Number(el), 0.00);
      this.tooltipHidden = false;
    }
  } else {
    this.tooltipHidden = true;
  }
}
clickOnPage() {
  if (!this.tooltipHidden) this.tooltipHidden = true;
  if (!this.tooltipRecHidden) this.tooltipRecHidden = true;
}
clickOnHeader() {
  if (!this.tooltipHidden && this.headerClickEnabled) {
    this.tooltipHidden = true;
  }
  if (!this.tooltipRecHidden && this.headerClickEnabled) {
    this.tooltipRecHidden = true;
  }
}
cancel() {
  this.tooltipHidden = true;  
  this.cs.setCommand({ src: 'billing-info', dest: 'vending-app', cmd: 'cancel' });
}
finish() {
  this.tooltipHidden = true;  
  this.cs.setCommand({ src: 'billing-info', dest: 'vending-app', cmd: 'finish' });
}











  getChange(): number {
    let change = 0.0;
    let cost = 0.0;

    if (this.clientInt.client.cardNumber) {
      this.orders.orders.forEach(item => {
        cost += Number(item.program.selPriceCard);
      });
    } else {
      this.orders.orders.forEach(item => {
        cost += Number(item.program.selPrice);
      });
    }
    this.totalCost = cost;
    return Math.round((this.clientInt.client.balance - cost) * 100) / 100;
  }

  getOrderRegObj(): any {
    let obj = {
      cardNumber: this.client['cardNumber'],
      expense: true,
      priceTotal: this.totalCost,  // type number
      orders: [],
    };

    // Iterate over all orders.
    this.orders.orders.forEach(item => {
      // TODO: check for client card to switch service cost.
      obj.orders.push({
        transaction: null,
        price: item.program.selPrice,
        machine_program_machineProgramId: item.program.machineProgramId,
      });
    });
    return obj;
  }

  // Navigation bar related methods --------------------------------------------------------------
  toggleMenu() {
    // Send command to app component.
    this.cs.setCommand({ src: 'vending-app', dest: 'app', cmd: 'TOGGLE_MENU'});
  }

  setAppLanguage(selectedLang) {
    if (!this.tooltipHidden) {
      this.tooltipHidden = true;
      return;
    }
    if (!this.tooltipRecHidden) {
      this.tooltipRecHidden = true;
      return;
    }
    // Send command to app component.
    this.cs.setCommand({ src: 'vending-app', dest: 'app', cmd: 'SET_LANG', param: selectedLang });
  }

  // Reset inactivity timer upon document click event.
  @HostListener('document:click', ['$event'])
  public documentClick(event: Event): void {
    this.inactivityTimer.resetTimer();
  }

  sendStatusRequest() {
    let pkg = { op: 'status_int' };
    this.middleware.send(pkg);
  }

  checkCardsAvailability() {
    // Send change request to low level.
    let pkg =   {
      op: 'has-card',
    };
    this.middleware.send(pkg);
  }

  balanceRequest() {
    // Send change request to low level.
    let pkg =   {
      op: 'get-change',
      data: `${parseInt(Math.round(this.clientInt.getBalance()*100).toString())}`,
    };
    this.middleware.send(pkg);
  }

  getHelp() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (this.selectedTour !== null) return;
    let helpPage = this.modalCtrl.create(HelpPage);
    helpPage.onDidDismiss(
      res => {
        if (!res || (res.hasOwnProperty('confirm') && !res.confirm)) {
          this.selectedTour = null;
          return;
        }

        // Start help tour
        this.help.startTour(res.selectedTour);
        this.selectedTour = res.selectedTour;
      }
    );
    helpPage.present();
  }
}



