import { Component, ChangeDetectorRef, ViewChild, OnDestroy } from '@angular/core';
import { Platform, MenuController, ModalController, Nav } from 'ionic-angular';
import { StatusBar, Splashscreen } from 'ionic-native';
import { Network } from '@ionic-native/network';
import { Storage } from '@ionic/storage';
import { DatePipe } from '@angular/common';

import { enableProdMode } from '@angular/core';
enableProdMode();

// Page components.
import { LoginPage } from '../pages/login/login';
import { VmLoginPage } from '../pages/vm-login/vm-login';
import { StartPage } from '../pages/start/start';
import { AlertVmPage } from '../pages/alert-vm/alert-vm';
import { AlertPage } from '../pages/alert/alert';

// Service/provider components.
import { AppSettings } from '../providers/app-settings';
import { AppConfig } from '../providers/app-config';
import { BackendApiProvider } from '../providers/backend-api-provider';
import { TranslateService } from '../translate';
import { HelpTour } from '../providers/help-tour';
import { UserSession } from '../providers/user-session';
import { Middleware } from '../providers/middleware';
import { CommonServices } from '../providers/common-services';
import { OfflineData } from '../providers/offline-data';
import { Client } from '../providers/client';

import * as $ from 'jquery';

declare var swal: any;
declare var navigator: any;

@Component({
  templateUrl: 'app.html'
})
export class InvokeLaundryMachineApp implements OnDestroy {

  // SOFTWARE VERION --------------------------------------
  version: string = '2.1.0';
  // ------------------------------------------------------

  // Permissions.
  readLauEnabled: boolean = false;
  readVMEnabled: boolean = false;
  readUserEnabled: boolean = false;
  readRoleEnabled: boolean = false;

  appMenu: any = null;

  @ViewChild(Nav) nav: Nav;
  rootPage: any = StartPage;

  authenticated: boolean = false;
  rows: Array<any> = [];
  scrollbar: boolean = false;

  hopperReqAmount: number = 500;
  hooperReqSent: boolean = false;

  datePipe = new DatePipe('pt-PT');

  storage = new Storage();

  constructor(public platform: Platform,
              private network: Network,
              private menuCtrl: MenuController,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private appSettings: AppSettings,
              private appConfig: AppConfig,
              private backendApi: BackendApiProvider,
              private userSession: UserSession,
              private middleware: Middleware,
              private cs: CommonServices,
              private client: Client,
              private helpTour: HelpTour,
              private changeDetector: ChangeDetectorRef,
              private offlineData: OfflineData) {
    platform.ready().then(() => {
      // Okay, so the platform is ready and our plugins are available.
      // Here you can do any higher level native things you might need.
      StatusBar.styleDefault();
      Splashscreen.hide();

      // Save software version on localStorage
      this.storage.set('appVersion', this.version);

      // Disable swipe menu.
      this.menuCtrl.swipeEnable(false, 'menu1');

      // Setup translate object.
      translate.use(this.appConfig.getDefaultLang());  // Set default language as portuguese.

      // Establish the connection with the middleware.
      this.middleware.connect();

      // Handle incommig commands.
      this.cs.getCommand().subscribe(res => {
        if (res.dest !== 'app') return;
        switch (res.cmd) {
          case 'TOGGLE_MENU':
            this.toggleMenu();
            break;
          case 'SET_LANG':
            this.setAppLanguage(res.param.value);
            break;
          case 'LOGOUT':
            this.logout(true);
            break;
        }
      });

      if (navigator.onLine) {
        this.offlineData.setNetworkConnection(true);
      } else {
        this.offlineData.setNetworkConnection(false);
      }

      // Watch network for a disconnection.
      this.network.onDisconnect().subscribe(() => {
        // send notification.
        this.offlineData.setNetworkConnection(false);
      });
      // Watch network for a connection.
      this.network.onConnect().subscribe(() => {
        // Send notification.
        this.offlineData.setNetworkConnection(true);
      });

      // Handle incoming data from the vending machine CPU.
      this.middleware.getPkg().subscribe(
        pkg => {
          if (!pkg || !this.hooperReqSent) return;

          this.storage.get('laundryInfo').then(laundryInfo => {
            if (laundryInfo) {
              this.backendApi.setEmptyHopper(laundryInfo.laundryId, { moneyAmount: this.hopperReqAmount - Number(pkg.data) / 100 }).subscribe();
            }
          });

          if (!pkg.hasOwnProperty('code')) {
            switch (pkg.op) {
              case 'no-change':
                this.printHopperTicket(Number(pkg.data) / 100);
                this.hooperReqSent = false;
                break;
            }
          }
        }
      );
    });
  }

  menuOpened() {
    if ($('#scrollable-content').height() < $('#menu-container').height()) {
      this.scrollbar = true;

    } else {
      this.scrollbar = false;
    }
    this.changeDetector.detectChanges();
    
  }

  ngOnDestroy() {
    if (this.middleware) this.middleware.disconnect();
  }

  login() {
    if (this.client.client.admin) {

      let loginVM = this.modalCtrl.create(VmLoginPage);
      loginVM.onDidDismiss(res => {
        if (res && res.success) {
          this.readLauEnabled = this.userSession.getPermission('laundry-read');
          this.readVMEnabled = this.userSession.getPermission('vending-machine-read');
          this.readUserEnabled = this.userSession.getPermission('user-read');
          this.readUserEnabled = this.userSession.getPermission('role-read');
          this.appMenu = this.createMenu();
          this.authenticated = res.success;
        } else if (res && res.status === 'VM_CONFIG_BLOCKED') {
          swal({
            title: this.translate.getTranslation('VM_BLOCKED_TITLE'),
            text: this.translate.getTranslation('VM_BLOCKED_MSG'),
            type: 'error',
            showConfirmButton: true,
            confirmButtonText: 'OK'  
          })
          .then().catch(swal.noop);
        }
      });
      loginVM.present();
    } else {
      let login = this.modalCtrl.create(LoginPage);
      login.onDidDismiss(res => {
        if (res && res.success) {
          this.readLauEnabled = this.userSession.getPermission('laundry-read');
          this.readVMEnabled = this.userSession.getPermission('vending-machine-read');
          this.readUserEnabled = this.userSession.getPermission('user-read');
          this.readUserEnabled = this.userSession.getPermission('role-read');
          this.appMenu = this.createMenu();
          this.authenticated = res.success;
        } else if (res && res.status === 'VM_CONFIG_BLOCKED') {
          swal({
            title: this.translate.getTranslation('VM_BLOCKED_TITLE'),
            text: this.translate.getTranslation('VM_BLOCKED_MSG'),
            type: 'error',
            showConfirmButton: true,
            confirmButtonText: 'OK'  
          })
          .then().catch(swal.noop);
        }
      });
      login.present();
    }
  }

  logout(external) {
    let storage = new Storage();
    if (this.authenticated) {
      this.appConfig.setUsername('');
      this.userSession.clearSession();
      this.authenticated = false;
      this.menuCtrl.close();

      storage.get('vm_id_token').then(vmToken => {
        storage.set('id_token', vmToken);
      });
    }
    if (!external) {
      this.cs.setCommand({ src: 'app', dest: 'start', cmd: 'LOGOUT' });
    }
  }

  createMenu(): any {
    this.rows = [];
    let menu = this.appSettings.getMenu();
    for (let i = 0; i < menu.length; i++) {
      this.rows.push(i);
    }
    return menu;
  }

  toggleMenu() {
    this.authenticated ? this.menuCtrl.toggle() : this.login();
  }

  openPage(page) {
    switch(page.label) {
      case 'USER':
        this.backendApi.getUserDetails(this.userSession.id).subscribe(
          res => {
            this.nav.push(page.component, { user: res, roles: [] });
          },
          err => {}
        );
        break;
      case 'CLIENT_LIST_TITLE':
        this.nav.push(page.component, { role: 'client', title: 'CLIENT_LIST_TITLE' });
        break;
      case 'DASHBOARD':
        this.nav.push(page.component, { target: 'DASHBOARD' });
        break;
      case 'ORDER_LOG':
        this.nav.push(page.component, { target: 'ORDER_LOG' });
        break;
      case 'UPDATE':
        this.updateVmApp();
        break;
      case 'EXIT':
        this.shutdownVm();
        break;
      case 'RELOAD':
        this.storage.set('isVM', false);
        this.storage.set('id_token', null);
        this.storage.set('vm_id_token', null);
        this.storage.set('appVersion', null);
        this.storage.set('laundryInfo', null);
        location.reload(true);
        break;
      case 'LOGOUT':
        this.logout(false);
        break;
      case 'EMPTY_HOPPER':
        this.sendEmptyHopperSignal();
        break;
      default:
        this.nav.push(page.component);
    }
    if (page.label !== 'LOGOUT') {
      this.toggleMenu();
    }
  }

  sendEmptyHopperSignal() {
    let modal = this.modalCtrl.create(AlertVmPage, { type: 'hopper', title: 'ALERT_EMPTY_HOPPER_TITLE', msg: 'ALERT_EMPTY_HOPPER_MSG' });
    modal.onDidDismiss(
      res => {
        if (res) {
          let pkg = {
            op: 'get-change',
            data: `${parseInt(Math.round(this.hopperReqAmount*100).toString())}`,
          };
          this.middleware.send(pkg);
          this.hooperReqSent = true;
          setTimeout(() => { this.hooperReqSent = false; }, 5*60*1000);
        }
      }
    );
    modal.present();    
  }

  printHopperTicket(unavailMoney) {
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (laundryInfo) {
        let totalMsg = `(EUR)${this.formatPrice(this.hopperReqAmount - unavailMoney)}`;
        let ordersObj = [{
          serv: 'Recolha Total',
          price: ' ',
        }];
        let pkg =   {
          op: 'print-receipt',
          data: {
            company: {
              name: (laundryInfo.name) ? laundryInfo.name : ' ',
              ownerName: (laundryInfo.ownerName) ? laundryInfo.ownerName :' ',
              addr: (laundryInfo.addr) ? laundryInfo.addr : ' ',
              nif: (laundryInfo.nif) ? 'Nif: ' + laundryInfo.nif : ' ',
              phone: (laundryInfo.phone) ? 'Tel: ' + laundryInfo.phone : ' ',
              email: (laundryInfo.email) ? laundryInfo.email : ' ',          
            },
            orders: ordersObj,
            total: totalMsg,
            client: { name: ' ', nif: ' ' },
            credit: ' ',
            date: this.datePipe.transform(new Date(), 'dd/MM/yyyy HH:mm'),
          },
        };
        this.middleware.send(pkg);
      }
    });
  }

  formatPrice(price) {
    return price.toFixed(2);
  }

  updateVmApp() {
    let modal = this.modalCtrl.create(AlertVmPage, { type: 'update', title: 'ALERT_UPDATE_TITLE', msg: 'ALERT_UPDATE_MSG' });
    modal.present();
  }

  shutdownVm() {
    let modal = this.modalCtrl.create(AlertVmPage, { type: 'shutdown', title: 'ALERT_SHUTDOWN_TITLE', msg: 'ALERT_SHUTDOWN_MSG' });
    modal.present();
  }

  setAppLanguage(lang: string) {
    this.translate.use(lang);

    this.helpTour.cancelTour();
    setTimeout(() => { this.helpTour.initTour(); }, 500);
  }
}



