import { Injectable } from '@angular/core';
import { ToastController } from 'ionic-angular';

// Service/provider components.
import { TranslateService } from '../translate';

@Injectable()
export class CommonFunctions {

  constructor(private toastCtrl: ToastController,
              private translate: TranslateService) {
  }

  // Reshape a 1D array 'arr' into a 2D array with 'n' columns.
  reshape(arr, n): Array<any> {
    let newArr = [];
    for (let i = 0; i < arr.length; i += n) {
      newArr.push(arr.slice(i, i + n));
    }
    return newArr;
  }

  getCopy(arr): Array<any> {
    return JSON.parse(JSON.stringify(arr));
  }

  filter(arr, searchTerm, key): Array<any> {
    searchTerm = searchTerm.trim().toLowerCase();
    if (searchTerm.length > 0) {
      return arr.filter(el => el[key].toLowerCase().includes(searchTerm));
    }
    return arr;
  }

  presentWarningNotification(msg, list) {
    let message = `${this.translate.getTranslation(msg)}:`
    list.forEach((item, i) => {
      if (i >= list.length -1) {
        message += ` ${item.toString()}.`;
      } else {
        message += ` ${item.toString()},`;
      }
    });
    let toast = this.toastCtrl.create({
      message: message,
      duration: 5000,
      position: 'top',
      cssClass: 'toast-peripheral-warning',
    });
    toast.present();
  }

  presentMsgNotification(state, msg) {
    let cssClass = 'toast-success';
    if (state !== 'success') {
      cssClass = 'toast-failure';
    }
    let toast = this.toastCtrl.create({
      message: this.translate.getTranslation(msg),
      duration: 3000,
      position: 'top',
      cssClass: cssClass,
    });
    toast.present();
  }

  presentNotification(state: string) {
    let msg = 'SAVE_CONFIGURATION_SUCCESS';
    let cssClass = 'toast-success';
    if (state !== 'success') {
      msg = 'SAVE_CONFIGURATION_FAILURE';
      cssClass = 'toast-failure';
    }
    let toast = this.toastCtrl.create({
      message: this.translate.getTranslation(msg),
      duration: 3000,
      position: 'top',
      cssClass: cssClass,
    });
    toast.present();
  }
}



