import { Component, OnInit, OnDestroy, HostListener, ChangeDetectionStrategy } from '@angular/core';
import { NavController, NavParams } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';
import 'rxjs/add/observable/of';
import 'rxjs/add/operator/do';
import 'rxjs/add/operator/map';
import * as $ from 'jquery';

// Page components.
import { LaundryConfigurationPage } from '../laundry-configuration/laundry-configuration';
import { DashboardPage } from '../dashboard/dashboard';
import { OrderLogsPage } from '../order-logs/order-logs';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';


@Component({
  selector: 'page-laundries',
  templateUrl: 'laundries.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LaundriesPage {

  asyncResults: Observable<any>;
  p: number = 1;
  total: number;
  itemsPerPage: number;
  searchTerm: string = null;
  search: string = null;

  loading: boolean = true;
  noResult: boolean = true;
  gettingPage = false;

  btnEnabled: boolean = true;

  // Permissions.
  newLauEnabled: boolean = false;

  laundries: Array<any> = [];
  filteredLaundries: Array<any> = [];
  displayMode: string = 'thumbnail';
  portraitMode: boolean = false;
  csSubs: Subscription;
  laundryImg: string = "assets/img/laundry-blue.png";
  dashTarget: boolean = false;
  orderLogTarget: boolean = false;
  storage: any = new Storage();    

  tabletMode: boolean = false;

  constructor(public navCtrl: NavController,
              private navParams: NavParams,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession) {
    if (this.navParams.data.hasOwnProperty('target')) {
      switch (this.navParams.data.target) {
        case 'DASHBOARD': this.dashTarget = true; break;
        case 'ORDER_LOG': this.orderLogTarget = true; break;
      }
    }

    if (window.innerWidth < window.innerHeight) {
      this.displayMode = 'list';
      this.portraitMode = true;
    }

    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    }

    // Enable/disable insert new laundry option.
    this.newLauEnabled = this.userSession.getPermission('laundry-insert');

    this.csSubs = cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'laundries') return;
        switch (res.cmd) {
          case 'refresh':
            this.searchTerm = null;
            this.getPage(1);
            break;
        }
      }
    );
  }

  ngOnInit() {
    this.getPage(1);
  }

  getPage(page: number) {
    $('page-laundries .scroll-content').animate({ scrollTop: 0 }, "slow");

    this.gettingPage = true;
    this.asyncResults = this.backendApi.getLaundriesPage(page, this.searchTerm)
      .do(res => {
        res.rows.forEach(el => {
          let sep1 = (el.addressLine2) ? ', ': '';
          let sep2 = (el.city) ? ', ': '';
          let sep3 = (el.country) ? ', ': '';
          el['ownerName'] = '---';
          if (el.hasOwnProperty('userLaundries') && Array.isArray(el.userLaundries) && el.userLaundries.length > 0 && el.userLaundries[0].user.name && el.userLaundries[0].user.name !== '') {
            el['ownerName'] = el.userLaundries[0].user.name;            
          }
          el['vmName'] = '---';
          if (el.hasOwnProperty('vendingMachines') && Array.isArray(el.vendingMachines) && el.vendingMachines.length > 0 && el.vendingMachines[0].type && el.vendingMachines[0].type !== '') {
            el['vmName'] = el.vendingMachines[0].type;
          }
          el['address'] = el.addressLine1 + sep1 + el.addressLine2 + sep2 + el.city + ' ' + el.postalCode + sep3 + el.country;
        });

        res.rows = res.rows.sort((a, b) => {
          if (a.name.toLowerCase() > b.name.toLowerCase()) {
            return 1;
          } else {
            return -1;
          } 
        });

        if (!this.itemsPerPage) this.itemsPerPage = res.rows.length;
        this.total = res.totalPages * this.itemsPerPage;
        this.p = page;

        if (res.rows.length === 0) {
          this.noResult = true;
        } else {
          this.noResult = false;
        }
        this.loading = false;
        this.gettingPage = false;
      }, err => {
        this.gettingPage = false;
        this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
      })
      .map(res => res.rows);
  }


  ngOnDestroy() { 
    if (this.csSubs) this.csSubs.unsubscribe();
  }

  addLaundry() {
    this.navCtrl.push(LaundryConfigurationPage, { laundryConfig: { lauConfigs: null, intConfigs: null, wasConfigs: null, dryConfigs: null }});
  }

  configLaundry(laundry) {
    if (!this.btnEnabled) return;

    this.btnEnabled = false;
    if (this.navParams.data.hasOwnProperty('target')) {
      if (this.dashTarget) this.navCtrl.push(DashboardPage, { laundry: laundry });
      if (this.orderLogTarget) this.navCtrl.push(OrderLogsPage, { laundry: laundry });
      this.btnEnabled = true;      
    } else {
      let laundryObs = this.backendApi.getLaundryInfo(laundry);
      let interfacesObs = this.backendApi.getInterfacesConfigs(laundry.laundryId);
      let washingMachinesObs = this.backendApi.getMachinesConfigs(laundry.laundryId, 'wash');
      let dryingMachinesObs = this.backendApi.getMachinesConfigs(laundry.laundryId, 'dry');
      let programsObs = this.backendApi.getPrograms(laundry.laundryId);
      Observable.forkJoin([laundryObs, interfacesObs, washingMachinesObs, dryingMachinesObs, programsObs]).subscribe(
        res => {
          this.navCtrl.push(LaundryConfigurationPage, { laundryConfig: { lauConfigs: res[0], intConfigs: res[1], wasConfigs: res[2], dryConfigs: res[3], prices: res[4] }});
          this.btnEnabled = true;
        },
        err => { this.btnEnabled = true; }
      );
    }
  }


  filterResults(e) {
    if (this.search.length === 0) {
      this.searchTerm = null;
      this.getPage(1);
    }
    if (this.search.length > 2) {
      this.searchTerm = (this.search === '') ? null : this.search;
      this.getPage(1);
    }
  }

  showAllResults(clearEv) {
    if (clearEv.type === 'click') {
      this.searchTerm = null;
      this.getPage(1);
    }
  }

  @HostListener('window:resize', ['$event'])
  onResize(event) {
    if (event.target.innerWidth < event.target.innerHeight) {
      this.displayMode = 'list';
    }

    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    } else {
      this.tabletMode = false;      
    }
  }
}



