import { Injectable } from '@angular/core';
import { Subject } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';


@Injectable()
export class CommonServices {

  storage = new Storage();

  exit: Subject<any>;
  command: Subject<any>;
  data: Subject<any>;
  perConfigs: Subject<any>;

  constructor() {
    this.exit = new Subject<any>();
    this.command = new Subject<any>();
    this.data = new Subject<any>();
    this.perConfigs = new Subject<any>();
  }

  getExit() {
    return this.exit.asObservable();
  }

  setExit(obj) {
    this.exit.next(obj);
  }

  getCommand() {
    return this.command.asObservable();
  }

  setCommand(obj) {
    if (!obj.hasOwnProperty('error')) this.command.next(obj);
  }

  getData() {
    return this.data.asObservable();
  }

  setData(obj) {
    this.data.next(obj);
  }

  // Vending machine peripherals configurations stream.
  getPerConfigs() {
    return this.perConfigs.asObservable();
  }

  setPerConfigs(obj) {
    this.perConfigs.next(obj);
  }
}



