import { Injectable } from '@angular/core';
import { Subject } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';

import { BackendApiProvider } from './backend-api-provider';


@Injectable()
export class Client {

  storage = new Storage();

  client: any = {
    name: null,
    cardNumber: null,
    nif: null,
    balance: 0.00,
    balanceCard: 0.00,
    bonus: 0,
    credits: 0,
    admin: false,
    hasCard: false,
    initBalance: 0,
  };
  clientStream: Subject<any> = null;

  constructor(private backendApi: BackendApiProvider) {
    this.clientStream = new Subject<any>();
  }

  reset() {
    this.client = {
      name: null,
      cardNumber: null,
      nif: null,
      balance: 0.00,
      balanceCard: 0.00,
      bonus: 0,
      credits: 0,
      admin: false,
      hasCard: false,
      initBalance: 0,
    };
    this.setClient();
  }

  resetCardInfo() {
    let cardNumber = this.client.cardNumber;

        this.client.name = null;
        this.client.cardNumber = null;
        this.client.nif = null;
        this.client.balanceCard = 0.00;
        this.client.admin = false;
        this.client.hasCard = false;
        this.client.initBalance = 0;

    this.sendChargeResquest(cardNumber);
  }

sendChargeResquest(cardNumber) {
  this.storage.get('laundryInfo').then(laundryInfo => {
    if (laundryInfo && Array.isArray(this.client.chargedArr) && this.client.chargedArr.length > 0) {
      let body = {
        laundryId: laundryInfo.laundryId,
        cardNumber: cardNumber,
        expense: false,
        priceTotal: this.client.chargedArr.reduce((a, b) => { return a + b; }, 0),
        type: 'CHARGE_CARD',
      }
      this.backendApi.setCard(body).subscribe(
        res => {},
        err => {}
      );
    }
    this.client.bonusArr = [];
    this.client.chargedArr = [];
    this.client.moneyArr = [];
  
    this.setClient();
  });
}

  getCardNumber() {
    return this.client.cardNumber;
  }

  getBalance(): number {
    return this.client.balance;
  }

  getBalanceCard(): number {
    return this.client.balanceCard;
  }

  resetBalance() {
    this.client.balance = 0.00;
    this.client.bonus = 0;
    this.client.credits = 0;
    this.setClient();
  }

  getNif(): string {
    return this.client.nif;
  }

  setNif(nif) {
    this.client.nif = nif;
  }

  getName() {
    return this.client.name;
  }

  setName(name) {
    this.client.name = name;
  }

  addToBalance(value: number) {
    this.client.balance += value;
    if (this.client.balance < 0) this.client.balance = 0;
    this.setClient();
  }

  getClient() {
    return this.clientStream.asObservable();
  }

  setClient() {
    this.clientStream.next(this.client);
  }

  setClientInfoByCard(card) {
    let cardBalance = Number(card.balance)/100;
    if (cardBalance < 0) cardBalance = 0;

    this.client.name = card.name;
    this.client.nif = card.nif;
    this.client.cardNumber = card.cardId;
    this.client.balanceCard = cardBalance;
    this.client.admin = (card.admin === 'true');
    this.client.hasCard = true;  
    this.client.initBalance = cardBalance; 
    this.setClient();
  }
}



