import { NgModule, ErrorHandler } from '@angular/core';
import { MaterialModule } from '@angular/material';
import { Http } from '@angular/http';
import { AuthHttp, AuthConfig } from 'angular2-jwt';
import { Storage } from '@ionic/storage';
import { File } from '@ionic-native/file';
import { IonicApp, IonicModule, IonicErrorHandler } from 'ionic-angular';
import { Geolocation } from '@ionic-native/geolocation';
import { AgmCoreModule } from 'angular2-google-maps/core';
import { Network } from '@ionic-native/network';
import { DndModule } from 'ng2-dnd';
import { DragulaModule } from 'ng2-dragula';
import { Daterangepicker } from 'ng2-daterangepicker';
import {NgxPaginationModule} from 'ngx-pagination';

// Application component.
import { InvokeLaundryMachineApp } from './app.component';

// Page components.
import { LoginPage } from '../pages/login/login';
import { MachineConfigurationPage } from '../pages/machine-configuration/machine-configuration';
import { InterfacesPage } from '../pages/interfaces/interfaces';
import { WashingMachinesPage } from '../pages/washing-machines/washing-machines';
import { DryingMachinesPage } from '../pages/drying-machines/drying-machines';
import { PeripheralConfigurationPage } from '../pages/peripheral-configuration/peripheral-configuration';
import { VendingAppPage } from '../pages/vending-app/vending-app';
import { LaundriesPage } from '../pages/laundries/laundries';
import { LaundryConfigurationPage } from '../pages/laundry-configuration/laundry-configuration';
import { VendingMachineConfigurationPage } from '../pages/vending-machine-configuration/vending-machine-configuration';
