import { VendingMachinesPage } from '../pages/vending-machines/vending-machines';
import { VendingMachinePage } from '../pages/vending-machine/vending-machine';
import { VmCpusPage } from '../pages/vm-cpus/vm-cpus';
import { VmPeripheralsPage } from '../pages/vm-peripherals/vm-peripherals';
import { ListSeletionPage } from '../pages/list-seletion/list-seletion';
import { UserListPage } from '../pages/user-list/user-list';
import { UserPage } from '../pages/user/user';
import { RolePage } from '../pages/role/role';
import { RoleListPage } from '../pages/role-list/role-list';
import { PricingTablePage } from '../pages/pricing-table/pricing-table';
import { InterfaceActivationPage } from '../pages/interface-activation/interface-activation';
import { WashingAppPage } from '../pages/washing-app/washing-app';
import { DryingAppPage } from '../pages/drying-app/drying-app';
import { SelectProgramPage } from '../pages/select-program/select-program';
import { BillConfirmationPage } from '../pages/bill-confirmation/bill-confirmation';
import { NifConfirmationPage } from '../pages/nif-confirmation/nif-confirmation';
import { BuyCardPage } from '../pages/buy-card/buy-card';
import { RechargeCardPage } from '../pages/recharge-card/recharge-card';
import { StartPage } from '../pages/start/start';
import { AlertPage } from '../pages/alert/alert';
import { AlertVmPage } from '../pages/alert-vm/alert-vm';
import { TaskEditorPage } from '../pages/task-editor/task-editor';

import { DashboardPage } from '../pages/dashboard/dashboard';
import { MaintenanceBoardPage } from '../pages/maintenance-board/maintenance-board';
import { NotificationsPage } from '../pages/notifications/notifications';
import { HelpPage } from '../pages/help/help';
import { OrderLogsPage } from '../pages/order-logs/order-logs';
import { AppChargePage } from '../pages/app-charge/app-charge';
import { ReleaseChangePage } from '../pages/release-change/release-change';
import { TermsCondPage } from '../pages/terms-cond/terms-cond';
import { VmLoginPage } from '../pages/vm-login/vm-login';

// Service/provider components.
import { BackendApiProvider } from '../providers/backend-api-provider';
import { VendingMachineApiProvider } from '../providers/vending-machine-api-provider';
import { TRANSLATION_PROVIDERS, TranslatePipe, TranslateService } from '../translate';
import { CommonServices } from '../providers/common-services';
import { CommonFunctions } from '../providers/common-functions';
import { UserSession } from '../providers/user-session';
import { Orders } from '../providers/orders';
import { Client } from '../providers/client';
import { Machines } from '../providers/machines';
import { Inactivity } from '../providers/inactivity';
import { Middleware } from '../providers/middleware';
import { MiddlewareCloud } from '../providers/middleware-cloud';
import { UnsavedOrders } from '../providers/unsaved-orders';
import { ExcelGenerator } from '../providers/excel-generator';

import { AppSettings } from '../providers/app-settings';
import { AppConfig } from '../providers/app-config';
import { SocketProvider } from '../providers/socket-provider';
import { OfflineData } from '../providers/offline-data';
import { HelpTour } from '../providers/help-tour';

// Class import
import { CustomErrorHandler } from '../providers/custom-error-handler';

declare var swal: any;

let storage = new Storage();
storage.set('isVM', false);
storage.set('id_token', null);
storage.set('vm_id_token', null);

export function getAuthHttp(http) {
  return new AuthHttp(new AuthConfig({
    headerPrefix: 'Bearer',
    noJwtError: false,
    globalHeaders: [{'Accept': 'application/json'}],
    tokenGetter: (() => storage.get('id_token')),
  }), http);
}

@NgModule({
  declarations: [
    InvokeLaundryMachineApp,
    LoginPage,
    MachineConfigurationPage,
    InterfacesPage,
    WashingMachinesPage,
    DryingMachinesPage,
    PeripheralConfigurationPage,
    VendingAppPage,
    TranslatePipe,
    LaundriesPage,
    VendingMachinesPage,
    LaundryConfigurationPage,
    VendingMachineConfigurationPage,
    LaundryPage,
    VendingMachinePage,
    VmCpusPage,
    VmPeripheralsPage,
    ListSeletionPage,
    UserListPage,
    UserPage,
    RoleListPage,
    RolePage,
    PricingTablePage,
    InterfaceActivationPage,
    WashingAppPage,
    DryingAppPage,
    SelectProgramPage,
    BillConfirmationPage,
    NifConfirmationPage,
    BuyCardPage,
    RechargeCardPage,
    StartPage,
    AlertPage,
    TaskEditorPage,
    DashboardPage,
    MaintenanceBoardPage,
    NotificationsPage,
    HelpPage,
    TermsCondPage,
    OrderLogsPage,
    ReleaseChangePage,
    VmLoginPage,
    AlertVmPage,
    AppChargePage
  ],
  imports: [
    IonicModule.forRoot(InvokeLaundryMachineApp, {
      mode: 'md' // set Material Design as default styling (independently of the platform in use).
    }),
    AgmCoreModule.forRoot({ apiKey: 'AIzaSyCgl8n3Mv-cOQaUVD3ljtF_yoTTQ1unatc' }),
    MaterialModule,
    DragulaModule,
    DndModule.forRoot(),
    Daterangepicker,
    NgxPaginationModule,
  ],
  bootstrap: [IonicApp],
  entryComponents: [
    InvokeLaundryMachineApp,
    LoginPage,
    MachineConfigurationPage,
    InterfacesPage,
    WashingMachinesPage,
    DryingMachinesPage,
    PeripheralConfigurationPage,
    VendingAppPage,
    LaundriesPage,
    VendingMachinesPage,
    LaundryConfigurationPage,
    VendingMachineConfigurationPage,
    LaundryPage,
    VendingMachinePage,
    VmCpusPage,
    VmPeripheralsPage,
    ListSeletionPage,
    UserListPage,
    UserPage,
    RoleListPage,
    RolePage,
    PricingTablePage,
    InterfaceActivationPage,
    WashingAppPage,
    DryingAppPage,
    SelectProgramPage,
    BillConfirmationPage,
    NifConfirmationPage,
    BuyCardPage,
    RechargeCardPage,
    StartPage,
    AlertPage,
    DashboardPage,
    TaskEditorPage,
    MaintenanceBoardPage,
    NotificationsPage,
    HelpPage,
    TermsCondPage,
    OrderLogsPage,
    ReleaseChangePage,
    VmLoginPage,
    AlertVmPage,  
    AppChargePage
  ],
  providers: [
    Network,
    File,
    Geolocation,
    BackendApiProvider,
    VendingMachineApiProvider,
    AppSettings,
    AppConfig,
    SocketProvider,
    {provide: AuthHttp, useFactory: getAuthHttp, deps: [Http]},
    TRANSLATION_PROVIDERS,
    TranslateService,
    CommonServices,
    CommonFunctions,
    UserSession,
    Orders,
    Client,
    Machines,
    Inactivity,
    Middleware,
    MiddlewareCloud,
    OfflineData,
    HelpTour,
    UnsavedOrders,
    ExcelGenerator,
    {provide: ErrorHandler, useClass: CustomErrorHandler}
  ]
})
export class AppModule {}



