import { Component, OnDestroy } from '@angular/core';
import { NavController, NavParams, ToastController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Md5 } from 'ts-md5/dist/md5';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';

// Page components.
import { VendingMachinePage } from '../vending-machine/vending-machine';
import { VmCpusPage } from '../vm-cpus/vm-cpus';
import { VmPeripheralsPage } from '../vm-peripherals/vm-peripherals';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-vending-machine-configuration',
  templateUrl: 'vending-machine-configuration.html'
})
export class VendingMachineConfigurationPage implements OnDestroy {

  vm: any = null;
  tabs: any = null;
  newVM: boolean = false;
  vmConfigs: any = null;
  vmHash: any = null;
  cpuConfigs: any = null;
  cpuHash: any = null;
  perConfigs: any = null;
  perHash: any = null;
  leave: boolean = false;

  cmdSubs: Subscription;
  middlewareSubs: Subscription = null;
  mwCloudSubs: Subscription = null;
  perConfigsSubs: Subscription = null;
  cpuConfigsSubs: Subscription = null;

  storage: any = null;

  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private toastCtrl: ToastController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud) {
    this.vmConfigs = this.navParams.get('vmConfigs');

    // Vending machine.
    if (!this.vmConfigs) {
      this.vmConfigs = this.getVMTemplate();
      this.newVM = true;
    }
    // CPU.
    if (this.vmConfigs.vendingMachineCpus.length === 0) {
      this.cpuConfigs = this.getCPUTemplate();
    } else {
      this.cpuConfigs = this.vmConfigs.vendingMachineCpus[0];
    }
    // Peripherals.
    if (this.vmConfigs.vendingMachinePeripherals.length === 0) {
      this.perConfigs = [];
    } else {
      this.perConfigs = this.vmConfigs.vendingMachinePeripherals;
    }
    this.setTabs();

    // Save initial configuration hash.
    this.vmHash = Md5.hashAsciiStr(JSON.stringify(this.vmConfigs));
    this.cpuHash = Md5.hashAsciiStr(JSON.stringify(this.cpuConfigs));
    this.perHash = Md5.hashAsciiStr(JSON.stringify(this.perConfigs));

    // Get and handle received commands from other components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'vending-machine-configuration') return;
        switch (res.src) {
          case 'vending-machine':
            // Handle request.
            switch (res.cmd) {
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.vmConfigs.action = 'delete';
                  this.backendApi.setVendingMachine(this.vmConfigs).subscribe(
                    res => {
                      // Leave page.
                      this.leave = true;
                      if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    },
                    err => {}
                  );
                }).catch(swal.noop);
                break;
              case 'save':
                (this.vmConfigs.hasOwnProperty('vendingMachineId')) ? this.vmConfigs.action = 'update': this.vmConfigs.action = 'insert';
                this.backendApi.setVendingMachine(this.vmConfigs).subscribe(
                  res => {
                    this.cf.presentNotification('success');
                    if (res.hasOwnProperty('vendingMachineId')) {
                      this.vmConfigs = res;
                    }
                    this.getVendingMachine();
                  },
                  // TODO: Handle fetching errors.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );
                break;
            }
            break;
          case 'vm-cpus':
            // Handle request.
            switch (res.cmd) {
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.cpuConfigs.action = 'delete';
                  this.backendApi.setCPU(this.cpuConfigs, this.vmConfigs.vendingMachineId).subscribe(
                    res => {
                      // Get vending machine configurations.
                      this.getVendingMachine();
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    },
                    err => {}
                  );
                }).catch(swal.noop);
                break;
              case 'save':
                (this.cpuConfigs.hasOwnProperty('cpuId')) ? this.cpuConfigs.action = 'update': this.cpuConfigs.action = 'insert';
                this.backendApi.setCPU(this.cpuConfigs, this.vmConfigs.vendingMachineId).subscribe(
                  res => {
                    this.cf.presentNotification('success');
                    this.getVendingMachine();
                  },
                  // TODO: Handle fetching errors.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );
                break;
            }
            break;

          case 'vm-peripherals':
            // Handle request.
            switch (res.cmd) {
              case 'get-per-configs':
                this.cs.setPerConfigs({ src: 'vending-machine-configuration', dest: 'vm-peripherals', data: this.perConfigs });
                break;
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.sendPerConfigRequest(res.perConfigReq, 'DELETE');
                }).catch(swal.noop);
                break;
              case 'config-save':
                // Send config to low-level.
                this.sendPerConfigRequest(res.perConfigReq, 'SAVE');
                break;
              case 'save':
                // Send config to backend.
                this.sendPerConfigRequestBackend(res.perConfigReq);
                break;
            }
            break;
        }
      }
    );

    this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
      pkg => {
        if (typeof pkg === 'object') {
          if (!pkg.hasOwnProperty('code')) {
            switch (pkg.op) {
              case 'config_per':
                let perConfig = pkg.per.filter(item => (!item.hasOwnProperty('error')));
                let perErrors = pkg.per.filter(item => (item.hasOwnProperty('error')));
                if (perErrors.length > 0) {
                  // TODO: send notification to inform about the erros occured...
                  this.cf.presentNotification('failure');
                }
                if (perConfig.length > 0) {
                  this.sendPerConfigRequestBackend(perConfig);
                }
              break;
            }
          }
        }
      }
    );

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg.hasOwnProperty('code')) {
          switch (pkg.op) {
            case 'config_per':
              let perConfig = pkg.per.filter(item => (!item.hasOwnProperty('error')));
              let perErrors = pkg.per.filter(item => (item.hasOwnProperty('error')));
              if (perErrors.length > 0) {
                // TODO: send notification to inform about the erros occured...
                this.cf.presentNotification('failure');
              }
              if (perConfig.length > 0) {
                this.sendPerConfigRequestBackend(perConfig);
              }
              break;
          }
        }
      }
    );
  }

  setTabs() {
    this.tabs = [{
        page: VendingMachinePage,
        title: 'VENDING_MACHINE_TAB_TITLE',
        iconName: 'home',
        enabled: 'true',
      },{
        page: VmCpusPage,
        title: 'VM_CPUS_TAB_TITLE',
        iconName: 'home',
        enabled: !this.newVM,
      },{
        page: VmPeripheralsPage,
        title: 'VM_PERIPHERALS_TAB_TITLE',
        iconName: 'home',
        enabled: !this.newVM,
      }];
  }

  getVendingMachine() {
    this.backendApi.getVendingMachine(this.vmConfigs.vendingMachineId).subscribe(
      res => {
        this.vmConfigs = res[0];
        if (this.vmConfigs.vendingMachineCpus.length === 0) {
          // this.cpuConfigs = this.getCPUTemplate();
          this.clearCPU();
        } else {
          // this.cpuConfigs = this.vmConfigs.vendingMachineCpus[0];
          this.updateCPU(this.vmConfigs.vendingMachineCpus[0]);
        }
        this.perConfigs = res[0].vendingMachinePeripherals;
      },
      // TODO: Handle fetching errors.
      err => {},
      () => {
        // Enable tabs.
        if (this.newVM) {
          this.newVM = false;
          this.setTabs();
        }
        this.vmHash = Md5.hashAsciiStr(JSON.stringify(this.vmConfigs));
        this.cpuHash = Md5.hashAsciiStr(JSON.stringify(this.cpuConfigs));
        this.perHash = Md5.hashAsciiStr(JSON.stringify(this.perConfigs));
        this.cs.setPerConfigs({ src: 'vending-machine-configuration', dest: 'vm-peripherals', data: this.perConfigs });
      }
    );
  }

  getVMTemplate(): any {
    return {
      type: '',
      brand: '',
      model: '',
      serialNumber: '',
      config: {
        type: 'VENDING_MACHINE',
      },
      obs: '',
      vendingMachineCpus: [],
      vendingMachinePeripherals: [],
    }
  }

  getCPUTemplate(): any {
    return {
      type: '',
      brand: '',
      model: '',
      serialNumber: '',
      config: {
        type: 'CPU',
      },
      obs: '',
    }
  }

  clearCPU() {
    this.cpuConfigs.type = '';
    this.cpuConfigs.brand = '';
    this.cpuConfigs.model = '';
    this.cpuConfigs.serialNumber = '';
    this.cpuConfigs.obs = '';
  }

  updateCPU(newCPU) {
    this.cpuConfigs.type = newCPU.type;
    this.cpuConfigs.brand = newCPU.brand;
    this.cpuConfigs.model = newCPU.model;
    this.cpuConfigs.serialNumber = newCPU.serialNumber;
    this.cpuConfigs.obs = newCPU.obs;

  }

  hasUnsavedChanges(): boolean {
    if ( this.vmHash !== Md5.hashAsciiStr(JSON.stringify(this.vmConfigs)) ||
         this.cpuHash !== Md5.hashAsciiStr(JSON.stringify(this.cpuConfigs)) ||
         this.perHash !== Md5.hashAsciiStr(JSON.stringify(this.perConfigs))) {
      return true;
    }
    return false;
  }

  ionViewCanLeave() {
    if (!this.leave) {
      if (this.hasUnsavedChanges()) {
        return new Promise((resolve, reject) => {
          swal({
            title: this.translate.getTranslation('ALERT_UNSAVED_TITLE'),
            text: this.translate.getTranslation('ALERT_UNSAVED_MSG'),
            type: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ff1a1a',
            cancelButtonColor: 'rgb(13, 51, 72)',
            confirmButtonText: this.translate.getTranslation('YES'),
            cancelButtonText: this.translate.getTranslation('NO'),
          }).then(() => {
            let vmObs = null;
            let cpuObs = null;
            let perObs = null;
            let allObs = [];
            // Vending machine configuration.
            if (this.vmHash !== Md5.hashAsciiStr(JSON.stringify(this.vmConfigs))) {
              this.vmConfigs.action = 'update';
              vmObs = this.backendApi.setVendingMachine(this.vmConfigs);
              allObs.push(vmObs);
            }
            // CPU configuration.
            if (this.cpuHash !== Md5.hashAsciiStr(JSON.stringify(this.cpuConfigs))) {
              (this.cpuConfigs.hasOwnProperty('cpuId')) ? this.cpuConfigs.action = 'update': this.cpuConfigs.action = 'insert';
              cpuObs = this.backendApi.setCPU(this.cpuConfigs, this.vmConfigs.vendingMachineId);
              allObs.push(cpuObs);
            }
            // Peripherals configuration.
            if (this.perHash !== Md5.hashAsciiStr(JSON.stringify(this.perConfigs))) {
              perObs = this.backendApi.setPeripheralsConfigurations(this.perConfigs, this.vmConfigs.vendingMachineId);
              allObs.push(perObs);
            }
            // Send save/update all request.
            Observable.forkJoin(allObs).subscribe(
              res => {},
              // TODO: Handle fetching errors.
              err => {
                this.cf.presentNotification('failure');
              },
              () => {
                if (vmObs) {
                  this.cs.setCommand({ src: 'vending-machine-configuration', dest: 'vending-machines', cmd: 'refresh' });
                }
                swal({
                  title: this.translate.getTranslation('SAVED'),
                  text: this.translate.getTranslation('SAVED_CONFIGURATION_SUCCESS'),
                  type: 'success',
                  showConfirmButton: false,
                  timer: 2000,
                }).catch(() => {
                  swal.noop;
                  resolve();
                });
              }
            );
          }).catch(() => resolve());
        });
      }
    }
    this.cs.setCommand({ src: 'vending-machine-configuration', dest: 'vending-machines', cmd: 'refresh' });
    return new Promise((resolve, reject) => resolve());
  }

  ngOnDestroy() {
    if (this.cmdSubs) this.cmdSubs.unsubscribe();
    if (this.perConfigsSubs) this.perConfigsSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
  }

  sendPerConfigRequest(pkg, action) {
    switch (action) {
      case 'SAVE':
        // Send peripherals configuration message to low-level.
        if (this.middlewareCloud.socket) {
          this.middlewareCloud.send(pkg);
        } else {
          this.middleware.send(pkg);                                                              
        }
        break;
      case 'DELETE':
        this.sendPerConfigRequestBackend(pkg);
        break;
    }
  }

  // NOTE: THIS IS WORKING FOR CCTALK AND MDB PROTOCOLS ------------------------
  sendPerConfigRequestBackend(pkg) {
    // Update perConfigs variable
    this.perConfigs.forEach(item => {
      if (item.hasOwnProperty('action')) {
        if (item.action !== 'delete') {
          // For protocol cctalk and mdb
          if (item.config.hasOwnProperty('protocol') && (item.config.protocol === 'cctalk' || item.config.protocol === 'MDB')) {

            if (pkg.hasOwnProperty('per')) {
              let perConfig = pkg.per.find(el => (el.addr === item.config.addr));
              if (perConfig && perConfig.hasOwnProperty('perProps')) {
                item.serialNumber = perConfig.perProps.sn;
                item.brand = perConfig.perProps.brand;
                item.config.br = perConfig.perProps.brand;
                item.model = perConfig.perProps.model;  
              }
            } else {
              let perConfig = pkg.find(el => (el.addr === item.config.addr));
              if (perConfig && perConfig.hasOwnProperty('perProps')) {
                item.serialNumber = perConfig.perProps.sn;
                item.brand = perConfig.perProps.brand;
                item.config.br = perConfig.perProps.brand;
                item.model = perConfig.perProps.model;
              }
            }
          }
        }
      }
    });

    this.backendApi.setPeripheralsConfigurations(this.perConfigs, this.vmConfigs.vendingMachineId).subscribe(
      backendRes => {
        if (backendRes.result.length > 0) {
          let serialNumbers = [];
          backendRes.result.forEach((item) => {
            if (!item.insert) {
              serialNumbers.push(item.serialNumber);
            }
          });
          this.cf.presentNotification('success');
        } else {
          this.cf.presentNotification('success');
        }
        this.getVendingMachine();
      },
      err => {
        this.cf.presentNotification('failure');
      }
    );

  }

}



