import { Component } from '@angular/core';
import { NavParams } from 'ionic-angular';

import { BackendApiProvider } from '../../providers/backend-api-provider';


@Component({
  selector: 'page-notifications',
  templateUrl: 'notifications.html'
})
export class NotificationsPage {

  laundryId: any = null;

  constructor(private navParams: NavParams,
  			  private backendApi: BackendApiProvider) {
  	this.laundryId = this.navParams.data;
  	this.getNotifications();
  }

  getNotifications() {
	this.backendApi.getLaundryNotifications(this.laundryId, null).subscribe(
		res => {},
    err => {}
	);
  }

  deleteNotification() {
  	let logId = null;
  	this.backendApi.deleteLaundryNotification(logId).subscribe(
  		res => {},
      err => {}
    );
  }

}



