import { Component } from '@angular/core';
import { ViewController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { JwtHelper } from 'angular2-jwt';

import { AppConfig } from '../../providers/app-config';
import { UserSession } from '../../providers/user-session';
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonFunctions } from '../../providers/common-functions';
import { Client } from '../../providers/client';

import * as $ from 'jquery';

@Component({
  selector: 'page-vm-login',
  templateUrl: 'vm-login.html'
})
export class VmLoginPage {

  jwtHelper: any = new JwtHelper();
  storage: any = new Storage();

  cardNumber: string = null;
  userCode: string = null;
  maxCodeLength: number = 8; 


  constructor(private viewCtrl: ViewController,
              private client: Client,
              private cf: CommonFunctions,
              private appConfig: AppConfig,
              private userSession: UserSession,
              private translate: TranslateService,
              private backendApi: BackendApiProvider) {
    this.cardNumber = this.client.client.cardNumber;
  }

  ionViewDidLoad() {
    (<any>$('.modal-wrapper')).addClass('modal-wrapper-md');
  }

  keyboardEv(key) {
    if (key === 'OK') {
      this.login();
      return;
    }

    if (key === 'CLEAR') {
      this.userCode = this.userCode.slice(0, -1);
    } else {
      if (this.userCode) {
        if (this.userCode.length <= this.maxCodeLength) {
          this.userCode = this.userCode + key;        
        }
      } else {
        this.userCode = key;        
      }
    }
  }

  login() {
    this.backendApi.vmAuth(this.cardNumber, this.userCode).subscribe(
      res => {
        if (res.hasOwnProperty('success') && !res.success) {
          switch (res.msg) {
            case 'WRONG_USERCODE':
              this.userCode = null;
              this.cf.presentMsgNotification('failure', this.translate.getTranslation(res.msg));
              break;
            case 'NO_PERMISSION':
              this.userCode = null;
              this.cf.presentMsgNotification('failure', this.translate.getTranslation(res.msg));
              this.viewCtrl.dismiss({ success: true, status: 'NOK' });
              break;
            default: this.cf.presentMsgNotification('error', 'CHECK_INTERNET_CONNECTION');        
          }
        } else {
          this.appConfig.setUsername(this.jwtHelper.decodeToken(res.token).name);
          this.userSession.setSessionAttr(this.jwtHelper.decodeToken(res.token));

          this.storage.set('id_token', res.token).then(() => {
            this.backendApi.getRolesById(this.userSession.roleId).subscribe(
              res => {
                this.userSession.setPermissions(res.permissions);
                this.userSession.roleName = res.role;
  
                this.viewCtrl.dismiss({ success: true, status: 'OK' });
              },
              err => this.cf.presentMsgNotification('error', 'CHECK_INTERNET_CONNECTION')
            );
          });
        }
      },
      err => {
        if (err.hasOwnProperty('status') && err.status === 403) {
          this.viewCtrl.dismiss({ success: false, status: 'VM_CONFIG_BLOCKED' });
        } else {
          this.cf.presentMsgNotification('error', 'CHECK_INTERNET_CONNECTION');
        }
      }
    );
  }

}



