import { Component, ChangeDetectionStrategy } from '@angular/core';
import { NavParams, ViewController } from 'ionic-angular';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';
import 'rxjs/add/observable/of';
import 'rxjs/add/operator/do';
import 'rxjs/add/operator/map';
import * as $ from 'jquery';

// Service/provider components.
import { TranslateService } from '../../translate';
import { CommonFunctions } from '../../providers/common-functions';
import { BackendApiProvider } from '../../providers/backend-api-provider';


@Component({
  selector: 'page-list-seletion',
  templateUrl: 'list-seletion.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ListSeletionPage {

  asyncResults: Observable<any>;
  p: number = 1;
  total: number;
  itemsPerPage: number;
  searchTerm: string = null;
  search: string = null;

  loading: boolean = true;
  noResult: boolean = true;
  gettingPage = false;

  srcPage: string = 'DEFAULT';
  dryImg: string = 'assets/img/drying-machine.png';
  washImg: string = 'assets/img/washing-machine.jpg';

  title: string = '';
  list: Array<any> = null;
  titleKey: string = '';
  subTitleKey: string = '';

  getTitle: any = null;
  getSubtitle: any = null;

  type: string = null;

  constructor(private navParams: NavParams,
              private viewCtrl: ViewController,
              private cf: CommonFunctions,
              private backendApi: BackendApiProvider,
              private translate: TranslateService) {
    this.title = navParams.get('title');
    this.list = navParams.get('list');
    this.titleKey = navParams.get('titleKey');
    this.subTitleKey = navParams.get('subTitleKey');
    this.getTitle = navParams.get('getTitle');
    this.getSubtitle = navParams.get('getSubtitle');

    if (this.navParams.data.hasOwnProperty('srcPage')) {
      this.srcPage = navParams.get('srcPage');
    } else if (this.navParams.data.hasOwnProperty('type')) {
      this.type = navParams.get('type');
    }

    this.getPage(1);
  }

  getPage(page: number) {
    switch (this.type) {
      case 'AVAILABLE_VMS':
        this.gettingPage = true;
        this.asyncResults = this.backendApi.getAvailableVendingMachinesPage(page, this.searchTerm)
          .do(res => {
            this.list = res.rows;

            if (!this.itemsPerPage) this.itemsPerPage = res.rows.length;
            this.total = res.totalPages * this.itemsPerPage;
            this.p = page;
    
            if (res.rows.length === 0) {
              this.noResult = true;
            } else {
              this.noResult = false;
            }
            this.loading = false;
            this.gettingPage = false;
          }, err => {
            this.gettingPage = false;
            this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
          })
          .map(res => res.rows);
        break;
      case 'OWNERS':
        this.gettingPage = true;
        this.asyncResults = this.backendApi.getUsersPage(page, this.searchTerm, 'owner')
          .do(res => {
            this.list = res.rows;

            if (!this.itemsPerPage) this.itemsPerPage = res.rows.length;
            this.total = res.totalPages * this.itemsPerPage;
            this.p = page;
    
            if (res.rows.length === 0) {
              this.noResult = true;
            } else {
              this.noResult = false;
            }
            this.loading = false;
            this.gettingPage = false;
          }, err => {
            this.gettingPage = false;
            this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
          })
          .map(res => res.rows);
        break;
      }
    // $('page-laundries .scroll-content').animate({ scrollTop: 0 }, "slow");
  }

  select(item) {
    this.viewCtrl.dismiss(item);
  }

  filterResults(e) {
    if (this.search.length === 0) {
      this.searchTerm = null;
      this.getPage(1);
    }
    if (this.search.length > 2) {
      this.searchTerm = (this.search === '') ? null : this.search;
      this.getPage(1);
    }
  }

  showAllResults(clearEv) {
    if (clearEv.type === 'click') {
      this.searchTerm = null;
      this.getPage(1);
    }
  }

  cancel() {
    this.viewCtrl.dismiss();
  }

}



