import { Component, ChangeDetectorRef, OnDestroy, HostListener } from '@angular/core';
import { NavParams, ModalController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';

// Page components.
import { PeripheralConfigurationPage } from '../peripheral-configuration/peripheral-configuration';
import { InterfaceActivationPage } from '../interface-activation/interface-activation';
import { TaskEditorPage } from '../task-editor/task-editor';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;

@Component({
  selector: 'page-interfaces',
  templateUrl: 'interfaces.html'
})
export class InterfacesPage implements OnDestroy {

  // Permissions.
  readLauEnabled: boolean = false;
  updLauEnabled: boolean =false;

  browserMode: boolean = true;
  intConfigs: Array<any> = null;
  wasConfigs: Array<any> = null;
  dryConfigs: Array<any> = null;
  lauConfigs: any = null;
  intTemplate: any = null;

  dataSubs: Subscription = null;
  ready: boolean = false;
  firstConfig: boolean = true;
  status: Array<any> = [];

  configEnabled: boolean = true;
  issueEnabled: boolean = true;

  storage: any = new Storage();  
  middlewareSubs: Subscription = null;  
  mwCloudSubs: Subscription = null;  
  cloudMode: boolean = false;

  constructor(private navParams: NavParams,
              private modalCtrl: ModalController,
              private changeDetector: ChangeDetectorRef,
              private backendApi: BackendApiProvider,
              private translate: TranslateService,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud) {          
    // Enable/disable insert new laundry option.
    this.readLauEnabled = this.userSession.getPermission('laundry-read');
    this.updLauEnabled = this.userSession.getPermission('laundry-update');
    this.issueEnabled = this.userSession.getPermission('maintenance-insert');

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg || this.cloudMode) return;

        if (!pkg.hasOwnProperty('code')) {          
          switch (pkg.op) {
            case 'status_int':
              // Update status array.
              this.setStatus(pkg.dev);
              break;    
          }
        }
      }
    );

    // Subscribe to incomming packages from middleware cloud.
    this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
      pkg => {
        if (!this.cloudMode) return;

        if (typeof pkg === 'object') {
          if (!pkg.hasOwnProperty('code')) {
            switch (pkg.op) {
              case 'status_int':
                // Update status array.
                this.setStatus(pkg.dev);
                break;
            }
          }
        }
      }
    );

    // Handle incoming data.
    this.dataSubs = this.cs.getData().subscribe(
      res => {
        if (res.dest !== 'interfaces') return;
        switch(res.target) {
          case 'interfaces':
            // Store interfaces configuration.
            if (this.firstConfig) {
              // Create status array.
              res.data.forEach(el => {
                let statusObj = {
                  intId: el.laundryPeripheralId,
                  value: 'NOK',
                  addr: el.config.id,
                };
                this.status.push(statusObj);
              });
              this.firstConfig = false;
            } else {
              // Manage status array (remove status entry of deleted items).
              let status = [];
              res.data.forEach(el1 => {
                let statusObj = this.status.find(el2 => (el2.intId === el1.laundryPeripheralId));
                if (statusObj) {
                  status.push(statusObj);
                } else {
                  status.push({
                    intId: el1.laundryPeripheralId,
                    value: 'NOK',
                    addr: el1.config.id,
                  });
                }
              });
              this.status = status;
            }
            this.intConfigs = res.data;

            break;
          case 'washing-machines':
            this.wasConfigs = res.data;
            break;
          case 'drying-machines':
            this.dryConfigs = res.data;
            break;
          case 'laundry':
            this.lauConfigs = res.data;

            this.storage.get('laundryInfo').then(laundryInfo => {
              if (!laundryInfo || (laundryInfo && laundryInfo.laundryId !== this.lauConfigs.laundryId)) {
                this.cloudMode = true;
              }
            });
            break;
        }
      }
    );

    this.backendApi.getInterfaceTemplate().subscribe(
      res => {
        this.intTemplate = res[0];
        this.ready = true;
      },
      err => {}
    );

    // Send configurations requests.
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'get-int-configs' });
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'get-was-configs' });
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'get-dry-configs' });
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'get-lau-configs' });
  
    setTimeout(() => { this.statusRequest(); }, 700);    
  }

  ngOnDestroy() {
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
    if (this.dataSubs) this.dataSubs.unsubscribe();
  }

  statusRequest() {
    let pkg = {
      op: 'status_int',
    };
    if (this.cloudMode) {
      this.middlewareCloud.send(pkg);
    } else {
      this.middleware.send(pkg);        
    }
  }

  add() {
    let modalArgs = null;
    let modalPage = null;
    let intParams = this.cf.getCopy(this.intTemplate.data.params);

    // Setup modal for interfaces configuration.
    modalArgs = {
      params: intParams,
      img: this.intTemplate.data.imgPath,
      delete: this.userSession.getPermission('laundry-delete'),
      update: this.userSession.getPermission('laundry-update'),
    };
    modalPage = this.modalCtrl.create(PeripheralConfigurationPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        let intConfig = null;
        let statusObj = null;
        if (!res || res.action === 'delete') return;

        // Store new configuration.
        intConfig = this.getInterfaceConfigs(res.params, 'insert');
        this.intConfigs.push(intConfig);

        // Send configuration.
        this.cs.setData({ src: 'interfaces', dest: 'laundry-configuration', data: this.intConfigs });
        // Send save request.
        this.save(false);
      }
    );
    modalPage.present();
  }

  configInterface(interfaceConfigs) {
    // Check user permission to interface configuration.
    if (!this.readLauEnabled || !this.configEnabled) return;

    let modalArgs = null;
    let modalPage = null;
    let intParams = this.getInterfaceParams(interfaceConfigs);
    // Setup modal for interfaces configuration.
    modalArgs = {
      params: intParams,
      img: this.intTemplate.data.imgPath,
      delete: this.userSession.getPermission('laundry-delete'),
      update: this.userSession.getPermission('laundry-update'),
    };
    modalPage = this.modalCtrl.create(PeripheralConfigurationPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        let i = null;
        if (!res) return;

        // In case of delete action check if the interface has machines associated.
        if (res.action === 'delete') {
          // Check if the interfaces as machines associated.
          if (this.wasConfigs.find(el => (el.config.intId === interfaceConfigs.config.id)) ||
              this.dryConfigs.find(el => (el.config.intId === interfaceConfigs.config.id))) {
            // Present error alert if the interface has machines associated.
            swal({
              title: this.translate.getTranslation('ALERT_HAS_MACHINE_TITLE'),
              text: this.translate.getTranslation('ALERT_HAS_MACHINE_MSG'),
              type: 'error',
              showConfirmButton: false,
              timer: 2000,
            })
            .then().catch(swal.noop);
            return;
          }
        }
        // Update new configuration.
        i = this.intConfigs.indexOf(interfaceConfigs);
        this.intConfigs[i] = this.getInterfaceConfigs(res.params, res.action);
        this.intConfigs[i].laundryPeripheralId = interfaceConfigs.laundryPeripheralId;
        // Send configuration.
        this.cs.setData({ src: 'interfaces', dest:'laundry-configuration', data: this.intConfigs });
        if (res.action === 'delete') this.delete();
      }
    );
    modalPage.present();
  }

  save(toLowLevel) {
    if (toLowLevel) {
      this.configRequest();
    }
    // Send save request.
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'save' });
    this.statusRequest();
  }

  delete() {
    // Send delete request.
    this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'delete' });
  }

  // Create a interface configuration object (format defined by the
  // backend api) based on the interface parameters object.
  getInterfaceConfigs(interfaceParams, action) {
    let interfaceConfigs = {
      action: action,
      type: this.intTemplate.type,
      laundry_laundryId: '',
      peripheral_has_machines: this.intTemplate.data.channels,
      config: {
        // TODO: add this dynamically in function of the number of ports.
        active: ['1', '1'],
      },
    };
    interfaceParams.forEach(el => {
      (el.config) ? interfaceConfigs.config[el.key] = el.value : interfaceConfigs[el.key] = el.value;
    });
    return interfaceConfigs;
  }

  // Create a interface parameters object (formated for form presentation)
  // based on the interface configuration object.
  getInterfaceParams(interfaceConfigs): Array<any> {
    let interfaceParams = this.cf.getCopy(this.intTemplate.data.params);
    interfaceParams.forEach(el => {
      (el.config) ? el.value = interfaceConfigs.config[el.key] : el.value = interfaceConfigs[el.key];
    });
    return interfaceParams;
  }

  getStatusClass(interfac) {
    let status = this.status.find(el => (el.intId === interfac.laundryPeripheralId));
    if (status) {
      switch(status.value) {
        case 'NOK':
          return 'machine-n-ok';
        case 'OK':
          return 'machine-ok';
      }
    } else {
      return 'machine-n-ok';
    }
  }

  activationRequest(interfac) {
    this.configEnabled = false;
    let modalArgs = {
      ports: interfac.peripheral_has_machines,
    };
    let modalPage = this.modalCtrl.create(InterfaceActivationPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        this.configEnabled = true;
        if (!res || (res.hasOwnProperty('machine_machineId') && res.machine_machineId === null)) return;

        let pkg = {
          op: 'activate_int',
          dev: [{
            id: interfac.config.id,
            chn: res.channel,
            impulses: '1',
          }],
        };
        if (this.cloudMode) {
          this.middlewareCloud.send(pkg);
        } else {
          this.middleware.send(pkg);        
        }
        this.backendApi.setActivationReg(interfac.laundry_laundryId, res.machine_machineId).subscribe(
          res => {},
          err => {}
        );
      }
    );
    modalPage.present();
  }

  configRequest() {
    let pkg = {
      op: 'config_int',
      int: [],
    };
    this.intConfigs.forEach(el => {
      pkg.int.push({
        id: el.config.id,
        ton: el.config.ton,
        toff: el.config.toff,
        active: el.config.active,
      });
    });

    if (this.cloudMode) {
      this.middlewareCloud.send(pkg);
    } else {
      this.middleware.send(pkg); 
    }
  }

  setStatus(status) {
    let newStatusObj = null;
    this.status.forEach(el1 => {
      newStatusObj = status.find(el2 => (el2.id === el1.addr));
      if (newStatusObj) {
        (newStatusObj.active === '0') ? el1.value = 'NOK' : el1.value = 'OK';
      }
    });
  }

  reportIssue(interfac) {
    this.configEnabled = false;
    let issueData = {
      laundryId: interfac.laundry_laundryId,
      deviceId: interfac.laundryPeripheralId,
      device: 'INTERFACE',
    };
    let taskModal = this.modalCtrl.create(TaskEditorPage, issueData);
    taskModal.onDidDismiss(
      res => {
        this.configEnabled = true;
        if (!res) return;

        if (res.cmd === 'REFRESH') {
          // Do something...
        }
      }
    )
    taskModal.present();
  }

}



