import { Component, OnInit, OnDestroy } from '@angular/core';
import { NavController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';

// Page components.
import { UserListPage } from '../user-list/user-list';
import { RolePage } from '../role/role';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';


@Component({
  selector: 'page-role-list',
  templateUrl: 'role-list.html'
})
export class RoleListPage implements OnInit, OnDestroy {

  // Permissions.
  newRoleEnabled: boolean = false;
  readRoleEnabled: boolean = false;
  readUserEnabled: boolean = false;

  ready: boolean = false;
  roles: Array<any> = null;
  filteredRoles: Array<any> = null;
  csSubs: Subscription = null;

  constructor(private navCtrl: NavController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession) {
    this.newRoleEnabled = this.userSession.getPermission('role-insert');
    this.readRoleEnabled = this.userSession.getPermission('role-read');
    this.readUserEnabled = this.userSession.getPermission('user-read');
  }

  ngOnInit() {
    this.getData();
    this.csSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'role-list') return;

        switch(res.cmd) {
          case 'refresh':
            this.getData();
            break;
        }
      }
    );
  }

  ngOnDestroy() {
    this.csSubs.unsubscribe();
  }

  add() {
    this.backendApi.getRoleType().subscribe(
      res => { this.navCtrl.push(RolePage, { role: res[0] }); },
      err => {}
    );
  }

  select(role) {
    if (!this.readRoleEnabled) return;
    this.navCtrl.push(RolePage, { role: role });
  }

  goToUsers(role) {
    if (!this.readUserEnabled) return;
    this.navCtrl.push(UserListPage, { role: role.role });
  }

  getData() {
    let roles = this.backendApi.getRoles();
    let counts = this.backendApi.getRolesCount();
    Observable.forkJoin([roles, counts]).subscribe(
      res => {
        this.roles = res[0].filter(el => (el.role !== 'vending'));
        this.roles.forEach(el1 => {
          el1.count = res[1].find(el2 => (el2.roleId === el1.roleId)).count;
        });
        this.filteredRoles = res[0].filter(el => (el.role !== 'vending'));
        this.ready = true;
      },
      err => {}
    );
  }

  filterResults(ev) {
    this.filteredRoles = this.cf.filter(this.roles, ev.target.value, 'role');
  }

  showAllResults(ev) {
    if (ev.type === 'mousedown') {
      this.filteredRoles = this.roles;
    }
  }
}



