import { Component } from '@angular/core';
import { NavParams, ViewController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';

// Service/provider components.
import { TranslateService } from '../../translate';

// Sweetalert2 variable declaration.
declare var swal: any;

@Component({
  selector: 'page-peripheral-configuration',
  templateUrl: 'peripheral-configuration.html'
})
export class PeripheralConfigurationPage {

  type: string = null;
  params: Array<any> = [];
  paramsCpy = null;
  img: string = null;
  intOpt: any = null;
  delete: boolean = true;
  update: boolean = true;

  constructor(private navParams: NavParams,
              private viewCtrl: ViewController,
              private translate: TranslateService) {
    this.delete = navParams.get('delete');
    this.update = navParams.get('update');
    this.params = navParams.get('params');
    this.img = navParams.get('img');

    // Change address label
    let addrInt = this.params.find(item => (item.label === 'ADDRESS'));
    if (addrInt && addrInt.hasOwnProperty('label')) {
      addrInt.label = 'ADDRESS_INT';
    }

    this.params.forEach(item => {
      if (!item.hasOwnProperty('options')) {
        item['type'] = (item.key !== 'index' && item.key !== 'id' && item.key !== 'ton' && item.key !== 'toff' && item.key !== 'durPerImp') ? 'text' : 'number';
      }
      if (item.hasOwnProperty('label') && this.isRequired(item)) {
        item['required'] = true;
      } else {
        item['required'] = false;
      }
    });

    // Add empty interface port option.
    let intOpt = this.params.find(el => (el.key === 'interface-channel'));
    this.intOpt = Object.assign({}, intOpt);
    if (intOpt && intOpt.value !== '' && intOpt.options.length === 1) {
      intOpt.options = [this.translate.getTranslation('NOT_CONNECTED')].concat(intOpt.options);
    }

    this.params.forEach((el, i) => {
      el.id = 'per-conf-' + i;
    });
    this.paramsCpy = JSON.stringify(this.params);    
  }

  isRequired(item) {
    switch(item.label) {
      case 'NAME': return true;
      case 'SERIAL_NUMBER': return true;
      case 'ADDRESS_INT': return true;
      case 'T_ON': return true;
      case 'T_OFF': return true;
      case 'NUMBER': return true;
      case 'ACTIVATION': return true;
      case 'INTERFACE_CHANNEL': return true;
      case 'PROTOCOL': return true;
      case 'BOUD_RATE': return true;
      case 'DUR_PER_IMP': return true;
    }
    return false;
  }

  checkOptionProperty(obj) {
    return obj.hasOwnProperty('options');
  }

  checkSelectedProtocol(protocol) {
    let inputField = this.params.find(el => (el.key === 'protocol'));
    if (inputField) {
      return (inputField.value === protocol)
    } else {
      return false;
    }
  }

  checkReadOnlyInput(el, protocol) {
    let hasProtocol = false;
    protocol.forEach(item => {
      let inputField = this.params.find(el => (el.key === 'protocol'));
      if (inputField && inputField.value === item) hasProtocol = true;
    });
    if (hasProtocol) {
      switch (el.label) {
        case 'BRAND':
        case 'MODEL':
        case 'SERIAL_NUMBER':
          return true
      }
    }
    return false;
  }

  cancel() {
    this.viewCtrl.dismiss();
  }

  submit() {
    // Check if form is complete
    let protocol = this.params.find(el => (el.label === 'PROTOCOL'));
    let formOk = true;
    this.params.forEach(item => {
      if (item.hasOwnProperty('label') && (item.label === 'SERIAL_NUMBER' || item.label === 'BOUD_RATE') && protocol !== undefined && protocol.hasOwnProperty('value') && (protocol.value === 'cctalk' || protocol.value === 'MDB')) {
        item.required = false;
      }
      if (item.hasOwnProperty('required') && item.required && !item.value) {
        formOk = false;
      }
    });
    if (formOk) {
      if (this.paramsCpy === JSON.stringify(this.params)) {
        this.cancel();
      } else {
        let chn = this.params.find(el => (el.key === 'interface-channel'));

        if (chn !== undefined && chn.hasOwnProperty('value') && chn.value === this.translate.getTranslation('NOT_CONNECTED')) {
          this.params.forEach(el => {
            if ((el.key === 'interface-channel')) {
              el.options = this.intOpt.options;
              el.value = this.intOpt.value,
              el.connected = false;
            }
          });
        }
        this.viewCtrl.dismiss({
          action: 'update',
          params: this.params,
        });  
      }
    } else {
      swal({
        title: this.translate.getTranslation('INCOMPLETE_FORM_TITLE'),
        text: this.translate.getTranslation('INCOMPLETE_FORM_MSG'),
        type: 'warning',
        confirmButtonColor: 'rgb(13, 51, 72)',
        confirmButtonText: 'OK',
      }).then(() => {}).catch(swal.noop);  
    }
  }

  remove() {
    this.viewCtrl.dismiss({
      action: 'delete',
      params: this.params,
    });
  }

}



