import { Component, ViewChild, ElementRef } from '@angular/core';
import { NavParams } from 'ionic-angular';
import { Observable } from 'rxjs/Observable';
import { DatePipe } from '@angular/common';
import 'rxjs/add/observable/forkJoin';
import * as D3 from 'd3/index';
import * as moment from 'moment';
import Chart from 'chart.js';

import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { ExcelGenerator } from '../../providers/excel-generator';

@Component({
  selector: 'page-dashboard',
  templateUrl: 'dashboard.html'
})
export class DashboardPage {

  isLoading: boolean = false;

  laundryId: string = null;
  viewReady: boolean = false;
  indReady: boolean = false;

  @ViewChild('workingContainer') workingContainer: ElementRef;
  @ViewChild('profitContainer') profitContainer: ElementRef;
  @ViewChild('sellsContainer') sellsContainer: ElementRef;
  @ViewChild('utilizationContainer') utilizationContainer: ElementRef;
  @ViewChild('machineProfitCanvas') machineProfitCanvas: ElementRef;
  @ViewChild('sellsCanvas') sellsCanvas: ElementRef;
  machineProfitChart: any = null;
  laundryProfitChart: any = null;
  profitHeight = 320;
  profitWidth = 782;
  @ViewChild('purchaseMethodCanvas') purchaseMethodCanvas: ElementRef;
  purchaseMethodChart: any = null;
  @ViewChild('machineTypeCanvas') machineTypeCanvas: ElementRef;
  machineTypeChart: any = null;
  @ViewChild('machineUsageCanvas') machineUsageCanvas: ElementRef;
  machineUsageChart: any = null;
  workingHeight = 320;
  workingWidth = 782;

  datePipe = new DatePipe('pt-PT');
  dateFormat = 'dd/MM';

  mapSettings: any = {
    lat: null,
    lng: null,
    zoom: 14,
  };

  mapData: any = null;
  purchaseMethodData: any = null;
  machineUsageDistData: any = null;
  dryWorkingHoursData: any = null;
  washWorkingHoursData: any = null;
  machineProfitData: any = null;
  laundryProfitData: any = null;

  ind1: number = 0;
  ind2: number = 0;
  ind3: number = 0;
  ind4: number = 0;

  blue: string = 'rgba(33,185,196,0.5)';
  green: string = 'rgba(61,254,166,0.5)';
  pink: string = 'rgba(245,103,120,0.5)';
  orange: string = 'rgba(255,148,77,0.5)';

  bBlue: string = 'rgb(33,185,196)';
  bGreen: string = 'rgb(61,254,166)';
  bPink: string = 'rgb(245,103,120)';
  bOrange: string = 'rgb(255,148,77)';

  width: number = 0;

  startDate: any = null;
  endDate: any = null;

  hasPurchaseMethod: boolean = true;
  hasMachineUsageDist: boolean = true;
  hasMachineProfit: boolean = true;
  hasSells: boolean = true;
  hasWorkingHours: boolean = true;

  daterange: any = {};
  options: any = {};
  ranges: any = null;
  locales: any = null;

  nActivations: number = null;
  nReturns: number = null;
  nCredits: number = null;
  notReturned: number = null;

  tabletMode = false;

  constructor(private navParams: NavParams,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private excelGen: ExcelGenerator) {
    switch (this.translate.currentLang) {
      case 'pt':
        this.ranges = {
          'Hoje': [moment(), moment()],
          'Ontem': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Últimos 7 dias': [moment().subtract(6, 'days'), moment()],
          'Últimos 30 dias': [moment().subtract(29, 'days'), moment()],
          'Este mês': [moment().startOf('month'), moment().endOf('month')],
          'Mês passado': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Customizado",
          "daysOfWeek": ["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"],
          "monthNames": ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"],
        };
        break;
      case 'fr':
        this.ranges = { 
          'Aujourd\'hui': [moment(), moment()],
          'Hier': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Les 7 derniers jours': [moment().subtract(6, 'days'), moment()],
          'Les 30 derniers jours': [moment().subtract(29, 'days'), moment()],
          'Ce mois-ci': [moment().startOf('month'), moment().endOf('month')],
          'Le mois dernier': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Personnalisé",
          "daysOfWeek": ["Dim","Lun","Mar","Mer","Jeu","Ven","Sam"],
          "monthNames": ["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"],
        };
        break;
      case 'es':
        this.ranges = {
          'Hoy': [moment(), moment()],
          'Ayer': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Últimos 7 días': [moment().subtract(6, 'days'), moment()],
          'Últimos 30 días': [moment().subtract(29, 'days'), moment()],
          'Este mes': [moment().startOf('month'), moment().endOf('month')],
          'Mes passado': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Personalizado",
          "daysOfWeek": ["Dom","Lun","Mar","Mier","Jue","Vie","Sa"],
          "monthNames": ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"],
        };
        break;
      case 'en':
        this.ranges = {
          'Today': [moment(), moment()],
          'Yesterday': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Last 7 days': [moment().subtract(6, 'days'), moment()],
          'Last 30 days': [moment().subtract(29, 'days'), moment()],
          'This month': [moment().startOf('month'), moment().endOf('month')],
          'Last month': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Custom",
          "daysOfWeek": ["Su","Mo","Tu","We","Th","Fr","Sa"],
          "monthNames": ["January","February","March","April","May","June","July","August","September","October","November","December"],
        };
        break;
    }

    this.options = {
      startDate: moment().subtract(6, 'days'),
      endDate: moment(),
      locale: this.locales,
      alwaysShowCalendars: true,
      ranges: this.ranges,
      autoApply: true,
      showCustomRangeLabel: true,
      timePicker: false,
    };

    this.startDate = this.options.startDate;
    this.endDate = this.options.endDate;
    
    if (window.innerWidth <= 767) {
      this.endDate = new Date(this.endDate).toISOString();
      this.startDate = new Date(this.startDate).toISOString();
      this.tabletMode = true;
    }

    this.laundryId = this.navParams.data.laundry.laundryId;
    this.getDataset();
  }

  ionViewDidLoad() {
    this.width = this.utilizationContainer.nativeElement.clientWidth - 20;
  }

  getDataset() {
    let start = null;
    let end = null;
    if (this.startDate) start = new Date(this.startDate);
    if (this.endDate) end = new Date(this.endDate);

    let purchaseMethodObs = this.backendApi.getPaymentMethodShare(this.laundryId, start, end);
    let machineUsageDistObs = this.backendApi.getMachineUsageDist(this.laundryId, start, end);
    let machineWorkingHoursObs = this.backendApi.getMachineWorkingHours(this.laundryId, start, end);
    let machineProfitObs = this.backendApi.getmachineprofit(this.laundryId, start, end);
    let activationObs = this.backendApi.getReg(this.laundryId, 'ACTIVATION', start, end);
    let changeObs = this.backendApi.getReg(this.laundryId, 'CHANGE', start, end);
    let creditsObs = this.backendApi.getReg(this.laundryId, 'REMOTE_CREDITS', start, end);
    let userObs = this.backendApi.getUserDetails(this.navParams.data.laundry.userLaundries[0].user.userId);
    let laundryProfitObs = this.backendApi.getLaundryProfit(this.laundryId, start, end);

    this.isLoading = true;
    Observable.forkJoin([purchaseMethodObs, machineUsageDistObs, machineWorkingHoursObs, machineProfitObs, activationObs, changeObs, userObs, laundryProfitObs, creditsObs]).subscribe(
      res => {
        this.mapData = [this.navParams.data.laundry];
        this.mapData[0].laundryNif = res[6].nif;

        this.purchaseMethodData = res[0];
        this.machineUsageDistData = res[1];
        this.dryWorkingHoursData = res[2].data.filter(item => (item.type === 'DRY')).sort((a, b) => {
          if (a.name < b.name) return -1;
          if (a.name >= b.name) return 1;
        });
        this.washWorkingHoursData = res[2].data.filter(item => (item.type === 'WASH')).sort((a, b) => {
          if (a.name < b.name) return -1;
          if (a.name >= b.name) return 1;
        });
        this.machineProfitData = res[3];
        this.laundryProfitData = res[7];

        // Check for data availabilty
        this.hasPurchaseMethod = true;
        this.hasMachineUsageDist = true;
        this.hasMachineProfit = true;
        this.hasWorkingHours = true;
        this.hasSells = true;

        if (this.purchaseMethodData.hasOwnProperty('msg')) {
          this.hasPurchaseMethod = false;
        }
        if (this.dryWorkingHoursData.length === 0 && this.washWorkingHoursData.length === 0) {
          this.hasWorkingHours = false;
        }
        if (this.machineProfitData.machines.length === 0) {
          this.hasMachineProfit = false;
        }

        if (this.laundryProfitData.hasOwnProperty('profit') && Array.isArray(this.laundryProfitData.profit) && this.laundryProfitData.profit.length === 0) {
          this.hasSells = false;
        }

        if (!this.checkForUsageDistData(this.machineUsageDistData)) {
          this.hasMachineUsageDist = false;
        }

        this.nActivations = res[4].length;
        this.nReturns = 0;
        res[5].forEach(el => {
          if (el.hasOwnProperty('obj') && el.obj.hasOwnProperty('retValue')) {
            this.nReturns = this.nReturns + el.obj.retValue;
          }
        });

        this.nCredits = Number(res[0].totalInCredit);

        this.notReturned = 0;
        if (this.hasPurchaseMethod) {
          this.notReturned = this.purchaseMethodData.totalOutMoney - (this.purchaseMethodData.totalInMoney - this.purchaseMethodData.spendNoCard);
        }
        this.isLoading = false;
        this.setIndicatores();
      },
      err => { this.isLoading = false; },
      () => {
        let laundry = this.mapData.find(item => (item.laundryId === this.laundryId));
        this.mapSettings.lat = laundry.coord.coordinates[0];
        this.mapSettings.lng = laundry.coord.coordinates[1];
        this.drawDashboard();
      }
    );
  }

  setIndicatores() {
    this.indReady = true;
  }

  checkForUsageDistData(dataset) {
    let hasData = false;
    let dayKeys = ['stMonday', 'stTuesday', 'stWednesday', 'stThursday', 'stFriday', 'stSaturday', 'stSunday'];
    dayKeys.forEach(key => {
      if (dataset[key].reduce((a, b) => { return a + b }, 0) !== 0) {
        hasData = true;
      }
    });
    return hasData;
  }

  onResize($event) {
    let width = this.utilizationContainer.nativeElement.clientWidth;
    let height = (250/790)*width + 10;
    D3.select("svg").remove();
    this.drawLaundryOcupation(width, height);
    if (window.innerWidth <= 767) {
      this.endDate = new Date(this.endDate).toISOString();
      this.startDate = new Date(this.startDate).toISOString();
      this.tabletMode = true;
    } else {
      this.endDate = new Date(this.endDate);
      this.startDate = new Date(this.startDate);
      this.tabletMode = false;      
    }
  }

  drawDashboard() {
    this.drawMachineProfit();
    this.drawSells();
    this.drawPurchaseMethod();
    this.drawMachineType();
    this.drawMachineUsage();
    D3.select("svg").remove();
    this.drawLaundryOcupation(this.width, (250/790)*this.width + 10);
  }

  drawMachineProfit() {
    let colors = ['rgba(33, 185, 196, 0.5)', 'rgba(61, 254, 166, 0.5)', 'rgba(245, 103, 120, 0.5)', 'rgba(255, 148, 77, 0.5)', 'rgba(33, 185, 196, 0.5)', 'rgba(61, 254, 166, 0.5)', 'rgba(245, 103, 120, 0.5)', 'rgba(255, 148, 77, 0.5)'];
    colors = colors.concat(colors);
    let bColors = ['rgb(33, 185, 196)', 'rgb(61, 254, 166)', 'rgb(245, 103, 120)', 'rgb(255, 148, 77)', 'rgb(33, 185, 196)', 'rgb(61, 254, 166)', 'rgb(245, 103, 120)', 'rgb(255, 148, 77)'];
    bColors = bColors.concat(bColors);
    let labels = [];
    this.machineProfitData.time.forEach((item, i) => {
      if (i !== 0 && i !== this.machineProfitData.time.length - 1 && i !== Math.floor(this.machineProfitData.time.length/2)) {
        labels.push('');
      } else {
        labels.push(this.datePipe.transform(new Date(Date.parse(item)), this.dateFormat));
      }
    });
    let datasets = [];
    this.machineProfitData.machines.forEach((item, i) => {
      datasets.push({
        label: item.name,
        data: item.profit,
        borderColor: bColors[i],
        backgroundColor: colors[i],
      });
    });

    if (this.machineProfitChart) {
      this.machineProfitChart.destroy();
    }

    this.machineProfitChart = new Chart(this.machineProfitCanvas.nativeElement, {
      type: 'line',
      data: {
        labels: labels,
        datasets: datasets,
      },
      options: {
        animation : false,
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          yAxes: [{
            scaleLabel: {
              display: true,
              labelString: '€',
            }
          }]
        },
        tooltips: {
          callbacks: {
            label: (tooltipItem, data) => {
              return ` ${this.datePipe.transform(new Date(Date.parse(this.machineProfitData.time[tooltipItem.index])), this.dateFormat)}: ${data.datasets[tooltipItem.datasetIndex].data[tooltipItem.index].toFixed(2)} €`;
            }
          }
        }
      }
    });
  }

  drawSells() {
    let colors = ['rgba(33, 185, 196, 0.5)'];
    let bColors = ['rgb(33, 185, 196)'];
    let labels = [];

    this.laundryProfitData.time.forEach((item, i) => {
      if (i !== 0 && i !== this.laundryProfitData.time.length - 1 && i !== Math.floor(this.laundryProfitData.time.length/2)) {
        labels.push('');
      } else {
        labels.push(this.datePipe.transform(new Date(Date.parse(item)), this.dateFormat));
      }
    });

    let datasets = [{
      label: '',
      data: this.laundryProfitData.profit,
      borderColor: bColors[0],
      backgroundColor: colors[0],
    }];

    if (this.laundryProfitChart) {
      this.laundryProfitChart.destroy();
    }

    this.laundryProfitChart = new Chart(this.sellsCanvas.nativeElement, {
      type: 'line',
      data: {
        labels: labels,
        datasets: datasets,
      },
      options: {
        animation : false,
        responsive: true,
        maintainAspectRatio: false,
        legend: {
          display: false,
        },
        scales: {
          yAxes: [{
            scaleLabel: {
              display: true,
              labelString: '€',
            }
          }]
        },
        tooltips: {
          callbacks: {
            label: (tooltipItem, data) => {
              return ` ${this.datePipe.transform(new Date(Date.parse(this.laundryProfitData.time[tooltipItem.index])), this.dateFormat)}: ${data.datasets[tooltipItem.datasetIndex].data[tooltipItem.index].toFixed(2)} €`;
            }
          }
        }
      }
    });
  }

  drawPurchaseMethod() {
    let data = [
      this.purchaseMethodData.spendApp,
      this.purchaseMethodData.spendCard,
      this.purchaseMethodData.spendNoCard
    ];

    let labels = ['APP', 'CARD', 'MONEY'];
    labels = labels.map(item => this.translate.getTranslation(item));

    if (this.purchaseMethodChart) {
      this.purchaseMethodChart.destroy();
    }

    this.purchaseMethodChart = new Chart(this.purchaseMethodCanvas.nativeElement, {
      type: 'pie',
      data: {
        labels: labels,
        datasets: [{
          backgroundColor: [
            this.green,
            this.pink,
            this.blue,
          ],
          borderColor: [
            this.bGreen,
            this.bPink,
            this.bBlue,
          ],
          data: data,
        }]
      },
      options: {
        animation : false,
        tooltips: {
          callbacks: {
            label: (tooltipItem, data) => {
              let value = 0;
              return ` ${data.labels[tooltipItem.index]}: ${data.datasets[tooltipItem.datasetIndex].data[tooltipItem.index].toFixed(2)} €`;
            }
          }
        }
      }
    });
  }

  drawMachineType() {
    let labels = ['WASHING_DASH', 'DRYING_DASH'];
    labels = labels.map(item => this.translate.getTranslation(item));

    let dryData = 0;
    this.dryWorkingHoursData.forEach(item => {
      let workingHours = 0;
      item.programs.forEach(item => {
        workingHours += (item.operations*item.duration)/60;
      });
      dryData += workingHours;
    });

    let washData = 0;
    this.washWorkingHoursData.forEach(item => {
      let workingHours = 0;
      item.programs.forEach(item => {
        workingHours += (item.operations*item.duration)/60;
      });
      washData += workingHours;
    });

    let data = [(washData/(washData + dryData))*100, (dryData/(washData + dryData))*100];

    if (this.machineTypeChart) {
      this.machineTypeChart.destroy();
    }

    this.machineTypeChart = new Chart(this.machineTypeCanvas.nativeElement, {
      type: 'pie',
      data: {
        labels: labels,
        datasets: [{
          backgroundColor: [
            this.pink,
            this.blue,
          ],
          borderColor: [
            this.bPink,
            this.bBlue,
          ],
          data: data,
        }]
      },
      options: {
        animation : false,
        tooltips: {
          callbacks: {
            label: (tooltipItem, data) => {
              return ` ${data.labels[tooltipItem.index]}: ${data.datasets[0].data[tooltipItem.index].toFixed(2)}%`;
            }
          }
        }
      }
    });
  }

  drawMachineUsage() {
    let dryLabels = this.dryWorkingHoursData.map(item => (item.name));
    let dryData = [];
    let dryNServ = [];
    this.dryWorkingHoursData.forEach(item => {
      let workingHours = 0;
      item.programs.forEach(item => {
        if (item.type === 'WASH') {
          workingHours += (item.operations*item.duration)/60;          
        } else {
          workingHours += (item.operations*item.durPerImp)/60;          
        }
        dryNServ.push(item.operations + ' ' + this.translate.getTranslation('DRY_SERVICES'));
      });
      dryData.push(workingHours);
    });

    let washLabels = this.washWorkingHoursData.map(item => (item.name));
    let washData = [];
    let washNServ = [];
    this.washWorkingHoursData.forEach(item => {
      let workingHours = 0;
      item.programs.forEach(item => {
        workingHours += (item.operations*item.duration)/60;
        washNServ.push(item.operations + ' ' + this.translate.getTranslation('WASH_SERVICES'));
      });
      washData.push(workingHours);
    });

    let labels = dryLabels.concat(washLabels);
    let data = dryData.concat(washData);
    let nServ = dryNServ.concat(washNServ);

    if (this.machineUsageChart) {
      this.machineUsageChart.destroy();
    }

    this.machineUsageChart = new Chart(this.machineUsageCanvas.nativeElement, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          data: data,
          backgroundColor: this.blue,
          borderColor: this.bBlue,
          nServ: nServ,
        }]
      },
      options: {
        animation : false,
        responsive: true,
        maintainAspectRatio: false,
        legend: {
          display: false,
        },
        scales: {
          yAxes: [{
              display: true,
              scaleLabel: {
                display: true,
                labelString: this.translate.getTranslation('HOURS'),
              },
              ticks: {
                  beginAtZero: true,
              },
          }]
        },
        tooltips: {
          callbacks: {
            label: (tooltipItem, data) => {
              let label = data.datasets[0].data[tooltipItem.index];
              let hours = Math.floor(label);
              let min = Math.floor((label % 1)*60);
              let nServ = data.datasets[0].nServ[tooltipItem.index];
              return ` ${hours}h${min}min. (${nServ})`;
            }
          }
        }
      }
    });
  }

  drawLaundryOcupation(inWidth, inHeight) {
    let _self = this;
    let minVal = 0;
    let maxVal = 0;
    let dataset = [];
    let dayKeys = ['stMonday', 'stTuesday', 'stWednesday', 'stThursday', 'stFriday', 'stSaturday', 'stSunday'];
    Object.keys(this.machineUsageDistData).forEach(item => {
      let key = null;
      let day = null;
      switch (item) {
        case 'stMonday':
          key = item;
          day = 1;
          break;
        case 'stTuesday':
          key = item;
          day = 2;
          break;
        case 'stWednesday':
          key = item;
          day = 3;
          break;
        case 'stThursday':
          key = item;
          day = 4;
          break;
        case 'stFriday':
          key = item;
          day = 5;
          break;
        case 'stSaturday':
          key = item;
          day = 6;
          break;
        case 'stSunday':
          key = item;
          day = 7;
          break;
      }
      if (key) {
        this.machineUsageDistData[key].forEach((item, index) => {
          if (item < minVal) {
            minVal = item;
          }
          if (item > maxVal) {
            maxVal = item;
          }
          dataset.push({ day: day, hour: index + 1, value: item });
        });
      }
    });

    let margin = { top: 30, right: 0, bottom: 30, left: 30 },
        width = inWidth - margin.left - margin.right,
        height = inHeight - margin.top - margin.bottom,
        gridSize = Math.floor(width / 24),
        legendElementWidth = gridSize*2,
        buckets = 9,
        colors = ["#ffffd9","#edf8b1","#c7e9b4","#7fcdbb","#41b6c4","#1d91c0","#225ea8","#253494","#081d58"], // alternatively colorbrewer.YlGnBu[9]
        colorsLim = [],
        days = ["2ª", "3ª", "4ª", "5ª", "6ª", "Sab", "Dom"],
        times = ["00h", "01h", "02h", "03h", "04h", "05h", "06h", "07h", "08h", "09h", "10h", "11h", "12h", "13h", "14h", "15h", "16h", "17h", "18h", "19h", "20h", "21h", "22h", "23h"];
        colors.forEach((item, index) => {
          if (index === 0) { colorsLim.push(minVal); }
          else {
            if (index === colors.length - 1) { colorsLim.push(maxVal); }
            else {
              colorsLim.push((maxVal - minVal)*(index/colors.length));
            }
          }
        });

        D3.select("svg").remove();

        let svg = D3.select("#utilizationCanvas").append("svg")
              .attr("width", width + margin.left + margin.right)
              .attr("height", height + margin.top + margin.bottom)
              .append("g")
              .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

        let dayLabels = svg.selectAll(".dayLabel")
            .data(days)
            .enter().append("text")
            .text(function (d) { return d; })
            .attr("x", 0)
            .attr("y", function (d, i) { return i * gridSize; })
            .style("text-anchor", "end")
            .attr("transform", "translate(-6," + gridSize / 1.5 + ")")
            .attr("class", function (d, i) { return ((i >= 0 && i <= 4) ? "dayLabel mono axis axis-workweek" : "dayLabel mono axis axis-workweek"); });

        let timeLabels = svg.selectAll(".timeLabel")
          .data(times)
          .enter().append("text")
          .text(function(d) { return d; })
          .attr("x", function(d, i) { return i * gridSize; })
          .attr("y", 0)
          .style("text-anchor", "middle")
          .attr("transform", "translate(" + gridSize / 2 + ", -6)")
          .attr("class", function(d, i) { return ((i >= 7 && i <= 16) ? "timeLabel mono axis axis-worktime" : "timeLabel mono axis axis-worktime"); });

        let div = D3.select("#utilizationCanvas").append("div")
          .attr("class", "tooltip")
          .style("opacity", 0);

        let heatmapChart = function() {
          let data = dataset;
          let colorScale = D3.scaleQuantile()
              .domain([0, buckets - 1, D3.max(data, function (d) { return d.value; })])
              .range(colors);
          let cards = svg.selectAll(".hour")
              .data(data, function(d) {return d.day+':'+d.hour;});
          cards.append("title");
          cards.enter().append("rect")
              .attr("x", function(d) { return (d.hour - 1) * gridSize; })
              .attr("y", function(d) { return (d.day - 1) * gridSize; })
              .attr("rx", 4)
              .attr("ry", 4)
              .attr("class", "hour bordered")
              .attr("width", gridSize)
              .attr("height", gridSize)
              .style("fill", (d, i) => {
                let colorIndex = 0;
                colorsLim.forEach((item, i) => {
                  if (d.value >= item) {
                    colorIndex = i;
                  }
                });
                return colors[colorIndex];
              })
              .on("mouseover", function(d) {
                div.transition()
                  .duration(200)
                  .style("opacity", .9);
                div.html('<div>' + _self.translate.getTranslation('TOTAL') + ': ' + Math.floor(d.value) + ' ' + _self.translate.getTranslation('SERVICES') +'<div>')
                  .style("left", (D3.event.pageX) + "px")
                  .style("top", (D3.event.pageY - 50) + "px");
              })
              .on("mouseout", function(d) {
                div.transition()
                  .duration(500)
                  .style("opacity", 0);
              });;
          cards.transition().duration(1000)
              .style("fill", function(d) { return colorScale(d.value); });
          cards.select("title").text(function(d) { return d.value; });
          cards.exit().remove();
        };
      heatmapChart();
  }

  getSeconds(str) {
    let secondsTotal = 0;
    str = str.split(':');
    if (str[0] !== '00') { secondsTotal += parseInt(str[0])*3600; }
    if (str[1] !== '00') { secondsTotal += parseInt(str[1])*60; }
    if (str[2] !== '00') { secondsTotal += parseInt(str[2]) }
    return secondsTotal;
  }

  selectedDate(value, datepicker?: any) {
    datepicker.start = value.start;
    datepicker.end = value.end;
    this.daterange.start = value.start; this.startDate = value.start;
    this.daterange.end = value.end; this.endDate = value.end;
    this.daterange.label = value.label;
    this.getDataset();
  }

  dateSelected() {
    if (this.startDate && this.endDate) {
      this.getDataset();
    }
  }

  getReport() {
    if (!this.hasPurchaseMethod) return;
    let address = this.mapData[0].addressLine1 + ', ' + this.mapData[0].postalCode + ' ' + this.mapData[0].city + ', ' + this.mapData[0].country;
    let reportData = [
      { 1: 'Lavandaria' , 2: this.mapData[0].name },
      { 1: 'Proprietário', 2: this.mapData[0].userLaundries[0].user.name },
      { 1: 'Morada', 2: address },
      { 1: 'NIF', 2: this.mapData[0].laundryNif },
      { 1:'Inter. Datas' , 2: this.datePipe.transform(new Date(this.startDate), 'dd/MM/yyyy HH:mm') + ' - ' +this.datePipe.transform(new Date(this.endDate), 'dd/MM/yyyy HH:mm') },
      { 1: null, 2: null },
      { 1: 'Desembolso manual (€)', 2: this.nReturns },
      { 1: 'Crédito remoto (€)', 2: this.nCredits },
      { 1: 'Total dispendido (€)', 2: this.purchaseMethodData.totalOutMoney },
      { 1: 'Total não dispendido (€)', 2: this.notReturned },
      { 1: null, 2: null },      
      { 1: 'Nº serv. dinheiro', 2: this.purchaseMethodData.countNoCard },
      { 1: 'Nº serv. cartão', 2: this.purchaseMethodData.countCard },
      { 1: 'Nº serv. app móvel', 2: this.purchaseMethodData.countApp },
      { 1: 'Nº serv. TOTAL', 2: this.purchaseMethodData.countNoCard + this.purchaseMethodData.countCard + this.purchaseMethodData.countApp },
      { 1: null, 2: null },
      { 1: 'Nº de cartões', 2: this.purchaseMethodData.countCardSell },
      { 1: null, 2: null },
      { 1: 'Valor serv. dinheiro (€)', 2: this.purchaseMethodData.spendNoCard },
      { 1: 'Valor serv. cartão (€)', 2: this.purchaseMethodData.spendCard },
      { 1: 'Valor serv. app móvel (€)', 2: this.purchaseMethodData.spendApp },
      { 1: 'Valor serv. TOTAL (€)', 2: this.purchaseMethodData.totalSpend },
      { 1: null, 2: null },
      { 1: 'Venda de serv. (€)', 2: this.purchaseMethodData.spendNoCard },
      { 1: 'Venda de cartões (€)', 2: this.purchaseMethodData.cardSell },
      { 1: 'Carreg. de cartões (€)', 2: this.purchaseMethodData.reloadCard },
      { 1: 'Total recolha (€)', 2: this.purchaseMethodData.spendNoCard + this.purchaseMethodData.reloadCard + this.purchaseMethodData.cardSell },      
    ];
    this.excelGen.exportFile(reportData, this.mapData[0].name, this.datePipe.transform(new Date(), 'dd-MM-yyyy HH-mm'));
  }

}



