import { Component, OnDestroy } from '@angular/core';
import { NavController, NavParams, ToastController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Md5 } from 'ts-md5/dist/md5';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';

// Page components.
import { LaundryPage } from '../laundry/laundry';
import { InterfacesPage } from '../interfaces/interfaces';
import { WashingMachinesPage } from '../washing-machines/washing-machines';
import { DryingMachinesPage } from '../drying-machines/drying-machines';
import { PricingTablePage } from '../pricing-table/pricing-table';
import { NotificationsPage } from '../notifications/notifications';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { Middleware }  from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-laundry-configuration',
  templateUrl: 'laundry-configuration.html'
})
export class LaundryConfigurationPage implements OnDestroy {

  intConfigOk: boolean = false;

  // Socket related variables.
  hasVm: boolean = false;

  tabs: any = null;
  newLaundry: boolean = false;
  lauConfigs: any = null;
  lauHash: any = null;
  intConfigs: any = [];
  intHash: any = null;
  wasConfigs: any = [];
  wasHash: any = null;
  dryConfigs: any = [];
  dryHash: any = null;
  prices: any = [];
  pricesHash: any = null;
  cmdSubs: Subscription = null;
  dataSubs: Subscription = null;
  mwCloudSubs: Subscription = null;
  leave: boolean = false;
  storage: any = new Storage();

  laundryId: string = null;

  middlewareSubs: Subscription = null;

  constructor(private navCtrl: NavController,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud,
              private navParams: NavParams,
              private toastCtrl: ToastController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions) {
    let laundryConfig = this.navParams.get('laundryConfig');

    this.storage.get('laundryInfo').then(laundryInfo => {
      if (!laundryInfo || (laundryInfo && laundryConfig.lauConfigs && laundryInfo.laundryId !== laundryConfig.lauConfigs.laundryId)) {
        this.middlewareCloud.connect(this.lauConfigs.laundryId);

        // Subscribe to incomming packages from middleware cloud.
        this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
          pkg => {
            if (typeof pkg === 'object') {
              switch (pkg.op) {
                case 'activate_int':
                  if (pkg.hasOwnProperty('code') && pkg.code === '200') {
                    this.cf.presentMsgNotification('success', 'ACTIVATION_OK');
                  } else {
                    this.cf.presentMsgNotification('failure', 'ACTIVATION_NOK');
                  }
                  break;
              }
            }
          }
        );
      } else {
        // Handle incoming data from the vending machine CPU.
        this.middlewareSubs = this.middleware.getPkg().subscribe(
          pkg => {
            if (!pkg) return;

            switch (pkg.op) {
              case 'activate_int':
                if (pkg.hasOwnProperty('code') && pkg.code === '200') {
                  this.cf.presentMsgNotification('success', 'ACTIVATION_OK');
                } else {
                  this.cf.presentMsgNotification('failure', 'ACTIVATION_NOK');
                }
                break;
            }
          }
        );
      }
    });

    // Laundry.
    if (!laundryConfig.lauConfigs) {
      this.lauConfigs = this.getLaundryTemplate();
      this.newLaundry = true;
    } else {
      this.lauConfigs = laundryConfig.lauConfigs;
      this.intConfigs = laundryConfig.intConfigs.sort((a, b) => {
        if (a.config.name < b.config.name) return -1;
        if (a.config.name >= b.config.name) return 1;
      });;
      this.wasConfigs = laundryConfig.wasConfigs.sort((a, b) => {
        return a - b;
      });
      this.dryConfigs = laundryConfig.dryConfigs.sort((a, b) => {
        return a - b;
      });

      laundryConfig.prices.forEach(el => {
        if (el.hasOwnProperty('priceApp') && el.priceApp === null) el.priceApp = '0.00'; 
      });

      this.prices = laundryConfig.prices;

      if (this.lauConfigs.vendingMachines.length > 0) {
        this.hasVm = true;
      }

      this.laundryId = laundryConfig.lauConfigs.laundryId;
    }

    // NOTE: Empty vending machine.
    if (this.lauConfigs.vendingMachines.length === 0) {
      this.lauConfigs.vendingMachines[0] = {
        type: '',
        brand: '',
        model: '',
        serialNumber: '',
        obs: '',
      }
    }
    this.setTabs();
    // Save initial configuration hash.
    this.lauHash = Md5.hashAsciiStr(JSON.stringify(this.lauConfigs));
    this.intHash = Md5.hashAsciiStr(JSON.stringify(this.intConfigs));
    this.wasHash = Md5.hashAsciiStr(JSON.stringify(this.wasConfigs));
    this.dryHash = Md5.hashAsciiStr(JSON.stringify(this.dryConfigs));
    this.pricesHash = Md5.hashAsciiStr(JSON.stringify(this.prices));

    // Handle incoming data.
    this.dataSubs = this.cs.getData().subscribe(
      res => {
        if (res.dest !== 'laundry-configuration') return;
        switch(res.src) {
          case 'laundry':
            this.lauConfigs = res.data;
            break;
          case 'interfaces':
            this.intConfigs = res.data;
            break;
          case 'washing-machines':
            this.wasConfigs = res.data;
            this.updateIntActivationConfig(this.wasConfigs);
            break;
          case 'drying-machines':
            this.dryConfigs = res.data;
            this.updateIntActivationConfig(this.dryConfigs);
            break;
          case 'pricing-table':
            if (res.hasOwnProperty('target') && res.target === 'laundry') {
              this.lauConfigs = res.data;
            } else {
              this.prices = res.data;              
            }
            break;
        }
      }
    );
    // Handle commands sent by child components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        let action = '';
        if (res.dest !== 'laundry-configuration') return;
        switch (res.src) {

// ############ LAUNDRY #################
          // Command from laundry component.
          case 'laundry':
            switch (res.cmd) {
              case 'get-laundry-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'laundry', data: this.lauConfigs });
                break;
              case 'delete-vm':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  // TODO: Remove vending machine association.
                  this.backendApi.removeVMAssociation(this.lauConfigs.vendingMachines[0]).subscribe(
                    res => {
                      // Get laundry configurations.
                      this.getLaundryConfigs();
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);

                      // TODO: delete vm-token.txt?
                      this.hasVm = false;
                      this.middleware.deleteVmToken();
                    }
                  );
                }).catch(swal.noop);
                break
              case 'save':
                let action = null;
                (this.lauConfigs.hasOwnProperty('laundryId')) ? action = 'update' : action = 'create';
                if (this.lauConfigs.userLaundries[0].hasOwnProperty('user') && !this.lauConfigs.userLaundries[0].user.hasOwnProperty('userId')) {
                  swal({
                    title: 'Proprietário em Falta!',
                    text: 'Associar o proprietário da lavandaria antes de criar lavandaria.',
                    type: 'warning',
                    confirmButtonColor: 'rgb(13, 51, 72)',
                    confirmButtonText: 'OK',
                  }).then(() => {}).catch(swal.noop);
                } else {
                  this.backendApi.setLaundry(this.lauConfigs, action).subscribe(
                    res => {
                      this.cf.presentNotification('success');
                      if (action === 'create') {
                        this.lauConfigs.laundryId = res.laundry_laundryId;
                        this.newLaundry = false;
                        this.setTabs();
                      }
                      this.getLaundryConfigs();
                    },
                    err => {
                      if (!this.presentMsgError(err)) {
                        this.cf.presentNotification('failure');
                      }
                    },
                    () => {
                      this.cs.setCommand({ src: 'laundry-configuration', dest: 'laundries', cmd: 'refresh' });
                      if (!this.hasVm && this.lauConfigs.vendingMachines[0].hasOwnProperty('vendingMachineId')) {
                        this.backendApi.vmAssociateLaundry(this.lauConfigs.vendingMachines[0].vendingMachineId, this.lauConfigs.laundryId).subscribe(
                          res => {
                            if (res.hasOwnProperty('token') && res.token !== null && res.token.trim() !== '') {
                              this.middleware.saveVmToken(res.token);
                              this.hasVm = true;
                            }
                          },
                          err => {}
                        );
                      }
                    }
                  );
                }
                break;
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  // Send delete laundry request.
                  this.backendApi.setLaundry(this.lauConfigs, 'delete').subscribe(
                    res => {},
                    // TODO: handle fetching errors.
                    err => {
                      this.cf.presentNotification('failure');
                    },
                    () => {
                      this.cs.setCommand({ src: 'laundry-configuration', dest: 'laundries', cmd: 'refresh' });
                      // Leave laundry configuration page.
                      this.leave = true;
                      if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    }
                  );
                }).catch(swal.noop);
                break;
            }
            break;
// ############ LAUNDRY #################

// ############ INTERFACES #################
          case 'interfaces':
            switch(res.cmd) {
              case 'get-lau-configs':
                this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', data: this.lauConfigs, target: 'laundry' });
                break;            
              case 'get-int-configs':
                this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', data: this.intConfigs, target: 'interfaces' });
                break;
              case 'get-was-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'interfaces', data: this.wasConfigs, target: 'washing-machines' });
                break;
              case 'get-dry-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'interfaces', data: this.dryConfigs, target: 'drying-machines' });
                break;
              case 'save':




                this.intConfigs.forEach(el => {
                  if (el.laundry_laundryId === '') {
                    el.laundry_laundryId = this.lauConfigs.laundryId;
                  }
                });
                // Send update/save request.
                this.backendApi.setInterfacesConfigs(this.intConfigs).subscribe(
                  res => {
                    this.cf.presentNotification('success');

                    // Get interface configurations.
                    this.getInterfacesConfigs();
                  },
                  // TODO: handle fetching error.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );




                break;
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.backendApi.setInterfacesConfigs(this.intConfigs).subscribe(
                    res => {},
                    // TODO: handle fetching errors.
                    err => {
                      this.cf.presentNotification('failure');
                    },
                    () => {
                      // Get interfaces configurations.
                      this.getInterfacesConfigs();
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    }
                  );
                }).catch(swal.noop);
                break;
            }
            break;
// ############ INTERFACES #################

// ############ WASHING MACHINE #################
          // Command from washing-machines component.
          case 'washing-machines':
            switch(res.cmd) {
              case 'get-dry-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'washing-machines', data: this.dryConfigs, target: 'drying-machines' });
                break;
              case 'get-was-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'washing-machines', data: this.wasConfigs, target: 'washing-machines' });
                break;
              case 'get-int-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'washing-machines', data: this.intConfigs, target: 'interfaces' });
                break;
              case 'save':
                this.wasConfigs.forEach(el => {
                  if (el.laundry_laundryId === '') {
                    el.laundry_laundryId = this.lauConfigs.laundryId;
                  }
                });
                // Send update/save request.
                this.backendApi.setWashingMachinesConfigs(this.wasConfigs).subscribe(
                  res => {
                    if (res.hasOwnProperty('success') && !res.success) {
                      this.cf.presentNotification('failure');
                    } else {
                      this.cf.presentNotification('success');
                    }
                    // Get drying machine configurations.
                    this.getMachinesConfigs('wash');

                    // Save interface configurations (update activation parameter if needed...).
                    if (this.intHash !== Md5.hashAsciiStr(JSON.stringify(this.intConfigs))) {
                      this.intConfigs.forEach(el => {
                        if (el.laundry_laundryId === '') {
                          el.laundry_laundryId = this.lauConfigs.laundryId;
                        }
                      });
                      // Send update/save request.
                      this.backendApi.setInterfacesConfigs(this.intConfigs).subscribe(
                        res => {
                          // Get interface configurations.
                          this.getInterfacesConfigs();
                        },
                        err => {}
                      );
                    }

                  },
                  // TODO: handle fetching error.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );
                break;
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.backendApi.setWashingMachinesConfigs(this.wasConfigs).subscribe(
                    res => {},
                    // TODO: handle fetching errors.
                    err => {
                      this.cf.presentNotification('failure');
                    },
                    () => {
                      // Get drying machine configurations.
                      this.getMachinesConfigs('wash');
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    }
                  );
                }).catch(swal.noop);
                break;
              }
            break;
// ############ WASHING MACHINE #################

// ############ DRYING MACHINE #################
          // Command from drying-machines component.
          case 'drying-machines':
            switch(res.cmd) {
              case 'get-dry-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'drying-machines', data: this.dryConfigs, target: 'drying-machines' });
                break;
              case 'get-was-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'drying-machines', data: this.wasConfigs, target: 'washing-machines' });
                break;
              case 'get-int-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'drying-machines', data: this.intConfigs, target: 'interfaces' });
                break;
              case 'save':
                this.dryConfigs.forEach(el => {
                  if (el.laundry_laundryId === '') {
                    el.laundry_laundryId = this.lauConfigs.laundryId;
                  }
                });
                // Send update/save request.
                this.backendApi.setDryingMachinesConfigs(this.dryConfigs).subscribe(
                  res => {
                    if (res.hasOwnProperty('success') && !res.success) {
                      this.cf.presentNotification('failure');                      
                    } else {
                      this.cf.presentNotification('success');                      
                    }
                    // Get interfaces configurations.
                    this.getMachinesConfigs('dry');

                    // Save interface configurations (update activation parameter if needed...).
                    if (this.intHash !== Md5.hashAsciiStr(JSON.stringify(this.intConfigs))) {
                      // this.cs.setCommand({ src: 'interfaces', dest: 'laundry-configuration', cmd: 'save' });
                      this.intConfigs.forEach(el => {
                        if (el.laundry_laundryId === '') {
                          el.laundry_laundryId = this.lauConfigs.laundryId;
                        }
                      });
                      // Send update/save request.
                      this.backendApi.setInterfacesConfigs(this.intConfigs).subscribe(
                        res => {
                          // Get interface configurations.
                          this.getInterfacesConfigs();
                        },
                        err => {}
                      );
                    }
                  },
                  // TODO: handle fetching error.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );
                break;
              case 'delete':
                swal({
                  title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
                  text: this.translate.getTranslation('ALERT_DELETE_MSG'),
                  type: 'warning',
                  showCancelButton: true,
                  confirmButtonColor: '#ff1a1a',
                  cancelButtonColor: 'rgb(13, 51, 72)',
                  confirmButtonText: this.translate.getTranslation('YES'),
                  cancelButtonText: this.translate.getTranslation('NO'),
                }).then(() => {
                  this.backendApi.setDryingMachinesConfigs(this.dryConfigs).subscribe(
                    res => {},
                    // TODO: handle fetching errors.
                    err => {
                      this.cf.presentNotification('failure');
                    },
                    () => {
                      // Get drying machine configurations.
                      this.getMachinesConfigs('dry');
                      swal({
                        title: this.translate.getTranslation('DELETED'),
                        text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
                        type: 'success',
                        showConfirmButton: false,
                        timer: 2000,
                      }).catch(swal.noop);
                    }
                  );
                }).catch(swal.noop);
                break;
              }
            break;
// ############ DRYING MACHINE #################

// ############ PRICING TABLE #################
          case 'pricing-table':
            switch(res.cmd) {
              case 'get-laundry-configs':
                this.cs.setData({ src:'laundry-configuration', dest: 'pricing-table', data: this.lauConfigs, flag: 'laundry' });
                break;
              case 'get-prices':
                this.cs.setData({ src:'laundry-configuration', dest: 'pricing-table', data: this.prices });
                break;
              case 'save':
                this.backendApi.setPrograms(this.prices).subscribe(
                  res => {
                    this.cf.presentNotification('success');
                    // Get prices.
                    this.getPrices();
                  },
                  // TODO: handle fetching errors.
                  err => {
                    this.cf.presentNotification('failure');
                  }
                );
                this.backendApi.setLaundry(this.lauConfigs, 'update').subscribe(
                  res => {
                  this.lauHash = Md5.hashAsciiStr(JSON.stringify(this.lauConfigs));
                  },
                  err => {}
                );
                break;
              case 'save-init':
                this.getPrices();
                break;
            }
            break;
// ############ PRICING TABLE #################

        }
      }
    );
  }

  updateIntActivationConfig(machineConfigs) {
    machineConfigs.forEach(el => {
      if (el.action === 'update' || el.action === 'insert') {
        let intId = el.config.intId;
        let intPort = (el.peripheral_has_machines[0]) ? (el.peripheral_has_machines[0]).channel : null;

        if (intPort) {
          this.intConfigs.forEach(int => {
            if (int.config.id === intId) {
              let activation = null;
              (el.config.activation === 'high') ? activation = '1' : activation = '0';

              if (int.config.active[intPort-1] !== activation) {
                int.config.active[intPort-1] = activation;
                int.action = 'update';
              }
            }
          });
        }
      }
    });
  }

  getLaundryConfigs() {
    this.backendApi.getLaundryInfo(this.lauConfigs).subscribe(
      res => {
        this.lauConfigs = res;
        if (this.lauConfigs.vendingMachines.length === 0) {
          this.lauConfigs.vendingMachines[0] = {
            type: '',
            brand: '',
            model: '',
            serialNumber: '',
            obs: '',
          };
        }
      },
      err => {},
      () => {
        this.lauHash = Md5.hashAsciiStr(JSON.stringify(this.lauConfigs));
        this.cs.setData({ src: 'laundry-configuration', dest: 'laundry', data: this.lauConfigs });
      }
    );
  }

  getMachinesConfigs(type) {
    this.backendApi.getMachinesConfigs(this.lauConfigs.laundryId, type).subscribe(
      res => {
        if (type === 'wash') {
          this.wasConfigs = res.sort((a, b) => {
            return a - b;
          });
          this.cs.setData({ src:'laundry-configuration', dest: 'washing-machines', data: this.wasConfigs, target: 'washing-machines' });
          this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', target: 'washing-machines', data: this.wasConfigs });
          this.wasHash = Md5.hashAsciiStr(JSON.stringify(this.wasConfigs));
        }
        if (type === 'dry') {
          this.dryConfigs = res.sort((a, b) => {
            return a - b;
          });
          this.cs.setData({ src:'laundry-configuration', dest: 'drying-machines', data: this.dryConfigs, target: 'drying-machines' });
          this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', target: 'drying-machines', data: this.dryConfigs });
          this.dryHash = Md5.hashAsciiStr(JSON.stringify(this.dryConfigs));
        }
      },
      err => {},
      () => {
        this.getPrices();
      }
    );
  }

  getInterfacesConfigs() {
    this.backendApi.getInterfacesConfigs(this.lauConfigs.laundryId).subscribe(
      res => {
        this.intConfigs = res.sort((a, b) => {
          if (a.config.name < b.config.name) return -1;
          if (a.config.name >= b.config.name) return 1;
        });
        this.cs.setData({ src: 'laundry-configuration', dest: 'interfaces', data: this.intConfigs, target: 'interfaces' });
        this.cs.setData({ src: 'laundry-configuration', dest: 'drying-machines', data: this.intConfigs, target: 'interfaces' });
        this.cs.setData({ src: 'laundry-configuration', dest: 'washing-machines', data: this.intConfigs, target: 'interfaces' });
        this.intHash = Md5.hashAsciiStr(JSON.stringify(this.intConfigs));
      }
    );
  }

  getPrices() {
    this.backendApi.getPrograms(this.lauConfigs.laundryId).subscribe(
      res => {
        this.prices = res;

        this.prices.forEach(el => {
          if (el.hasOwnProperty('priceApp') && el.priceApp === null) el.priceApp = '0.00'; 
        });

        this.cs.setData({ src: 'laundry-configuration', dest: 'pricing-table', data: this.prices });
        this.pricesHash = Md5.hashAsciiStr(JSON.stringify(this.prices));
      },
      err => {}
    );
  }

  ngOnDestroy() {
    if (this.cmdSubs) this.cmdSubs.unsubscribe();
    if (this.dataSubs) this.dataSubs.unsubscribe();
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    this.middlewareCloud.disconnect();
  }

  hasUnsavedChanges(): boolean {
    if (this.lauHash !== Md5.hashAsciiStr(JSON.stringify(this.lauConfigs)) ||
        this.intHash !== Md5.hashAsciiStr(JSON.stringify(this.intConfigs)) ||
        this.pricesHash !== Md5.hashAsciiStr(JSON.stringify(this.prices))
        ) {
      return true;
    }
    return false;
  }

  ionViewCanLeave() {
    if (!this.leave) {
      if (this.hasUnsavedChanges()) {
        return new Promise((resolve, reject) => {
          swal({
            title: this.translate.getTranslation('ALERT_UNSAVED_TITLE'),
            text: this.translate.getTranslation('ALERT_UNSAVED_MSG'),
            type: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#ff1a1a',
            cancelButtonColor: 'rgb(13, 51, 72)',
            confirmButtonText: this.translate.getTranslation('YES'),
            cancelButtonText: this.translate.getTranslation('NO'),
          }).then(() => {
            let action = null;
            let laundryObs = null;
            let interfaceObs = null;
            let washingMachinesObs = null;
            let dryingMachineObs = null;
            let pricesObs = null;
            let allObs = [];
            // Laundry configuration.
            if (this.lauHash !== Md5.hashAsciiStr(JSON.stringify(this.lauConfigs))) {
              (this.lauConfigs.hasOwnProperty('laundryId')) ? action = 'update' : action = 'create';
              laundryObs = this.backendApi.setLaundry(this.lauConfigs, action);
              allObs.push(laundryObs);
            }
            if (action === 'create') {
              // Send create laundry request.
              laundryObs.subscribe(
                res => {
                  this.cs.setCommand({ src: 'laundry-configuration', dest: 'laundries', cmd: 'refresh' });
                },
                // TODO: handle fetching errors.
                err => this.cf.presentNotification('failure'),
                () => {
                  swal({
                    title: this.translate.getTranslation('SAVED'),
                    text: this.translate.getTranslation('SAVED_CONFIGURATION_SUCCESS'),
                    type: 'success',
                    showConfirmButton: false,
                    timer: 2000,
                  }).catch(() => {
                    swal.noop;
                    resolve();
                  });
                }
              );
            } else {
              // Interfaces configuration.
              if (this.intHash !== Md5.hashAsciiStr(JSON.stringify(this.intConfigs))) {
                this.intConfigs.forEach(el => {
                  if (el.laundry_laundryId === '') {
                    el.laundry_laundryId = this.lauConfigs.laundryId;
                  }
                });
                interfaceObs = this.backendApi.setInterfacesConfigs(this.intConfigs);
                allObs.push(interfaceObs);
              }
              // Washing machines configuration.
              if (this.wasHash !== Md5.hashAsciiStr(JSON.stringify(this.wasConfigs))) {
                washingMachinesObs = this.backendApi.setWashingMachinesConfigs(this.wasConfigs);
                allObs.push(washingMachinesObs);
              }
              // Drying machines configuration.
              if (this.dryHash !== Md5.hashAsciiStr(JSON.stringify(this.dryConfigs))) {
                dryingMachineObs = this.backendApi.setDryingMachinesConfigs(this.dryConfigs);
                allObs.push(dryingMachineObs);
              }
              // Prices configuration.
              if (this.pricesHash !== Md5.hashAsciiStr(JSON.stringify(this.prices))) {
                pricesObs = this.backendApi.setPrograms(this.prices);
                allObs.push(pricesObs);
              }
              // Send save/update all request.
              Observable.forkJoin(allObs).subscribe(
                res => {
                  this.cs.setCommand({ src: 'laundry-configuration', dest: 'laundries', cmd: 'refresh' });

                  this.cs.setCommand({ src: 'laundry-configuration', dest: 'vending-app', cmd: 'refresh' });
                },
                // TODO: handle fetching errors.
                err => {
                  this.cf.presentNotification('failure');
                },
                () => {
                  swal({
                    title: this.translate.getTranslation('SAVED'),
                    text: this.translate.getTranslation('SAVED_CONFIGURATION_SUCCESS'),
                    type: 'success',
                    showConfirmButton: false,
                    timer: 2000,
                  }).catch(() => {
                    swal.noop;
                    resolve();
                  });
                }
              );
            }
          }).catch(() => resolve());
        });
      }
    }
    return new Promise((resolve, reject) => resolve());
  }

  getLaundryTemplate(): any {
    return {
      name: '',
      laundryCode: '',
      obj: {
        changeEnabled: false,
        minRecharge: '2.50',
        minCharge: '10.00',

        // Parameters for new recharge workflow
        cardPrice: '5.00',
        minCardCredit: '5.00',
        cardCreditInc: '0.50',
        rechargeWithChange: false,

        rechargeCoinBonus: '0',  // %
        rechargeBillBonus: '0',  // %
      },
      address: {
        addressLine1: '',
        addressLine2: '',
        country: '',
        stateProvince: '',
        city: '',
        postalCode: '',
        lat: '',
        lng: '',
        email: '',
        mobileNumber: '',
        phoneNumber: '',
        faxNumber: '',
      },
      userLaundries: [{
        user: {
          birthDate: null,
          language: '',
          name: '',
          nif: '',
          sex: '',
        }
      }],
      vendingMachines: [{
        type: '',
        brand: '',
        model: '',
        serialNumber: '',
        obs: '',
      }],
      // vendingMachines: [this.getEmptyVM()],
    }
  }

  getEmptyVM() {
    return {
      type: '',
      brand: '',
      model: '',
      serialNumber: '',
      obs: '',
    };
  }

  setTabs() {
    this.tabs = [{
      page: LaundryPage,
      title: 'LAUNDRY_TAB_TITLE',
      iconName: 'home',
      enabled: true,
    },{
      page: InterfacesPage,
      title: 'INTERFACE_TAB_TITLE',
      iconName: 'pulse',
      enabled: !this.newLaundry,
    }, {
      page: WashingMachinesPage,
      title: 'WASHING_MACHINE_TAB_TITLE',
      iconName: 'shirt',
      enabled: !this.newLaundry,
    }, {
      page: DryingMachinesPage,
      title: 'DRYING_MACHINE_TAB_TITLE',
      iconName: 'thermometer',
      enabled: !this.newLaundry,
    }, {
      page: PricingTablePage,
      title: 'PRICING_TAB_TITLE',
      iconName: 'list-box',
      enabled: !this.newLaundry,
    }, {
      page: NotificationsPage,
      title: 'NOTIFICATION_TAB_TITLE',
      iconName: 'notifications',
      enabled: !this.newLaundry,
    }];
  }

  presentMsgError(err) {
    if (err.hasOwnProperty('message')) {
      this.cf.presentMsgNotification('error', err.message);
      return true;
    }
    return false;
  }

}



