import { Component, OnDestroy } from '@angular/core';
import { ModalController } from 'ionic-angular';
import { DragulaService } from 'ng2-dragula/ng2-dragula';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { TaskEditorPage } from '../task-editor/task-editor';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { UserSession } from '../../providers/user-session';


@Component({
  selector: 'page-maintenance-board',
  templateUrl: 'maintenance-board.html'
})
export class MaintenanceBoardPage implements OnDestroy {

  viewReady: boolean = false;

  // Task lists.
  tasks: Array<any> = [];
  fTasks: Array<any> = [];

  todoTasks: Array<any> = [];
  inProgressTasks: Array<any> = [];
  doneTasks: Array<any> = [];

  // Filtered tasks lists.
  fTodoTasks: Array<any> = [];
  fInProgressTasks: Array<any> = [];
  fDoneTasks: Array<any> = [];

  users: Array<any> = [];
  selectedUser: string = '';

  filterKeys: Array<any> = ['userName', 'laundryName', 'deviceType', 'repairDate', 'obs'];
  dragulaSubs: Subscription;
  

  constructor(private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private userSession: UserSession,
              private dragulaService: DragulaService) {
    // Drag and drop events.
    this.dragulaSubs = dragulaService.drop.subscribe((value) => {
      let taskId = value[1].id;
      let destId = value[2].id;

      // get droped task
      let task = JSON.parse(JSON.stringify(this.tasks.find(item => (item.maintenanceId === taskId))));
      switch (destId) {
        case 'todo':
          task.status = 'TODO';
          break;
        case 'in-progress':
          task.status = 'IN_PROGRESS';
          break;
        case 'done':
          task.status = 'DONE';
          break;
      }
      this.updateTask(task);
    });
    this.getTasks();
  }

  ngOnDestroy() {
    if (this.dragulaSubs) this.dragulaSubs.unsubscribe();
  }

  getTasks() {
    this.backendApi.getTasks().subscribe(
      res => {
        this.tasksPreprocessing(res);
        this.viewReady = true; 
      },
      err => {}
    );
  }

  tasksPreprocessing(tasks) {
    Object.keys(tasks).forEach(key => {
      tasks[key].forEach(task => {
        task.userName = (task.user) ? task.user.name : this.translate.getTranslation('NO_OPERATOR');
        task.laundryName = (task.laundry) ? task.laundry.name : '';
        task.hasLaundry = (task.laundry && task.laundry.hasOwnProperty('deleted_at')) ? true : false;
        task.hasUser = (task.user && task.user.hasOwnProperty('deleted_at')) ? true : false;
        task.visibility = true;
        if (task.machine_machineId) {
          if (task.machine.type === 'wash') {
            task.deviceType = this.translate.getTranslation('WASH_MACHINE');
          } else {
            task.deviceType = this.translate.getTranslation('DRY_MACHINE');
          }
        }
        if (task.vending_machine_vendingMachineId) {
          task.deviceType = this.translate.getTranslation('VM');
        }
        if (task.laundry_peripheral_laundryPeripheralId) {
          task.deviceType = this.translate.getTranslation('INTERFACE');
        }
        if (task.vending_machine_peripheral_peripheralId) {
          task.deviceType = this.translate.getTranslation('PERIPHERAL');
        }
      });
    })
    this.tasks = tasks.todo.concat(tasks.inpro, tasks.done);
  }

  updateTask(task) {
    this.backendApi.updateTask(task).subscribe(
      res => {},
      err => {}
    );
  }

  getPriorityClass(task) {
    switch (task.priority) {
      case 'LOW':
        return 'low-priority';
      case 'MEDIUM':
        return 'medium-priority';
      case 'HIGH':
        return 'high-priority';
    }
  }

  newTask() {
    let taskModal = this.modalCtrl.create(TaskEditorPage);
    taskModal.onDidDismiss(
      res => {
        if (!res) return;

        res.task.userName = (res.task.user) ? res.task.user.name : '';
        res.task.laundryName = (res.task.laundry) ? res.task.laundry.name : '';
        res.task.visibility = true;

        if (res.task.machine_machineId) {
          if (res.task.machine.type === 'wash') {
            res.task.deviceType = this.translate.getTranslation('WASH_MACHINE');
          } else {
            res.task.deviceType = this.translate.getTranslation('DRY_MACHINE');
          }
        }
        if (res.task.vending_machine_vendingMachineId) {
          res.task.deviceType = this.translate.getTranslation('VM');
        }
        if (res.task.laundry_peripheral_laundryPeripheralId) {
          res.task.deviceType = this.translate.getTranslation('INTERFACE');
        }
        if (res.task.vending_machine_peripheral_peripheralId) {
          res.task.deviceType = this.translate.getTranslation('PERIPHERAL');
        }
        this.getTasks();
      }
    )
    taskModal.present();
  }

  editTask(task) {
    let taskModal = this.modalCtrl.create(TaskEditorPage, { task: task });
    taskModal.onDidDismiss(
      res => {
        if (!res) return;

        if (res.cmd === 'DELETE') {
          let task = this.tasks.find(item => (item.maintenanceId === res.maintenanceId)).deleted = true;
        } else {
          this.tasks.forEach(item => {
            if (item.maintenanceId === res.task.maintenanceId) {

              Object.keys(item).forEach(k => {
                  if (res.task.hasOwnProperty(k)) {
                    item[k] = res.task[k];
                  }
              });
              item.userName = (item.user) ? item.user.name : '';
              item.laundryName = (item.laundry) ? item.laundry.name : '';
              item.visibility = true;

              if (item.machine_machineId) {
                if (item.machine.type === 'wash') {
                  item.deviceType = this.translate.getTranslation('WASH_MACHINE');
                } else {
                  item.deviceType = this.translate.getTranslation('DRY_MACHINE');
                }
              }
              if (item.vending_machine_vendingMachineId) {
                item.deviceType = this.translate.getTranslation('VM');
              }
              if (item.laundry_peripheral_laundryPeripheralId) {
                item.deviceType = this.translate.getTranslation('INTERFACE');
              }
              if (item.vending_machine_peripheral_peripheralId) {
                item.deviceType = this.translate.getTranslation('PERIPHERAL');
              }
            }
          });
        }
      }
    );
    taskModal.present();
  }

  filterResults($event) {
    let searchTerm = $event.target.value.trim().toLowerCase();
    if (searchTerm.length > 0) {
      this.tasks.forEach(item => {
        if(Object.keys(item).some(k => (item[k] && typeof item[k] === 'string' && this.filterKeys.indexOf(k) >= 0 && item[k].toLowerCase().includes(searchTerm.toLowerCase())))) {
          item.visibility = true;
        } else {
          item.visibility = false;
        }
      });
    } else {
      this.showAllResults();
    }
  }

  showAllResults() {
    this.tasks.forEach(item => item.visibility = true);
  }

}



