import { Injectable } from '@angular/core';

// Page components.
import { AppConfigurationPage } from '../pages/app-configuration/app-configuration';
import { LaundriesPage } from '../pages/laundries/laundries';
import { VendingMachinesPage } from '../pages/vending-machines/vending-machines';
import { UserListPage } from '../pages/user-list/user-list';
import { UserPage } from '../pages/user/user';
import { RoleListPage } from '../pages/role-list/role-list';
import { DashboardPage } from '../pages/dashboard/dashboard';
import { AppChargePage } from '../pages/app-charge/app-charge';
import { MaintenanceBoardPage } from '../pages/maintenance-board/maintenance-board';

// Service/provider components.
import { UserSession } from '../providers/user-session';


@Injectable()
export class AppSettings {

  hopperOK: boolean = true;
  // Money insertion variables (bills and coins).
  coinEqTable: any = [
    { "key": "3", "value": 0.05 },
    { "key": "4", "value": 0.10 },
    { "key": "5", "value": 0.20 },
    { "key": "6", "value": 0.50 },
    { "key": "7", "value": 1.00 },
    { "key": "8", "value": 2.00 }
  ];
  billEqTable: any = [
    { "key": "5", "value": 5.00 },
    { "key": "10", "value": 10.00 },
    { "key": "20", "value": 20.00 },
    { "key": "50", "value": 50.00 }
  ];

  appSettings: any;

  constructor(private userSession: UserSession) {
    if (window.location.host.indexOf('localhost') !== -1) {
      this.appSettings = {
        menuAdmin: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER_LIST', icon: 'ios-person-outline', component: UserListPage, permission: 'user-read' },
           { label: 'CLIENT_LIST_TITLE', icon: 'ios-people-outline', component: UserListPage, permission: 'user-read' }],
          [{ label: 'ROLE_LIST', icon: 'ios-alert-outline', component: RoleListPage, permission: 'role-read' },
           { label: 'DASHBOARD', icon: 'ios-stats-outline', component: LaundriesPage, permission: 'user-read' }],
          [{ label: 'ORDER_LOG', icon: 'ios-clipboard-outline', component: LaundriesPage, permission: 'user-read' },
           { label: 'APP_CHARGE', icon: 'ios-tablet-portrait-outline', component: AppChargePage, permission: 'user-read' }],
          [{ label: 'MAINTENANCE', icon: 'ios-list-box-outline', component: MaintenanceBoardPage, permission: 'user-read' },
           { label: 'EMPTY_HOPPER', icon: 'ios-sync-outline', component: null, permission: null }],
          [{ label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null },
           { label: 'RELOAD', icon: 'ios-refresh-outline', component: null, permission: null }],
          [{ label: 'UPDATE', icon: 'ios-sync-outline', component: null, permission: null },
           { label: 'EXIT', icon: 'ios-power-outline', component: null, permission: null }]         
        ],
        menuOwner: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER', icon: 'ios-person-outline', component: UserPage, permission: 'user-read' },
           { label: 'CLIENT_LIST_TITLE', icon: 'ios-people-outline', component: UserListPage, permission: 'user-read' }],
          [{ label: 'DASHBOARD', icon: 'ios-stats-outline', component: LaundriesPage, permission: 'user-read' },
           { label: 'ORDER_LOG', icon: 'ios-clipboard-outline', component: LaundriesPage, permission: 'user-read' }],
          [{ label: 'EMPTY_HOPPER', icon: 'ios-sync-outline', component: null, permission: null },
           { label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null }],
          [{ label: 'RELOAD', icon: 'ios-refresh-outline', component: null, permission: null },
           { label: 'UPDATE', icon: 'ios-sync-outline', component: null, permission: null }],
          [{ label: 'EXIT', icon: 'ios-power-outline', component: null, permission: null }]                    
        ],
        menuOperator: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER', icon: 'ios-person-outline', component: UserPage, permission: 'user-read' },
           { label: 'MAINTENANCE', icon: 'ios-list-box-outline', component: MaintenanceBoardPage, permission: 'user-read' }],
          [{ label: 'EMPTY_HOPPER', icon: 'ios-sync-outline', component: null, permission: null },
           { label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null }],
          [{ label: 'RELOAD', icon: 'ios-refresh-outline', component: null, permission: null },
           { label: 'UPDATE', icon: 'ios-sync-outline', component: null, permission: null }],
          [{ label: 'EXIT', icon: 'ios-power-outline', component: null, permission: null }]          
        ],
        // Color palette set used for customization.
        colorPalette: [
          { name: 'primary'},
          { name: 'red', value: '#ff0000' },
          { name: 'green', value: '#00ff00'},
          { name: 'blue', value: '#0000ff' },
        ],
        // Customizable fields (color theme).
        colors: [
          { name: 'header-background', label: 'Header background'},
          { name: 'footer-background', label: 'Footer background'},
          { name: 'page-background', label: 'Page background'},
          { name: 'font', label: 'Font'}
        ],
        // Supported languages.
        langs: [
          { name: 'Português', value: 'pt', label: 'PT', img: 'assets/img/portugues.png'},
          { name: 'Español', value: 'es', label: 'ES', img: 'assets/img/espanhol.png'},
          { name: 'Français', value: 'fr', label: 'FR', img: 'assets/img/frances.png'},
          { name: 'English', value: 'en', label: 'EN', img: 'assets/img/ingles.png'},
        ]
      }
    } else {
      this.appSettings = {
        menuAdmin: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER_LIST', icon: 'ios-person-outline', component: UserListPage, permission: 'user-read' },
           { label: 'CLIENT_LIST_TITLE', icon: 'ios-people-outline', component: UserListPage, permission: 'user-read' }],
          [{ label: 'ROLE_LIST', icon: 'ios-alert-outline', component: RoleListPage, permission: 'role-read' },
           { label: 'DASHBOARD', icon: 'ios-stats-outline', component: LaundriesPage, permission: 'user-read' }],
          [{ label: 'ORDER_LOG', icon: 'ios-clipboard-outline', component: LaundriesPage, permission: 'user-read' },
           { label: 'APP_CHARGE', icon: 'ios-tablet-portrait-outline', component: AppChargePage, permission: 'user-read' }],
          [{ label: 'MAINTENANCE', icon: 'ios-list-box-outline', component: MaintenanceBoardPage, permission: 'user-read' },
           { label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null }]
        ],
        menuOwner: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER', icon: 'ios-person-outline', component: UserPage, permission: 'user-read' },
           { label: 'CLIENT_LIST_TITLE', icon: 'ios-people-outline', component: UserListPage, permission: 'user-read' }],
          [{ label: 'DASHBOARD', icon: 'ios-stats-outline', component: LaundriesPage, permission: 'user-read' },
           { label: 'ORDER_LOG', icon: 'ios-clipboard-outline', component: LaundriesPage, permission: 'user-read' }],
          [{ label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null }]
        ],
        menuOperator: [
          [{ label: 'CONFIG_LAUNDRY', icon: 'ios-home-outline', component: LaundriesPage, permission: 'laundry-read' },
           { label: 'CONFIG_VM', icon: 'ios-tablet-portrait-outline', component: VendingMachinesPage, permission: 'vending-machine-read' }],
          [{ label: 'USER', icon: 'ios-person-outline', component: UserPage, permission: 'user-read' },
           { label: 'MAINTENANCE', icon: 'ios-list-box-outline', component: MaintenanceBoardPage, permission: 'user-read' }],
          [{ label: 'LOGOUT', icon: 'ios-exit-outline', component: null, permission: null }]
        ],
        // Color palette set used for customization.
        colorPalette: [
          { name: 'primary'},
          { name: 'red', value: '#ff0000' },
          { name: 'green', value: '#00ff00'},
          { name: 'blue', value: '#0000ff' },
        ],
        // Customizable fields (color theme).
        colors: [
          { name: 'header-background', label: 'Header background'},
          { name: 'footer-background', label: 'Footer background'},
          { name: 'page-background', label: 'Page background'},
          { name: 'font', label: 'Font'}
        ],
        // Supported languages.
        langs: [
          { name: 'Português', value: 'pt', label: 'PT', img: 'assets/img/portugues.png'},
          { name: 'Español', value: 'es', label: 'ES', img: 'assets/img/espanhol.png'},
          { name: 'Français', value: 'fr', label: 'FR', img: 'assets/img/frances.png'},
          { name: 'English', value: 'en', label: 'EN', img: 'assets/img/ingles.png'},
        ]
      }
    }
  }

  getMenu() {
    switch (this.userSession.roleName) {
      case 'admin': return this.appSettings.menuAdmin;
      case 'owner': return this.appSettings.menuOwner;
      case 'operator': return this.appSettings.menuOperator;
    }
    return this.appSettings.menuOwner;
  }

  getColorPalette() {
    return this.appSettings.colorPalette;
  }

  getLangs() {
    return this.appSettings.langs;
  }

  getColors() {
    return this.appSettings.colors;
  }

}



