import { Injectable } from '@angular/core';
import { Subject } from 'rxjs/Rx';
import { Subscription } from 'rxjs/Rx';
import 'rxjs/add/operator/map';

import { Middleware } from './middleware';


@Injectable()
export class Inactivity {

  timer: any = null;
  inactTimeout: number = 2*60*1000; // [ms]
  // inactTimeout: number = 15*1000; // [ms]

  inactStream: Subject<any> = null;
  enabled: boolean = true;

  middlewareSubs: Subscription = null;

  constructor(private middleware: Middleware) {
    this.inactStream = new Subject<any>();

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg.hasOwnProperty('code')) {
          switch (pkg.op) {
            case'card-inserted':
              if (pkg.data.admin === 'true') {
                this.stopTimer();
                this.enabled = false;
              }
              break;
            case 'card-removed':
              this.enabled = true;
              break;
          }
        }
      }
    );
  }

  setInactivitySignal() {
    this.inactStream.next({ state: 'INACTIVE' });
  }

  getInactivitySignal() {
    return this.inactStream.asObservable();
  }

  inactivityTimeout() {
    this.timer = setTimeout(() => {
      this.setInactivitySignal();
    }, this.inactTimeout);
  }

  startTimer() {
    if (this.enabled) {
      this.inactivityTimeout();
    }
  }

  stopTimer() {
    clearTimeout(this.timer);
  }

  resetTimer() {
    if (this.enabled) {
      this.stopTimer();
      this.startTimer();
    }
  }

}



