import { Component, OnDestroy } from '@angular/core';
import { ViewController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';

// Service/provider components.
import { TranslateService } from '../../translate';
import { Inactivity } from '../../providers/inactivity';


@Component({
  selector: 'page-help',
  templateUrl: 'help.html'
})
export class HelpPage implements OnDestroy {

  storage = new Storage();  
  timerSubs: Subscription = null;  

  constructor(private viewCtrl: ViewController,
              private inactivityTimer: Inactivity,
              private translate: TranslateService) {
    // Subscribe to inactivity timer event.
    this.timerSubs = this.inactivityTimer.getInactivitySignal().subscribe(signal => {
      if (signal.state === 'INACTIVE') {
        // dismiss modal component.
        this.close();
      }
    });
  }

  ngOnDestroy() {
    if (this.timerSubs) this.timerSubs.unsubscribe();
  }

  selectTour(selectedTour) {
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (selectedTour === 'RECHARGE_CARD' && !laundryInfo.pricingObj.rechargeWithChange) {
        selectedTour = 'RECHARGE_CARD_ALT';
      }
      if (selectedTour === 'BUY_CARD' && !laundryInfo.pricingObj.buyChargeEnabled) {
        selectedTour = 'BUY_CARD_ALT';
      }
      this.viewCtrl.dismiss({ confirm: true, selectedTour: selectedTour });
    });
  }

  close() {
     this.viewCtrl.dismiss({ confirm: false });
  }
}



