import { Injectable } from '@angular/core';

import { Middleware } from './middleware';
import { BackendApiProvider } from './backend-api-provider';
import { CommonServices } from './common-services';

@Injectable()
export class UnsavedOrders {

  orders: Array<any> = [];
  maxAttemps: number = 6;
  timer = null;

  constructor(private middleware: Middleware,
              private cs: CommonServices,
              private backendApi: BackendApiProvider) {
    this.cs.getData().subscribe(res => {
      if (res.hasOwnProperty('unsavedOrders')) {
        this.orders = res.unsavedOrders;
        this.saveRecords();
      }
    });
  }

  init() {
    if (this.timer) clearTimeout(this.timer);
    this.middleware.getUnsavedOrders();
  }

  addRecords(serv, body) {
    this.orders.push({ serv: serv, body: body, attempts: 0 });
    this.middleware.setUnsavedOrders(this.orders);
  }

  saveRecords() {
    if (this.orders.length > 0) {
      if (this.orders[0].hasOwnProperty('attempts')) {
        this.orders[0].attempts = this.orders[0].attempts + 1;
      } else {
        this.orders[0]['attempts'] = 0;
      }

      // Remove order logs if entry reached the maximum number of saving attemps
      if (this.orders[0].hasOwnProperty('attempts') && this.orders[0].attempts > this.maxAttemps) {
        this.orders.shift();
        this.middleware.setUnsavedOrders(this.orders);
        this.timer = setTimeout(() => { this.saveRecords(); }, 1000);
      } else {
        switch (this.orders[0].serv) {
          case 'orders/neworder':
            this.backendApi.setOrders(this.orders[0].body).subscribe(
              res => {
                this.orders.shift();
                this.middleware.setUnsavedOrders(this.orders);
                this.timer = setTimeout(() => { this.saveRecords(); }, 1000);
              },
              err => {}
            );
            break;
          case 'card/newcard':
            this.backendApi.newCard(this.orders[0].body).subscribe(
              res => {
                this.orders.shift();
                this.middleware.setUnsavedOrders(this.orders);
                this.timer = setTimeout(() => { this.saveRecords(); }, 1000);
              },
              err => {}
            );
            break;
        }
      }
    }
  }
}



