import { Injectable } from '@angular/core';
import { Observable } from 'rxjs/Rx';
import { Subject } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';
import { JwtHelper } from 'angular2-jwt';

import * as io from "socket.io-client";
import * as CryptoJS from 'crypto-js';

import { Client } from './client';
import { CommonServices } from './common-services';
import { AppConfig } from './app-config';


@Injectable()
export class Middleware {

  jwtHelper: any = new JwtHelper();

  host: string = 'localhost';
  port: string = '3300';
  socket: SocketIOClient.Socket = null;
  incomingPkgObs: Subject<any> = null;
  storage = new Storage();

  ownerId: any = null;

  constructor(private client: Client,
              private cs: CommonServices,
              private app: AppConfig) {
    this.incomingPkgObs = new Subject<any>();

    this.storage.get('laundryInfo').then(laundryInfo => {
      if (laundryInfo) {
        this.ownerId = laundryInfo.ownerId;
      }
    });
  }

  connect() {
    let middlewareUrl = `http://${this.host}:${this.port}`;
    this.socket = io.connect(middlewareUrl, { reconnection: true, reconnectionAttempts: 4 });

    this.socket.on('connect', () => {
      this.getLocalStorage();
      this.getUnsavedOrders();
    });

    this.socket.on('middleware-pkg', (pkg) => {
      let pkgAux = JSON.parse(pkg.replace(/(\r\n|\n|\r)/gm,""));
      if (this.hasAccess(pkgAux)) {
        this.incomingPkgObs.next(pkgAux);
      }
    });

    this.socket.on('SET_VM_TOKEN', (vmToken) => {
      this.storage.set('isVM', true)
        .then(() => {
          if (vmToken) {
            this.storage.set('vm_id_token', vmToken.trim());
            this.storage.set('id_token', vmToken.trim());
          }
          this.incomingPkgObs.next({ op: 'MIDDLEWARE_CONNECTED' });
        })
        .catch((err) => {});
      }
    );

    this.socket.on('SET_LOCAL_STORAGE', (data) => {
      if (typeof data === 'string' && data) {
        let bytes  = CryptoJS.AES.decrypt(data, this.app.appConfig.acst);
        let decryptedData = JSON.parse(bytes.toString(CryptoJS.enc.Utf8));
        this.cs.setData({ offlineData: decryptedData });
      }
    });

    this.socket.on('SET_OFFLINE_SERV', (data) => {
      if (typeof data === 'string' && data) {
        let bytes  = CryptoJS.AES.decrypt(data, this.app.appConfig.acst);
        let decryptedData = JSON.parse(bytes.toString(CryptoJS.enc.Utf8));
        this.cs.setData({ unsavedOrders: decryptedData });
      }
    });
  }

  disconnect() {
    this.socket.disconnect();
  }

  send(pkg) {
    if (pkg.hasOwnProperty('op') && pkg.op === 'remote-credits-res') {
      this.socket.emit('remote-credits-res', pkg);
    } else {
      if (pkg.hasOwnProperty('op') && pkg.op === 'write-card' && pkg.hasOwnProperty('data')) {
        if (this.client.client.admin) {
          pkg.data.admin = true;
        } else {
          pkg.data.ownerId = this.ownerId;        
        }
      }
      this.socket.emit('pkg', pkg);
    }
  }

  lowLevelEmulator(pkg) {
    if (this.hasAccess(pkg)) {
      this.incomingPkgObs.next(pkg);
    }
  }

  getPkg(): Observable<any> {
    return this.incomingPkgObs.asObservable();
  }

  saveVmToken(vmToken) {
    this.socket.emit('SAVE_VM_TOKEN', vmToken);
  }

  deleteVmToken() {
    this.socket.emit('DELETE_VM_TOKEN');
  }

  shutdownPC() {
    this.socket.emit('shutdown');
  }

  rebootPC() {
    if (this.socket) { this.socket.emit('reboot'); }
  }

  updateVM() {
    this.socket.emit('update');    
  }

  getLocalStorage() {
    if (this.socket) {
      this.socket.emit('get-localstorage');
    }   
  }

  setLocalStorage(data) {
    try {
      let ciphertext = CryptoJS.AES.encrypt(JSON.stringify(data), this.app.appConfig.acst);
      this.socket.emit('set-localstorage', ciphertext.toString());
    } catch (err) {}
  }

  getUnsavedOrders() {
    if (this.socket) this.socket.emit('get-offline-serv');    
  }

  setUnsavedOrders(orders) {
    let ciphertext = CryptoJS.AES.encrypt(JSON.stringify(orders), this.app.appConfig.acst);    
    this.socket.emit('set-offline-serv', ciphertext.toString());
  }

  hasAccess(pkg) {
    if (!(pkg.hasOwnProperty('op') && pkg.op === 'card-inserted')) return true;

    if (pkg.hasOwnProperty('data') && (!pkg.data.hasOwnProperty('ownerId') || (pkg.data.hasOwnProperty('ownerId') && pkg.data.ownerId === 'ALL') || (pkg.data.hasOwnProperty('ownerId') && pkg.data.ownerId === this.ownerId))) {
      return true;
    } else {
      return false;
    }
  }
}



