import { Component, OnInit } from '@angular/core';
import { NavController, NavParams } from 'ionic-angular';
import { Md5 } from 'ts-md5/dist/md5';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-role',
  templateUrl: 'role.html'
})
export class RolePage implements OnInit {

  debugFlag: boolean = false;
  adminMode: boolean = false;

  // Permissions.
  updRoleEnabled: boolean = false;
  delRoleEnabled: boolean = false;

  role: any = null;
  permissions: Array<any> = null;
  roleHash: any = null;
  action: string = 'create';
  newRole: boolean = false;
  roleName: string = '';
  roleNamePlaceholder: string = '';
  canLeave: boolean = false;
  readOnly: boolean = true;

  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession) {
    // Enable/disable CRUD operations.
    this.updRoleEnabled = this.userSession.getPermission('role-update');
    this.delRoleEnabled = this.userSession.getPermission('role-delete');
  }

  returnBool() {
    return false;
  }

  ngOnInit() {
    // Get role.
    this.role = this.navParams.get('role');
    if (this.role.role !== 'type') {
      this.action = 'update';
    } else {
      this.roleNamePlaceholder = this.translate.getTranslation('NEW_ROLE_PLACEHOLDER');
      this.newRole = true;
    }
    // Store initial role state.
    this.roleHash = Md5.hashAsciiStr(JSON.stringify(this.role));
    // Get permissions in array format.
    this.permissions = this.objToArray(this.role.permissions);

    if (this.role.role === 'admin') {
      this.adminMode = true;
    }
  }

  save() {
    this.role.permissions = this.arrayToObj(this.permissions);
    if (this.role.role === 'type') {
        this.role.role = this.roleName;
    }
    // Save role.
    this.backendApi.setRole(this.role, this.action).subscribe(
      res => {},
      // TODO: handle fetching errors.
      err => {
        this.cf.presentNotification('failure');
      },
      () => {
        this.cs.setCommand({ src: 'role', dest: 'role-list', cmd: 'refresh'});
        this.cf.presentNotification('success');
        if (this.action === 'create') this.action = 'update';
        // Store new user state.
        this.roleHash = Md5.hashAsciiStr(JSON.stringify(this.role));
      }
    );
  }

  edit() {
    this.readOnly = !this.readOnly;
  }

  objToArray(obj): Array<any> {
    let keys = Object.keys(obj);
    let permissions = [];
    keys.forEach(el => {
      let innerKeys = Object.keys(this.role.permissions[el]);
      let fields = [];
      let obj1 = {};
      innerKeys.forEach(el2 => {
        let obj2 = {};
        obj2['key'] = el2;
        obj2['value'] = this.role.permissions[el][el2];
        fields.push(obj2);
      });
      obj1['key'] = el;
      obj1['value'] = fields;
      permissions.push(obj1);;
    });
    return permissions;
  }

  arrayToObj(arr): any {
    let obj1 = {};
    arr.forEach(el1 => {
      let obj2 = {};
      el1.value.forEach(el2 => {
        obj2[el2.key] = el2.value;
      });
      obj1[el1.key] = obj2;
    });
    return obj1;
  }

  delete() {
    if (this.role.count !== 0) {
      // Not possible to delete (users associated).
      swal({
        title: this.translate.getTranslation('ALERT_CANNOT_DELETE_TITLE'),
        text: this.translate.getTranslation('ALERT_CANNOT_DELETE_MSG'),
        type: 'error',
        showConfirmButton: false,
        timer: 2000,
      })
      .then().catch(swal.noop);
    } else {
      // Show alert to confirm role deletion.
      swal({
        title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
        text: this.translate.getTranslation('ALERT_DELETE_MSG'),
        type: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#ff1a1a',
        cancelButtonColor: 'rgb(13, 51, 72)',
        confirmButtonText: this.translate.getTranslation('YES'),
        cancelButtonText: this.translate.getTranslation('NO'),
      }).then(() => {
        this.backendApi.setRole(this.role, 'delete').subscribe(
          res => {},
          // TODO: handle fetching errors.
          err => {
            this.cf.presentNotification('failure');
          },
          () => {
            this.cs.setCommand({ src: 'role', dest: 'role-list', cmd: 'refresh'});
            this.canLeave = true;
            if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
            swal({
              title: this.translate.getTranslation('DELETED'),
              text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
              type: 'success',
              showConfirmButton: false,
              timer: 2000,
            }).catch(swal.noop);
          }
        );
      }).catch(swal.noop);
    }
  }

  hasUnsavedChanges() {
    if (this.adminMode) return false;

    this.role.permissions = this.arrayToObj(this.permissions);
    if (this.roleHash !== Md5.hashAsciiStr(JSON.stringify(this.role))) {
      if (this.role.role === 'type') {
          this.role.role = this.roleName;
      }
      return true;
    }
    return false;
  }

  ionViewCanLeave() {
    if (!this.canLeave && this.hasUnsavedChanges()) {
      return new Promise((resolve, reject) => {
        swal({
          title: this.translate.getTranslation('ALERT_UNSAVED_TITLE'),
          text: this.translate.getTranslation('ALERT_UNSAVED_MSG'),
          type: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#ff1a1a',
          cancelButtonColor: 'rgb(13, 51, 72)',
          confirmButtonText: this.translate.getTranslation('YES'),
          cancelButtonText: this.translate.getTranslation('NO'),
        }).then(() => {
          this.backendApi.setRole(this.role, this.action).subscribe(
            res => {},
            // TODO: handle fetching errors.
            err => {
              this.cf.presentNotification('failure');
              reject();
            },
            () => {
              this.cs.setCommand({ src: 'role', dest: 'role-list', cmd: 'refresh'});
              swal({
                title: this.translate.getTranslation('SAVED'),
                text: this.translate.getTranslation('SAVE_CONFIGURATION_SUCCESS'),
                type: 'success',
                showConfirmButton: false,
                timer: 2000,
              }).catch(() => {
                swal.noop;
                resolve();
              });
            }
          );
        }).catch(() => {
          this.cs.setCommand({ src: 'role', dest: 'role-list', cmd: 'refresh'});
          resolve();
        });
      });
    }
    return new Promise((resolve, reject) => resolve());
  }

}



