import { Component } from '@angular/core';
import { ModalController, ViewController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { JwtHelper } from 'angular2-jwt';

// Service/provider components.
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { AppConfig } from '../../providers/app-config';
import { UserSession } from '../../providers/user-session';
import { CommonFunctions } from '../../providers/common-functions';


@Component({
  selector: 'page-login',
  templateUrl: 'login.html'
})
export class LoginPage {

  storage: any = new Storage();
  jwtHelper: any = new JwtHelper();
  email: string = null;
  password: string = null;
  btnEnabled: boolean = true;

  constructor(private viewCtrl: ViewController,
              private modalCtrl: ModalController,
              private backendApi: BackendApiProvider,
              private appConfig: AppConfig,
              private cf: CommonFunctions,
              private userSession: UserSession) {
  }

  clearFormInput() {
    this.email = null;
    this.password = null;
  }

  login() {
    if (!this.btnEnabled) return;

    this.btnEnabled = false;

    this.backendApi.authenticate(this.email, this.password).subscribe(
      res => {
        this.appConfig.setUsername(this.jwtHelper.decodeToken(res.token).name);
        this.userSession.setSessionAttr(this.jwtHelper.decodeToken(res.token));

        this.storage.set('id_token', res.token).then(() => {
          this.backendApi.getRolesById(this.userSession.roleId).subscribe(
            res => {
              this.userSession.setPermissions(res.permissions);
              this.userSession.roleName = res.role;

              this.btnEnabled = true;
              this.viewCtrl.dismiss({ success: true, status: 'OK' });
            },
            err => this.cf.presentMsgNotification('error', 'CHECK_INTERNET_CONNECTION')
          );
        });
      },
      err => {
        if (err.hasOwnProperty('status') && err.status === 401) {
          this.cf.presentMsgNotification('error', 'LOGIN_WRONG_CREDENTIALS');
          this.clearFormInput();
        } else if (err.hasOwnProperty('status') && err.status === 403) {
          this.viewCtrl.dismiss({ success: false, status: 'VM_CONFIG_BLOCKED' });
        } else {
          this.cf.presentMsgNotification('error', 'CHECK_INTERNET_CONNECTION');
        }
        this.btnEnabled = true;        
      }
    );
  }

}



