import { Component, OnDestroy, ChangeDetectionStrategy, Input } from '@angular/core';
import { NavParams, ModalController, ToastController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/forkJoin';
import 'rxjs/add/observable/of';
import 'rxjs/add/operator/do';
import 'rxjs/add/operator/map';
import * as moment from 'moment';
import * as $ from 'jquery';
import { DatePipe } from '@angular/common';

// Page components.
import { ReleaseChangePage } from '../release-change/release-change';

// Service/provider components.
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { TranslateService } from '../../translate';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';
import { CommonFunctions } from '../../providers/common-functions';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-order-logs',
  templateUrl: 'order-logs.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class OrderLogsPage implements OnDestroy {

  asyncResults1: Observable<any>;
  p1: number = 1;
  total1: number;
  itemsPerPage1: number;
  loading1: boolean = true;
  noResult1: boolean = true;
  gettingPage1 = false;

  asyncResults2: Observable<any>;
  p2: number = 1;
  total2: number;
  itemsPerPage2: number;
  loading2: boolean = true;
  noResult2: boolean = true;
  gettingPage2 = false;

  asyncResults3: Observable<any>;
  p3: number = 1;
  total3: number;
  itemsPerPage3: number;
  loading3: boolean = true;
  noResult3: boolean = true;
  gettingPage3 = false;

  asyncResults4: Observable<any>;
  p4: number = 1;
  total4: number;
  itemsPerPage4: number;
  loading4: boolean = true;
  noResult4: boolean = true;
  gettingPage4 = false;

  datePipe = new DatePipe('pt-PT');

  isLoading: boolean = false; //true;
  hasResults: boolean = true;

  laundryId: string = null;  
  startDate: any = null;
  endDate: any = null;

  orderLogs: Array<any> = [];
  actLogs: Array<any> = [];
  changeLogs: Array<any> = [];

  cloudMode: boolean = false;
  storage: any = new Storage();
  middlewareSubs: Subscription = null;  
  mwCloudSubs: Subscription = null; 
  changeRequested: boolean = false;
  localChangeRequested: boolean = false;
  activeSection: string = 'orders';

  changeValueReq: any = null;

  daterange: any = {};
  options: any = {};
  ranges: any = null;
  locales: any = null;

  tabletMode = false;

  sentCreditValue = null;    
  creditsRequested = true;


  constructor(private navParams: NavParams,
              private modalCtrl: ModalController,
              private cf: CommonFunctions,
              private translate: TranslateService,
              private toastCtrl: ToastController,
              private backendApi: BackendApiProvider,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud) {
    switch (this.translate.currentLang) {
      case 'pt':
        this.ranges = {
          'Hoje': [moment(), moment()],
          'Ontem': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Últimos 7 dias': [moment().subtract(6, 'days'), moment()],
          'Últimos 30 dias': [moment().subtract(29, 'days'), moment()],
          'Este mês': [moment().startOf('month'), moment().endOf('month')],
          'Mês passado': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Customizado",
          "daysOfWeek": ["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"],
          "monthNames": ["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"],
        };
        break;
      case 'fr':
        this.ranges = { 
          'Aujourd\'hui': [moment(), moment()],
          'Hier': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Les 7 derniers jours': [moment().subtract(6, 'days'), moment()],
          'Les 30 derniers jours': [moment().subtract(29, 'days'), moment()],
          'Ce mois-ci': [moment().startOf('month'), moment().endOf('month')],
          'Le mois dernier': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Personnalisé",
          "daysOfWeek": ["Dim","Lun","Mar","Mer","Jeu","Ven","Sam"],
          "monthNames": ["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"],
        };
        break;
      case 'es':
        this.ranges = {
          'Hoy': [moment(), moment()],
          'Ayer': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Últimos 7 días': [moment().subtract(6, 'days'), moment()],
          'Últimos 30 días': [moment().subtract(29, 'days'), moment()],
          'Este mes': [moment().startOf('month'), moment().endOf('month')],
          'Mes passado': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Personalizado",
          "daysOfWeek": ["Dom","Lun","Mar","Mier","Jue","Vie","Sa"],
          "monthNames": ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"],
        };
        break;
      case 'en':
        this.ranges = {
          'Today': [moment(), moment()],
          'Yesterday': [moment().subtract(1, 'days'), moment().subtract(1, 'days')],
          'Last 7 days': [moment().subtract(6, 'days'), moment()],
          'Last 30 days': [moment().subtract(29, 'days'), moment()],
          'This month': [moment().startOf('month'), moment().endOf('month')],
          'Last month': [moment().subtract(1, 'month').startOf('month'), moment().subtract(1, 'month').endOf('month')]
        };
        this.locales = {
          "format": "DD/MM/YYYY",
          "customRangeLabel": "Custom",
          "daysOfWeek": ["Su","Mo","Tu","We","Th","Fr","Sa"],
          "monthNames": ["January","February","March","April","May","June","July","August","September","October","November","December"],
        };
        break;
    }

    this.options = {
      startDate: moment().subtract(6, 'days'),
      endDate: moment(),
      locale: this.locales,
      alwaysShowCalendars: true,
      ranges: this.ranges,
      autoApply: true,
      showCustomRangeLabel: true,
      timePicker: false,
    };

    this.laundryId = this.navParams.data.laundry.laundryId;
    this.startDate = this.options.startDate;
    this.endDate = this.options.endDate;

    if (window.innerWidth <= 767) {
      this.endDate = new Date(this.endDate).toISOString();
      this.startDate = new Date(this.startDate).toISOString();
      this.tabletMode = true;
    }

    this.getPage1(1, false);
    this.getPage2(1, false);
    this.getPage3(1, false);
    this.getPage4(1, false);

    this.storage.get('laundryInfo').then(laundryInfo => {
      if (!laundryInfo || (laundryInfo && laundryInfo.laundryId !== this.laundryId)) {
        this.cloudMode = true;
        this.middlewareCloud.connect(this.laundryId);

        // Subscribe to incomming packages from middleware cloud.
        this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
          pkg => {
            if (!pkg) return;

            switch (pkg.op) {
              case 'no-change':
                if (this.changeRequested) {
                  this.changeNotification(pkg.data);
                  this.changeRequested = false;
                  this.changeValueReq = null;
                }

              case 'remote-credits-res':
                if (this.creditsRequested) {
                  this.creditsNotification(pkg.data);
                  this.creditsRequested = false;
                  this.sentCreditValue = null;
                }
            }
          }
        );
      } else {
        // Handle incoming data from the vending machine CPU.
        this.middlewareSubs = this.middleware.getPkg().subscribe(
          pkg => {
            if (!pkg) return;

            if (pkg.op === 'no-change') {
              if (this.localChangeRequested) {
                this.changeNotification(pkg.data);
                this.changeValueReq = null;
                this.localChangeRequested = false;
              }
            } 
          }
        );
      }
    });
  }

  ngOnDestroy() {
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    this.middlewareCloud.disconnect();
  }

  getPage1(page: number, opacity: boolean) {
    $('page-order-logs .scroll-content').animate({ scrollTop: 0 }, "slow");

    if (opacity) {
      this.gettingPage1 = true;
    } else {
      this.loading1 = true;
    }
    let start = (this.startDate) ? new Date(this.startDate) : null;
    let end = (this.endDate) ? new Date(this.endDate) : null;
    this.asyncResults1 = this.backendApi.getOrderLogsPage(page, this.laundryId, start, end)
    .do(res => {
      res.rows.forEach(el1 => {
        if (el1.orderMachinePrograms.length > 0) {
          el1.orderMachinePrograms = el1.orderMachinePrograms.filter(el2 => (el2.hasOwnProperty('machineProgram') && el2.machineProgram));
        }
        el1['datetime'] = moment(el1.created_at).format('DD-MM-YYYY HH:mm');    
      });

      if (!this.itemsPerPage1) this.itemsPerPage1 = res.rows.length;
      this.total1 = res.totalPages * this.itemsPerPage1;
      this.p1 = page;

      if (res.rows.length === 0) {
        this.noResult1 = true;
      } else {
        this.noResult1 = false;
      }
      this.loading1 = false;
      this.gettingPage1 = false;
    }, err => {
      this.gettingPage1 = false;
      this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
    })
    .map(res => res.rows);
  }

  getPage2(page: number, opacity: boolean) {
    $('page-order-logs .scroll-content').animate({ scrollTop: 0 }, "slow");

    if (opacity) {
      this.gettingPage2 = true;
    } else {
      this.loading2 = true;
    }
    let start = (this.startDate) ? new Date(this.startDate) : null;
    let end = (this.endDate) ? new Date(this.endDate) : null;
    this.asyncResults2 = this.backendApi.getRegPage(page, this.laundryId, 'CHANGE', start, end)
    .do(res => {

      res.rows.forEach(el => {
        el['datetime'] = moment(el.created_at).format('DD-MM-YYYY HH:mm');
      });

      if (!this.itemsPerPage2) this.itemsPerPage2 = res.rows.length;
      this.total2 = res.totalPages * this.itemsPerPage2;
      this.p2 = page;

      if (res.rows.length === 0) {
        this.noResult2 = true;
      } else {
        this.noResult2 = false;
      }
      this.loading2 = false;
      this.gettingPage2 = false;
    }, err => {
      this.gettingPage2 = false;
      this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
    })
    .map(res => res.rows);
  }

  getPage3(page: number, opacity: boolean) {
    $('page-order-logs .scroll-content').animate({ scrollTop: 0 }, "slow");

    if (opacity) { 
      this.gettingPage3 = true; 
    } else {
      this.loading3 = true;
    }
    let start = (this.startDate) ? new Date(this.startDate) : null;
    let end = (this.endDate) ? new Date(this.endDate) : null;
    this.asyncResults3 = this.backendApi.getRegPage(page, this.laundryId, 'ACTIVATION', start, end)
    .do(res => {

      res.rows = res.rows.filter(el => (el.hasOwnProperty('machine') && el.machine !== null));
      res.rows.forEach(el => {
        el['datetime'] = moment(el.created_at).format('DD-MM-YYYY HH:mm');
      });

      if (!this.itemsPerPage3) this.itemsPerPage3 = res.rows.length;
      this.total3 = res.totalPages * this.itemsPerPage3;
      this.p3 = page;

      if (res.rows.length === 0) {
        this.noResult3 = true;
      } else {
        this.noResult3 = false;
      }
      this.loading3 = false;
      this.gettingPage3 = false;
    }, err => {
      this.gettingPage3 = false;
      this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
    })
    .map(res => res.rows);
  }

  getPage4(page: number, opacity: boolean) {
    $('page-order-logs .scroll-content').animate({ scrollTop: 0 }, "slow");

    if (opacity) { 
      this.gettingPage4 = true; 
    } else {
      this.loading4 = true;
    }
    let start = (this.startDate) ? new Date(this.startDate) : null;
    let end = (this.endDate) ? new Date(this.endDate) : null;
    this.asyncResults4 = this.backendApi.getRegPage(page, this.laundryId, 'REMOTE_CREDITS', start, end)
    .do(res => {

      res.rows.forEach(el => {
        el['datetime'] = moment(el.created_at).format('DD-MM-YYYY HH:mm');
      });

      if (!this.itemsPerPage4) this.itemsPerPage4 = res.rows.length;
      this.total4 = res.totalPages * this.itemsPerPage4;
      this.p4 = page;

      if (res.rows.length === 0) {
        this.noResult4 = true;
      } else {
        this.noResult4 = false;
      }
      this.loading4 = false;
      this.gettingPage4 = false;
    }, err => {
      this.gettingPage4 = false;
      this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
    })
    .map(res => res.rows);
  }

  confDeleteOrder(order, machOrder) {
    swal({
      title: this.translate.getTranslation('RETURN_ASSO_AMOUNT'),
      type: 'warning',
      showCloseButton: true,
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',    
      confirmButtonText: 'Sim',
      cancelButtonText: 'Não',
    }).then((res) => {
      if (machOrder) {
        this.releaseChange(Number(machOrder.price));
        this.deleteMachProgOrder(order, machOrder);  
      } else {
        // card charge/recharge
        this.releaseChange(Number(order.priceTotal));
        this.deleteOrder(order);
      }
    }).catch((res) => {
      if (res === 'cancel') {
        if (machOrder) { 
          this.deleteMachProgOrder(order, machOrder);          
        } else {
          // card charge/recharge
          this.deleteOrder(order);
        }
      }
    });
  }

  deleteOrder(order) {
    this.backendApi.deleteOrder(order.orderId).subscribe(
      res => {
          this.orderLogs = this.orderLogs.filter(item => (item.orderId !== order.orderId));
      },
      err => {}
    );
  }

  deleteMachProgOrder(order, machOrder) {
    this.backendApi.deleteMachineProgOrder(order.orderId, machOrder.orderMachineProgramId).subscribe(
      res => {
        // Remove order/machineOrder from previous order list.
        order.orderMachinePrograms = order.orderMachinePrograms.filter(item => (item.orderMachineProgramId !== machOrder.orderMachineProgramId));
        if (order.orderMachinePrograms.length === 0) {
          this.orderLogs = this.orderLogs.filter(item => (item.orderId !== order.orderId));
        }
      },
      err => {}
    );
  }

  openReleaseChangePage() {
    swal({
      title: this.translate.getTranslation('RETURNS_TITLE'),
      text: this.translate.getTranslation('RETURNS_MSG'),
      type: 'warning',
      input: 'number',
      showCloseButton: true,
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',    
      confirmButtonText: 'Sim',
      cancelButtonText: 'Não',
      preConfirm: (value) => {
        return new Promise((resolve) => {
          if (value <= 0) {
            swal.showValidationError(this.translate.getTranslation('SEL_POSITIVE_AMOUNT'));
          } else {
            resolve();            
          }
        })
      },
    }).then((value) => {
      if (value && value > 0) {
        value = Math.round(value * 100) / 100;
        this.releaseChange(value);
      }
    }).catch(swal.noop);
  }

  releaseChange(value) {
    // Send change request to low level.
    let pkg = {
      op: 'get-change',
      data: `${parseInt((value*100).toString())}`,
    };
    this.changeValueReq = value;    
    if (this.cloudMode) {
      this.middlewareCloud.send(pkg);
      this.changeRequested = true;
    } else {
      this.middleware.send(pkg);
      this.localChangeRequested = true;
    }
  }

  openRemoteCreditsPage() {
    swal({
      title: this.translate.getTranslation('REMOTE_CREDITS_TITLE'),
      text: this.translate.getTranslation('RETURNS_MSG'),
      type: 'warning',
      input: 'number',
      showCloseButton: true,
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',    
      confirmButtonText: 'Sim',
      cancelButtonText: 'Não',
      preConfirm: (value) => {
        return new Promise((resolve) => {
          if (value <= 0) {
            swal.showValidationError(this.translate.getTranslation('SEL_POSITIVE_AMOUNT'));
          } else {
            resolve();            
          }
        })
      },
    }).then((value) => {
      if (value && value > 0) {
        value = Math.round( (Math.round((Math.round(value * 100) / 100) / 0.05) * 0.05) * 100 ) / 100;

console.log(value);

        this.sendCredits(value);
      }
    }).catch(swal.noop);
  }

  sendCredits(value) {
    // Send credits request to low level.
    let pkg = {
      op: 'remote-credits',
      data: `${parseInt((value*100).toString())}`,
    };
    this.sentCreditValue = value;    

    this.middlewareCloud.send(pkg);
    this.creditsRequested = true;
  }

  selectedDate(value, datepicker?: any) {
    datepicker.start = value.start;
    datepicker.end = value.end;
    this.daterange.start = value.start; this.startDate = value.start;
    this.daterange.end = value.end; this.endDate = value.end;
    this.daterange.label = value.label;
    
    this.getPage1(1, false);
    this.getPage2(1, false);
    this.getPage3(1, false);
    this.getPage4(1, false);
    this.noResult1 = true;
    this.noResult2 = true;
    this.noResult3 = true;
    this.noResult4 = true;
  }

  dateSelected() {
    if (this.startDate && this.endDate) {
      this.getPage1(1, false);      
      this.getPage2(1, false);      
      this.getPage3(1, false);
      this.getPage4(1, false);
      this.noResult1 = true;
      this.noResult2 = true;
      this.noResult3 = true;     
      this.noResult4 = true;     
    }
  }

  creditsNotification(value) {
    let cssClass = 'toast-success';
    let msg = this.translate.getTranslation('CREDITS_SUCC_MSG');
    let toast = this.toastCtrl.create({
      message: msg,
      duration: 4000,
      position: 'top',
      cssClass: cssClass,
    });
    toast.present();

    // // Send change return registration.
    this.backendApi.setCreditsReg(this.laundryId, { creditValue: this.sentCreditValue }).subscribe(res => {},err => {});
  }

  changeNotification(value) {
    let cssClass = 'toast-success';
    let msg = this.translate.getTranslation('RETURN_SUCC_MSG');
    if (value !== '0') {
      cssClass = 'toast-failure';
      msg = this.translate.getTranslation('RETURN_ERR_MSG') + (Number(value)/100).toFixed(2) + ' €';
    }
    let toast = this.toastCtrl.create({
      message: msg,
      duration: 4000,
      position: 'top',
      cssClass: cssClass,
    });
    toast.present();

    // Send change return registration.
    this.backendApi.setReturnsReg(this.laundryId, { retValue: this.changeValueReq - Number(value)/100 }).subscribe(res => {},err => {});
  }

  onResize($event) {
    if (window.innerWidth <= 767) {
      this.endDate = new Date(this.endDate).toISOString();
      this.startDate = new Date(this.startDate).toISOString();
      this.tabletMode = true;
    } else {
      this.endDate = new Date(this.endDate);
      this.startDate = new Date(this.startDate);
      this.tabletMode = false;      
    }
  }
}



