import { Component, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { NavController, ModalController, NavParams, ViewController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';
import { DatePipe } from '@angular/common';

// Page components.
import { AlertPage } from '../alert/alert';

// Service/provider components.
import { TranslateService } from '../../translate';
import { Orders } from '../../providers/orders';
import { Client } from '../../providers/client';
import { Middleware } from '../../providers/middleware';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { HelpTour } from '../../providers/help-tour';
import { Machines } from '../../providers/machines';
import { OfflineData } from '../../providers/offline-data';
import { UnsavedOrders } from '../../providers/unsaved-orders';


@Component({
  selector: 'page-nif-confirmation',
  templateUrl: 'nif-confirmation.html'
})
export class NifConfirmationPage implements OnDestroy {

  smCardImg: string = 'assets/img/sm-card.png';
  smCoinsImg: string = 'assets/img/sm-coins.png';

  page: string = 'NifConfirmationPage';  

  storage: any = new Storage();

  processStateImg: string = 'assets/img/ambiente_2.png';
  cartImg: string = "assets/img/cart-blue.png";

  nif: string = null;
  // Form inputs
  formFields: Array<any> = [
    { id: 'nif-confirmation-nif', value: null },
  ];
  useNif: boolean = false;

  totalCost: number = 0.00;
  missingBalance: number = 0.00;
  balance: number = 0.00;
  clientCard: boolean = false;
  clientSubs: Subscription = null;
  middlewareSubs: Subscription = null;

  change: number = 0.00;
  actMsg: Array<any> = [];

  credit: number = 0.00;

  company: any = {
    name: null,
    addr: null,
    nif: null,
    laundryId: null,
  };

  clientAux: any = null;

  datePipe = new DatePipe('pt-PT');
  dateFormat = 'dd/MM/yyyy HH:mm';

  processingMoneyOrder: boolean = false;

  popToRoot: boolean = true;

  print: boolean = false;
  cardWriErrTimeout: number = 20*1000;
  timer: any = null;

  processingOrder: boolean = false;

  requestedChange: number = null;
  unavailableChange: number = null;

  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private modalCtrl: ModalController,
              private viewCtrl: ViewController,
              private translate: TranslateService,
              private changeDetector: ChangeDetectorRef,
              private orders: Orders,
              private client: Client,
              private middleware: Middleware,
              private backendApi: BackendApiProvider,
              private help: HelpTour,
              private offlineData: OfflineData,
              private unsavedOrders: UnsavedOrders,
              private machines: Machines) {
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (laundryInfo) {
        this.company = laundryInfo;
      }
    });

    // Get change for parent component.
    this.change = this.navParams.data.change;
    this.actMsg = this.navParams.data.actMsg;

    this.formFields[0].value = this.client.getNif();
    if (this.formFields[0].value === 'null') {
      this.formFields[0].value = null;
    }
    
    this.balance = this.client.getBalance();

    if ((this.client.getCardNumber() !== null)) {
      this.clientCard = true;
      this.clientAux = Object.assign({}, this.client.client);
    }

    this.setTotal();

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg) return;

        switch (pkg.op) {
          case 'no-change':
            this.credit = Number(pkg.data) / 100;
            this.unavailableChange = Number(pkg.data) / 100;
            
            this.concludeOrder();
            break;
          case 'write-card':
            clearTimeout(this.timer);
            if (pkg.hasOwnProperty('code') && pkg.code === '201') {
              this.concludeOrder();
            }
            if (pkg.hasOwnProperty('code') && pkg.code !== '200' && pkg.code !== '201') {
              let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'CARD_PURCHASE_ERROR_TITLE', msg: 'CARD_PURCHASE_ERROR_MSG' });
              modalPage.onDidDismiss(
                res => { 
                  this.orders.reset();
                  if (this.navCtrl.getActive().instance.page !== 'StartPage') {
                    this.navCtrl.popToRoot();
                  }
              });
              modalPage.present();
            }              
            break;
        }
      }
    );

    // Handle client updates.
    this.clientSubs = this.client.getClient().subscribe(
      client => {
        this.balance = client.balance;
        this.changeDetector.detectChanges();
      }
    );
  }

  ngOnDestroy() {
    this.help.cancelTour();
    if (this.clientSubs) this.clientSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
  }

  setTotal() {
    // Payment with laundry card.
    let key = null;
    (this.clientCard) ? key = 'selPriceCard' : key = 'selPrice';
    this.totalCost = this.orders.get()
      .map(el => el.program[key])
      .reduce((prevVal, el) => prevVal + Number(el), 0.00);
  }

  selectNif(selected) {
    this.useNif = selected;    
    if (selected) {      
      this.print = true;
    } else {
      this.print = false;
    }
  }

  goToPrevPage() {
    if (this.processingOrder) return;    
    if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
  }

  completeOrder() {
    this.client.sendChargeResquest(this.client.getCardNumber());

    if (this.processingOrder) return;
    this.processingOrder = true;

    this.help.cancelTour();

    if (this.useNif) {
      if (this.clientCard) {
        this.sendChargeReq();
        this.processingMoneyOrder = true;
        this.simpleChangeRequest(this.client.client.balance)
      } else {
        // Change request.
        this.changeRequest();
        this.processingMoneyOrder = true;
      }
    } else {
      let successPage = this.modalCtrl.create(AlertPage, { type: 'receipt', title: 'RECEIPT_TITLE', msg: 'RECEIPT_MSG' });
      successPage.onDidDismiss(
        res => {
          if (res && res.hasOwnProperty('confirm') && res.confirm) {
            this.print = true;
          } else {
            this.print = false;
          }
          if (this.clientCard) {
            this.sendChargeReq();
            this.processingMoneyOrder = true;
            this.simpleChangeRequest(this.client.client.balance)
          } else {
            // Change request.
            this.changeRequest();
            this.processingMoneyOrder = true;
          }
        }
      );
      successPage.present();
    }
  }

  sendChargeReq() {
    let pkg =   {
      op: 'write-card',
      data: {
        cardId: this.client.client.cardNumber,
        name: this.client.client.name,
        nif: this.clientAux.nif,
        balance: ((this.clientAux.balanceCard - this.totalCost) * 100).toString(),
        new: false,
        admin: false,
      },
    };
    this.middleware.send(pkg);
    
    this.timer = setTimeout(() => {
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'CARD_PURCHASE_ERROR_TITLE', msg: 'CARD_PURCHASE_ERROR_MSG' });
      modalPage.onDidDismiss(
        res => {
          this.orders.reset();
          if (this.navCtrl.getActive().instance.page !== 'StartPage') {
            this.navCtrl.popToRoot();
          }
      });
      modalPage.present();
    }, this.cardWriErrTimeout);
  }

  concludeOrder() {
    this.popToRoot = false;
    
    // Request with all the data needed to print the client receipt.
    if (this.print || this.credit >= 0.05) {
      this.receiptRequest();      
    }

    // Machine activation request (signal to enable the machines selected/paid by the client).
    this.activationRequest();

    // Send order request.
    let body = this.getOrderRegObj();
    let inMoney = (this.totalCost && this.requestedChange) ? this.totalCost + this.requestedChange : null;
    let outMoney = (this.requestedChange && this.unavailableChange !== null) ? this.requestedChange - this.unavailableChange : null;

    let inCredit = 0;
    if (this.client.client['credits']) {
      let aux = (this.unavailableChange !== null) ? this.unavailableChange : 0;
      inCredit = this.client.client['credits'] - aux;
    }

    this.backendApi.setOrders(body, inMoney, outMoney, inCredit).subscribe(
      res => {},
      err => { this.unsavedOrders.addRecords('orders/neworder', body); }
    );

    // Show alert if change is unavailable.
    if (this.credit >= 0.05) {
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'info', title: 'INFO_TITLE', msg: 'NO_CHANGE_MSG' });
      modalPage.onDidDismiss(
        res => {
          this.client.reset();
          this.orders.reset();

          if (this.navCtrl.getActive().instance.page !== 'StartPage') {
            this.navCtrl.popToRoot();
          }
        }
      );
      modalPage.present();
    } else {
      let successPage = this.modalCtrl.create(AlertPage, { type: 'success', title: 'SUCCESS_TITLE', msg: 'SUCCESS_MSG' });
      successPage.onDidDismiss(
        res => {
          this.client.reset();
          this.orders.reset();

          if (this.navCtrl.getActive().instance.page !== 'StartPage') {
            // this.navCtrl.popToRoot();
            this.navCtrl.popTo(this.navCtrl.getByIndex(0));
          }
        }
      );
      successPage.present();
    }
  }

  simpleChangeRequest(change) {
    if (change >= 0.10) {
      this.requestedChange = Number((Math.round(this.change * 100) / 100).toFixed(2));

      let pkg =   {
        op: 'get-change',
        data: `${parseInt(Math.round(change*100).toString())}`,
      };
      this.middleware.send(pkg);
    }
  }

  changeRequest() {
    this.requestedChange = Number((Math.round(this.change * 100) / 100).toFixed(2));

    let pkg =   {
      op: 'get-change',
      data: `${parseInt(Math.round(this.change*100).toString())}`,
    };
    this.middleware.send(pkg);

    // Timeout to conclude order in case get-change response do not reach the app.
    setTimeout(() => {
      if (this.popToRoot) {
        this.credit = this.change;
        this.concludeOrder();  
      }
    }, 60*1000);
  }

  receiptRequest() {
    // Credit print message
    let creditMsg = null;
    if (this.credit >= 0.05) {
      creditMsg = `CREDITO: (EUR)${this.formatPrice(this.credit)}`;
    }
    // Total print message
    let totalMsg = `(EUR)${this.formatPrice(this.totalCost)}`;
    // Orders print message.
    let ordersObj = [];
    let key = null;
    (this.clientCard) ? key = 'selPriceCard' : key = 'selPrice';
    this.orders.get().forEach(item => {
      ordersObj.push({
        serv: `${item.machine.name} (${item.program.program.name})`,
        price: item.program[key],
      });
    });

    if (this.client.client.balanceCard > this.client.client.initBalance) {
      let actualCardBalance = this.clientAux.balanceCard - this.totalCost;
      let chargeValue = actualCardBalance - this.client.client.initBalance - this.client.client.bonus;
      if (chargeValue > 0) {
        ordersObj.push({
          serv: `Carregamento de cartao`,
          price: `${this.formatPrice(chargeValue)}`,
        });
        totalMsg = `(EUR)${this.formatPrice(this.totalCost + chargeValue)}`;
        this.client.client.chargedArr = [];
      }
    }

    // Send receipt request to low level.
    let pkg =   {
      op: 'print-receipt',
      data: {
        company: {
          name: (this.company.name) ? this.company.name : ' ',
          ownerName: (this.company.ownerName) ? this.company.ownerName :' ',
          addr: (this.company.addr) ? this.company.addr : ' ',
          nif: (this.company.nif) ? 'Nif: ' + this.company.nif : ' ',
          phone: (this.company.phone) ? 'Tel: ' + this.company.phone : ' ',
          email: (this.company.email) ? this.company.email : ' ',
        },
        orders: ordersObj,
        total: totalMsg,
        client: {
          name: (this.client.getName() && this.client.getName() !== 'SEM NOME') ? 'Nome: ' + this.client.getName() : ' ',
          nif: (this.formFields[0].value) ? 'Nif: ' + this.formFields[0].value : ' ',
        },
        credit: creditMsg,
        date: this.datePipe.transform(new Date(), this.dateFormat),
      },
    };
    this.middleware.send(pkg);
  }

  activationRequest() {
    let pkg = {
      op: 'activate-machine',
      data: this.actMsg,
    };
    this.middleware.send(pkg);
    // Set Reservation Idle
    this.actMsg.forEach(item => {
      this.machines.setReservation(item.id, item.chn);
    });
  }

  getOrderRegObj() {
    let price = null;
    let obj = {
      cardNumber: this.client.getCardNumber(),
      nif: this.formFields[0].value,
      expense: true,
      priceTotal: this.totalCost,
      laundryId: this.company.laundryId,
      orders: [],
    };

    // Iterate over all orders.
    this.orders.orders.forEach(item => {
      (this.client.getCardNumber() === null) ? price = Number(item.program.selPrice) : price = Number(item.program.selPriceCard);
      obj.orders.push({
        price: price,
        machineProgramId: item.program.machineProgramId,
        impulses: (item.program.impulses) ? item.program.impulses : 1,
      });
    });
    return obj;
  }

  formatPrice(price) {
    return price.toFixed(2);
  }

  goBack() {
    if (this.processingOrder) return;
    this.navCtrl.pop();
  }

  keyboardEv(key) {
    if (this.formFields[0].value && key !== 'CLEAR' && this.formFields[0].value.length >= 10) return;

    if (key === 'CLEAR') {
      this.formFields[0].value = this.formFields[0].value.slice(0, -1);
    } else {
      if (this.formFields[0].value) {
        this.formFields[0].value = this.formFields[0].value + key;        
      } else {
        this.formFields[0].value = key;        
      }
    }
  }

}



