import { Component, OnDestroy } from '@angular/core';
import { NavParams } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-pricing-table',
  templateUrl: 'pricing-table.html'
})
export class PricingTablePage implements OnDestroy {

  coinBonus: number = null;  
  billBonus: number = null;

  lauConfig: any = null;

  // Permissions.
  updPriEnabled: boolean = false;

  prices: Array<any> = null;
  pricesCpy: Array<any> = null;
  dataSubs: Subscription = null;
  hasWasMachines: boolean = false;
  hasDryMachines: boolean = false;
  ready: boolean = false;
  readOnly: boolean = false;

  constructor(private navParams: NavParams,
              private translate: TranslateService,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private backendApi: BackendApiProvider,
              private userSession: UserSession) {
    this.updPriEnabled = this.userSession.getPermission('machine-price');

    // Handle incoming data.
    this.dataSubs = this.cs.getData().subscribe(
      res => {
        if (res.dest != 'pricing-table') return;

        if (res.hasOwnProperty('flag') && res.flag === 'laundry') {
          if (!res.data.obj.hasOwnProperty('autoCharge')) {
            res.data.obj.autoCharge = false;
          }
          this.lauConfig = JSON.parse(JSON.stringify(res.data));
        } else {
          this.prices = res.data;

          let initPriceUpdate = [];
          // Program duration handling
          this.prices.forEach(el => {
            if (el.program.type === 'WASH' && !el.duration) {
              el.duration = el.program.duration;
              initPriceUpdate.push(JSON.parse(JSON.stringify(el)));
            }
          });
          if (initPriceUpdate.length > 0) {
            initPriceUpdate.forEach(el => { el.action = 'update' });
            this.backendApi.setPrograms(initPriceUpdate).subscribe(
              res => {
                this.cs.setCommand({ src: 'pricing-table', dest: 'laundry-configuration', cmd: 'save-init' });
              },
              err => {}
            );
          }

          this.pricesCpy = this.cf.getCopy(this.prices);
          (this.pricesCpy.find(el => (el.program.type === 'WASH'))) ? this.hasWasMachines = true : this.hasWasMachines = false;
          (this.pricesCpy.find(el => (el.program.type === 'DRY'))) ? this.hasDryMachines = true : this.hasDryMachines = false;

          this.ready = true;
        }
      }
    );

    // Send prices request.
    this.cs.setCommand({ src: 'pricing-table', dest: 'laundry-configuration', cmd: 'get-prices' });

    // Send configuration request.
    this.cs.setCommand({ src: 'pricing-table', dest: 'laundry-configuration', cmd: 'get-laundry-configs' });
  }

  ngOnDestroy() {
    if (this.dataSubs) this.dataSubs.unsubscribe();
  }

  focusOut(price) {
    if (!this.readOnly) {
      if (this.prices.find(el => (el.machineProgramId === price.machineProgramId)).price !== price.price ||
          this.prices.find(el => (el.machineProgramId === price.machineProgramId)).priceCard !== price.priceCard ||
          this.prices.find(el => (el.machineProgramId === price.machineProgramId)).priceApp !== price.priceApp ||
          this.prices.find(el => (el.machineProgramId === price.machineProgramId)).duration !== Number(price.duration)) {
        price.action = 'update';
        this.prices = JSON.parse(JSON.stringify(this.pricesCpy));
        this.cs.setData({ src: 'pricing-table', dest: 'laundry-configuration', data: this.prices });
      }
    }
  }

  setCardMode() {
    this.cs.setData({ src: 'pricing-table', dest: 'laundry-configuration', data: this.lauConfig, target: 'laundry' });
  }

  setLaundryCardPrice() {
    if (!this.readOnly) {
      this.lauConfig.obj.minCharge = parseFloat(this.lauConfig.obj.minCharge).toFixed(2);
      this.lauConfig.obj.minRecharge = parseFloat(this.lauConfig.obj.minRecharge).toFixed(2);

      // PARAMETERS FOR NEW RECHARGE WORKFLOW.
      this.lauConfig.obj.cardPrice = parseFloat(this.lauConfig.obj.cardPrice).toFixed(2);
      this.lauConfig.obj.minCardCredit = parseFloat(this.lauConfig.obj.minCardCredit).toFixed(2);
      this.lauConfig.obj.cardCreditInc = parseFloat(this.lauConfig.obj.cardCreditInc).toFixed(2);
      this.lauConfig.obj.rechargeWithChange = this.lauConfig.obj.rechargeWithChange;

      this.cs.setData({ src: 'pricing-table', dest: 'laundry-configuration', data: this.lauConfig, target: 'laundry' });
    }
  }

  save() {
    // Send save request.
    this.cs.setCommand({ src: 'pricing-table', dest: 'laundry-configuration', cmd: 'save' });
  }

  edit() {
    this.readOnly = !this.readOnly;
  }
}



