import { Injectable } from '@angular/core';
import { Storage } from '@ionic/storage';
import { Subject } from 'rxjs/Rx';
import 'rxjs/add/operator/map';

import { Middleware } from './middleware';
import { CommonServices } from './common-services';
import { UnsavedOrders } from './unsaved-orders';

@Injectable()
export class OfflineData {

  storage = new Storage();

  useOfflineData: boolean = false;
  data: any = {
    wasMachines: [],
    dryMachines: [],
    programs: [],
  };

  constructor(private middleware: Middleware,
              private unsavedOrders: UnsavedOrders,
              private cs: CommonServices) {

    this.cs.getData().subscribe(res => {
      if (res.hasOwnProperty('offlineData')) {
        this.data = res.offlineData;
      }
    });
  }

  setNetworkConnection(connected) {
    this.useOfflineData = !connected;
    if (connected) {
      // this.unsavedOrders.saveRecords();
      this.unsavedOrders.init();
    }
  }

  setWashingMachinesConfig(config) {
    if (config === null || (Array.isArray(config) && config.length === 0)) return;
    this.data.wasMachines = config;
    this.updateLocalStorage();
  }

  setDryingMachinesConfig(config) {
    if (config === null || (Array.isArray(config) && config.length === 0)) return;
    this.data.dryMachines = config;
    this.updateLocalStorage();
  }

  setProgramsConfig(config) {
    if (config === null || (Array.isArray(config) && config.length === 0)) return;
    this.data.programs = config;
    this.updateLocalStorage();
  }

  getData(key): any {
    if (this.data.hasOwnProperty(key)) {
      return this.data[key];
    }
    return null;
  }

  updateLocalStorage() {
    this.middleware.setLocalStorage(this.data);
  }
}



