import { Component } from '@angular/core';
import { NavParams, ViewController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';

import { Middleware } from '../../providers/middleware';


@Component({
  selector: 'page-alert-vm',
  templateUrl: 'alert-vm.html'
})
export class AlertVmPage {

  waitingMsgShutdown: string = 'WAITING_SHUTDOWN_MSG';
  waitingMsgUpdate: string = 'WAITING_UPDATE_MSG';

  type: string = null;
  title: string = null;
  msg: string = null;

  isSpinnerOn: boolean = false;

  constructor(private viewCtrl: ViewController,
              private middleware: Middleware,
              private navParams: NavParams) {
    this.type = this.navParams.data.type;
    this.title = this.navParams.data.title;
    this.msg = this.navParams.data.msg;
  }

  confirm() {
    if (this.isSpinnerOn) return;

    if (this.type === 'update') {
      this.isSpinnerOn = true;
      this.msg = this.waitingMsgUpdate;
      this.middleware.updateVM();
      return;
    }

    if (this.type === 'shutdown') {
      this.isSpinnerOn = true;
      this.msg = this.waitingMsgShutdown;
      this.middleware.shutdownPC();
      return;    
    }

    this.viewCtrl.dismiss(true)
  }

  cancel() {
    if (this.isSpinnerOn) return;
    
    this.viewCtrl.dismiss(false);
  }

}



