import { Component, OnDestroy } from '@angular/core';
import { NavController, PopoverController, ModalController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';
import { Md5 } from 'ts-md5/dist/md5';
import { DatePipe } from '@angular/common';

// Page components.
import { BillConfirmationPage } from '../bill-confirmation/bill-confirmation';
import { AlertPage } from '../alert/alert';
import { TermsCondPage } from '../terms-cond/terms-cond';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { Client } from '../../providers/client';  // NOTE: provider used to get the balance.
import { CommonServices } from '../../providers/common-services';
import { Orders } from '../../providers/orders';
import { Middleware } from '../../providers/middleware';
import { Inactivity } from '../../providers/inactivity';
import { HelpTour } from '../../providers/help-tour'
import { AppSettings } from '../../providers/app-settings';
import { Machines } from '../../providers/machines';
import { OfflineData } from '../../providers/offline-data';
import { UnsavedOrders } from '../../providers/unsaved-orders';


@Component({
  selector: 'page-buy-card',
  templateUrl: 'buy-card.html'
})
export class BuyCardPage implements OnDestroy {

  page: string = 'BuyCardPage';

  print: boolean = false;
  termsCondAccepted: boolean = false;

  // Images
  cartImg: string = 'assets/img/carrinho.png';
  cardImg: string = 'assets/img/group.png';
  plusImg: string = 'assets/img/+.png';
  minusImg: string = 'assets/img/-.png';

  smCardImg: string = 'assets/img/sm-card.png';
  smCoinsImg: string = 'assets/img/sm-coins.png';

  storage = new Storage();

  client: Client = null;
  clientSubs: Subscription = null;

  missingValue: number = 0.00;
  changeValue: number = 0.00;

  // Charging parameters
  minChargeValue: number = null;
  maxChargeValue: number = null;
  chargeValue: number = 0.00;
  chargeStep: number = null;

  // Form inputs
  formFields: Array<any> = [
    { id: 'buy-card-name', value: null },
    { id: 'buy-card-nif', value: null },
    { id: 'buy-card-address', value: null },
    { id: 'buy-card-phone', value: null },
    { id: 'buy-card-email', value: null },    
  ];

  cmdSubs: Subscription = null;
  popover: any = null;
  moneyPopover: any = null;
  clientCard: boolean = false;
  orderCount: number = 0;
  orderCountSubs: Subscription = null
  orderTotal: any = null;
  orderTotalSubs: Subscription = null;
  middlewareSubs: Subscription = null;
  credit: number = 0.00;
  company: any = {
    name: null,
    addr: null,
    nif: null,
    laundryId: null,
    pricingObj: { buyChargeEnabled: true }
  };

  newCardReleased: boolean = false;

  datePipe = new DatePipe('pt-PT');
  dateFormat = 'dd/MM/yyyy HH:mm';

  processingOrder: boolean = false;  

  requestedChange: number = null;
  unavailableChange: number = null;

  constructor(private navCtrl: NavController,
              private popoverCtrl: PopoverController,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private offlineData: OfflineData,
              private unsavedOrders: UnsavedOrders,
              private orders: Orders,
              private machines: Machines,
              private appSet: AppSettings,
              private clientInt: Client,
              private middleware: Middleware,
              private inactivityTimer: Inactivity,
              private help: HelpTour) {
    this.storage.get('laundryInfo').then(laundryInfo => {
      if (laundryInfo) {
        this.company = laundryInfo;
        // Charging parameters
        this.minChargeValue = Number(this.company.minCharge);
        this.maxChargeValue = 5*Number(this.company.minCharge);
        this.chargeStep = Number(this.company.minRecharge);

        if (this.company.pricingObj.buyChargeEnabled) {
          this.chargeValue = this.minChargeValue;
          // Initialize missing object.
          this.missingValue = (this.chargeValue - this.client['balance'] < 0) ? 0 : this.chargeValue - this.client['balance'];
          this.changeValue = (this.chargeValue - this.client['balance'] < 0) ? this.client['balance'] - this.chargeValue : 0;  
        } else {
          this.chargeValue = Number(this.company.pricingObj.cardPrice) + Number(this.company.pricingObj.minCardCredit);;
          // Initialize missing object.
          this.missingValue = (this.chargeValue - this.client['balance'] < 0) ? 0 : this.chargeValue - this.client['balance'];
          this.changeValue = (this.chargeValue - this.client['balance'] < 0) ? this.client['balance'] - this.chargeValue : 0;  
        }
      }
    });

    // Initialize client object.
    this.client = this.clientInt.client;

    // Handle client updates.
    this.clientSubs = this.clientInt.getClient().subscribe(
      client => {
        this.client = client;
        // Update missing money.
        this.missingValue = (this.chargeValue - client['balance'] < 0) ? 0 : this.chargeValue - client['balance'];
        this.changeValue = (this.chargeValue - this.client['balance'] < 0) ? this.client['balance'] - this.chargeValue : 0;
      }
    );

    // Handle commands sent by other components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'buy-card') return;

        // Handle inccoming commands from billing-info  popover.
        if (res.src === 'billing-info') {
          switch(res.cmd) {
            case 'cancel':
              let pkg = {
                op: 'cancel-orders'
              };
              this.machines.updateMachineState(pkg);
              this.orders.reset();
              break;
            case 'finish':
              this.navCtrl.push(BillConfirmationPage);
              break;
          }
        }

        if (res.src === 'money-recovery' && res.cmd === 'money-recovery') {
          // Realease money and reset vending app
          this.inactivityTimer.setInactivitySignal();
        }

      }
    );

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg) return;

        if (!pkg.hasOwnProperty('code')) {
          switch (pkg.op) {
            case 'no-change':
              this.credit = Number(pkg.data) / 100;
              this.unavailableChange = Number(pkg.data) / 100;
              this.concludeOrder();
              break;
          }
        }
      }
    );

    // Initialize order count.
    this.orderCount = this.orders.get().length;
    // Handle order count updates.
    this.orderCountSubs = this.orders.getCount().subscribe(
      count => {
        this.orderCount = count;
      }
    );

    // Initialize order price.
    this.orderTotal = this.orders.total;
    // Get total order price.
    this.orderTotalSubs = this.orders.getTotalPrice().subscribe(
      totalPrice => { this.orderTotal = totalPrice }
    );
  }



  tooltipRecHidden: boolean = true;
  openMoneyRecovery(event) {
    if (!this.tooltipHidden) return;
  
    this.headerClickEnabled = false;
    setTimeout(() => { this.headerClickEnabled = true; }, 250);
  
    if (this.tooltipRecHidden) {
      this.storage.get('laundryInfo').then(laundryInfo => {
        if (this.client['balance'] > 0 && laundryInfo.changeEnabled) {
          this.tooltipRecHidden = false;  
        }
      });
    } else {
      this.tooltipRecHidden = true;
    }
  }
  getMoney() {
    this.cs.setCommand({ src: 'money-recovery', dest: 'buy-card', cmd: 'money-recovery' });
  }



  tooltipHidden: boolean = true;
  headerClickEnabled: boolean = true;
  cartTotalPrice: number = 0.00;
  cartTotalPriceCard: number = 0.00;
  cartDeleteOrderImg: string = 'assets/img/remover.png';
  cartCardImg: string = 'assets/img/cartao-icon.png';
  cartCoinImg: string = 'assets/img/moedas-icon.png';
  openShoppingCard(event) {
    if (!this.tooltipRecHidden) return;

    this.headerClickEnabled = false;
    setTimeout(() => { this.headerClickEnabled = true; }, 250);

    if (this.tooltipHidden) {
      if (this.orders.get().length > 0) {
        this.cartTotalPrice = this.orders.get().map(el => el.program['selPrice']).reduce((prevVal, el) => prevVal + Number(el), 0.00);
        this.cartTotalPriceCard = this.orders.get().map(el => el.program['selPriceCard']).reduce((prevVal, el) => prevVal + Number(el), 0.00);
        this.tooltipHidden = false;
      }
    } else {
      this.tooltipHidden = true;
    }
  }
  clickOnPage() {
    if (!this.tooltipHidden) this.tooltipHidden = true;
    if (!this.tooltipRecHidden) this.tooltipRecHidden = true;
  }
  clickOnHeader() {
    if (!this.tooltipHidden && this.headerClickEnabled) {
      this.tooltipHidden = true;
    }
    if (!this.tooltipRecHidden && this.headerClickEnabled) {
      this.tooltipRecHidden = true;
    }
  }
  cancelTooltip() {
    this.tooltipHidden = true;  
    this.cs.setCommand({ src: 'billing-info', dest: 'buy-card', cmd: 'cancel' });
  }
  finishTooltip() {
    this.tooltipHidden = true;  
    this.cs.setCommand({ src: 'billing-info', dest: 'buy-card', cmd: 'finish' });
  }








  ngOnDestroy() {
    this.help.cancelTour();
    if (this.clientSubs) this.clientSubs.unsubscribe();
    if (this.cmdSubs) this.cmdSubs.unsubscribe();
    if (this.orderCountSubs) this.orderCountSubs.unsubscribe();
    if (this.orderTotalSubs) this.orderTotalSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    this.clickOnPage();
  }

  toggleClientCard() {
    this.clientCard = !this.clientCard;
  }

  setChargeValue(action) {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    switch (action) {
      case 'INC':
        this.chargeValue += this.chargeStep;
        if (this.chargeValue > this.maxChargeValue) {
          this.chargeValue -= this.chargeStep;
        }
        break;
      case 'DEC':
        this.chargeValue -= this.chargeStep;
        if (this.chargeValue < this.minChargeValue) {
          this.chargeValue += this.chargeStep;
        }
        break;
    }
    // Update missing money.
    this.missingValue = (this.chargeValue - this.client['balance'] < 0) ? 0 : this.chargeValue - this.client['balance'];
    this.changeValue = (this.chargeValue - this.client['balance'] < 0) ? this.client['balance'] - this.chargeValue : 0;    
  }

  cancel() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (this.processingOrder) return;    
    // Leave page.
    if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
  }

  finish() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    if (this.processingOrder) return;
    if (!this.termsCondAccepted && this.formHasData()) {
      this.termsCondTooltip();
      return;
    } else {
      this.help.cancelTermsTour();
    }
    this.help.cancelTour();

if (this.missingValue <= 0) {
  let successPage = this.modalCtrl.create(AlertPage, { type: 'receipt', title: 'RECEIPT_TITLE', msg: 'RECEIPT_MSG' });
  successPage.onDidDismiss(
    res => {
      if (res && res.hasOwnProperty('confirm') && res.confirm) {
        this.print = true;
      } else {
        this.print = false;
      }

        // Disable buttons (finalize and cancel)
        this.processingOrder = true;        


        // Send client new card request to low-level.
        this.releaseCardRequest();

        let cardData = {
          name: this.formFields[0].value,
          nif: this.formFields[1].value,
          balance: (this.company.pricingObj.buyChargeEnabled) ? this.chargeValue : this.chargeValue - Number(this.company.pricingObj.cardPrice),
          cardId: this.clientInt.client.cardNumber,
        }
        let insertCardPage = this.modalCtrl.create(AlertPage, { type: 'card-charge', title: 'INSERT_CARD_TITLE', msg: 'INSERT_CARD_MSG', cardData: cardData }, { enableBackdropDismiss: false });
        insertCardPage.onDidDismiss(
          confirm => {
            if (!confirm) return;
            if (confirm.confirm) {
              this.changeRequest();
              
              let body = {
                laundry_laundryId: this.company.laundryId,
                cardNumber: this.clientInt.client.cardNumber,
                priceTotal: this.chargeValue,

                type: 'BUY_CARD',
                priceCard: Number(this.company.pricingObj.cardPrice),
                cardBalance: (this.company.pricingObj.buyChargeEnabled) ? this.chargeValue : this.chargeValue - Number(this.company.pricingObj.cardPrice),

                name: this.formFields[0].value,
                nif: this.formFields[1].value,
                mobileNumber: this.formFields[3].value,
                addressLine1: this.formFields[2].value,
              };
              if (this.isEmail(this.formFields[4].value) && this.formFields[4].value) {
                body['email'] = this.formFields[4].value;
              }

              let inMoney = (this.chargeValue && this.requestedChange) ? this.chargeValue + this.requestedChange : null;
              let outMoney = (this.requestedChange && this.unavailableChange !== null) ? this.requestedChange - this.unavailableChange : null;              
              this.backendApi.newCard(body, inMoney, outMoney).subscribe(
                  res => {},
                  err => { this.unsavedOrders.addRecords('card/newcard', body); }
              );

              let pkg = {
                op:"card-inserted",
                data: {
                  name: this.formFields[0].value,
                  nif: this.formFields[1].value,
                  balance: (this.company.pricingObj.buyChargeEnabled) ? (this.chargeValue*100).toString() : ((this.chargeValue - Number(this.company.pricingObj.cardPrice))*100).toString(),
                  cardId: this.clientInt.client.cardNumber,
                  new: false,
                  admin: false,
                },
              };
              setTimeout(() =>{ this.middleware.lowLevelEmulator(pkg) }, 500);
            } else {
              let errorPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'CHARGE_ERROR_TITLE', msg: 'CHARGE_ERROR_MSG' });
              errorPage.onDidDismiss(
                res => {
                  this.credit = Math.round(this.clientInt.getBalance());
                  if (!this.company.pricingObj.buyChargeEnabled) {
                    this.credit = this.credit - Number(this.company.pricingObj.cardPrice);
                  }
                  this.clientInt.resetBalance();
                  this.receiptRequest();

                  this.orders.reset();
                  if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
                }
              );
              errorPage.present();
            }
          }
        );
        insertCardPage.present();      
    });
    successPage.present();
} else {
  // Insufficient balance alert.
  let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'INSUFFICIENT_BALANCE_TITLE', msg: 'INSUFFICIENT_BALANCE_MSG' });
  modalPage.present();
} 
  }

  releaseCardRequest() {
    this.newCardReleased = true;
    let pkg = {
      op: 'card-release',
    }
    this.middleware.send(pkg);
  }

  updateBalance() {
    this.client['balance'] -= this.chargeValue;
    this.clientInt.setClient();
  }

  concludeOrder() {
    // Request with all the data needed to print the client receipt.
    if (this.print || this.credit >= 0.05) {
      this.receiptRequest();      
    }
 
    // Show alert if change is unavailable.
    if (this.credit >= 0.05) {
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'info', title: 'INFO_TITLE', msg: 'NO_CHANGE_MSG' });
      modalPage.onDidDismiss(
        res => {
          let successPage = this.modalCtrl.create(AlertPage, { type: 'success', title: 'CHARGE_SUCCESS_TITLE', msg: 'CHARGE_SUCCESS_MSG' });
          successPage.onDidDismiss(
            confirm => {
              // Reset app and go to root page.
              this.orders.reset();
              if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
            }
          );
          successPage.present();
        }
      );
      modalPage.present();
    } else {
      let successPage = this.modalCtrl.create(AlertPage, { type: 'success', title: 'SUCCESS_TITLE', msg: 'SUCCESS_MSG' });
      successPage.onDidDismiss(
        res => {
          // Reset app and go to root page.
          this.orders.reset();
          if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
        });
      successPage.present();
    }
  }

  changeRequest() {
    this.requestedChange = Number((Math.round((this.clientInt.getBalance() - this.chargeValue)*100) / 100).toFixed(2));
    let pkg =   {
      op: 'get-change',
      data: `${parseInt(Math.round((this.clientInt.getBalance() - this.chargeValue)*100).toString())}`,
    };
    this.clientInt.resetBalance();
    this.middleware.send(pkg);
  }

  receiptRequest() {
    // Credit print message
    let creditMsg = ' ';
    if (this.credit >= 0.05) {
      creditMsg = `CREDITO: (EUR)${this.formatPrice(this.credit)}`;
    }
    // Total print message
    let totalMsg = `(EUR)${this.formatPrice(this.chargeValue)}`;
    // Orders print message.
    let ordersObj = [{
      serv: `Compra de cartao`,
      price: `${this.formatPrice(this.chargeValue)}`,
    }];

    // Send receipt request to low level.
    let pkg =   {
      op: 'print-receipt',
      data: {
        company: {
          name: (this.company.name) ? this.company.name :' ',
          ownerName: (this.company.ownerName) ? this.company.ownerName :' ',
          addr: (this.company.addr) ? this.company.addr : ' ',
          nif: (this.company.nif) ? 'Nif: ' + this.company.nif : ' ',
          phone: (this.company.phone) ? 'Tel: ' + this.company.phone : ' ',
          email: (this.company.email) ? this.company.email : ' ',          
        },
        orders: ordersObj,
        total: totalMsg,
        client: {
          name: (this.formFields[0].value && this.formFields[0].value !== 'SEM NOME') ? 'Nome: ' + this.formFields[0].value : ' ',
          nif: (this.formFields[1].value) ? 'Nif: ' + this.formFields[1].value : ' ',
        },
        credit: creditMsg,
        date: this.datePipe.transform(new Date(), this.dateFormat),
      },
    };
    this.middleware.send(pkg);
  }

  formatPrice(price) {
    return price.toFixed(2);
  }

  goBack() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;
    
    if (this.processingOrder) return;    
    this.navCtrl.pop();
  }

  formHasData() {
    let aux = false;
    this.formFields.forEach(item => {
      if (item.value) aux = true;
    });
    return aux;
  }

  termsCondTooltip() {
    this.help.startTour('TERMS_COND');
    setTimeout(() => { this.help.cancelTermsTour(); }, 5000);
  }

  clearTooltip() {
    this.help.cancelTermsTour();
  }

  openTermsCond() {
    if (!this.tooltipHidden || !this.tooltipRecHidden) return;

    let modalPage = this.modalCtrl.create(TermsCondPage);
    modalPage.onDidDismiss(
      res => {
        if (res === null || typeof res === 'undefined') {
          this.termsCondAccepted = false;
          return;
        }        
        if (res.hasOwnProperty('accept') && res.accept) {
          this.termsCondAccepted = true;
        }
        if (res.hasOwnProperty('accept') && !res.accept) {
          this.termsCondAccepted = false;
        }
      }
    );
    modalPage.present();
  }

  isEmail(email) {
    let reg = /\S+@\S+\.\S+/;
    if (reg.test(email) && email.trim() !== '') {
      return true;
    } else {
      return false;
    }
  }
}



