import { Component, OnDestroy } from '@angular/core';
import { NavParams, ModalController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Geolocation } from '@ionic-native/geolocation';
import { Storage } from '@ionic/storage';

// Page components.
import { ListSeletionPage } from '../list-seletion/list-seletion';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { UserSession } from '../../providers/user-session';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;


@Component({
  selector: 'page-laundry',
  templateUrl: 'laundry.html'
})
export class LaundryPage implements OnDestroy {

  // Permissions.
  updLauEnabled: boolean = false;
  delLauEnabled: boolean = false;

  fineAdjust: boolean = false;
  ready: boolean = false;
  activeSection: string = 'laundry';
  laundryImg: string = "assets/img/laundry.jpg";
  dataSubs: Subscription = null;
  lauConfigs: any = null;
  readOnly: boolean = false;

  lat: number = null;
  lng: number = null;
  zoom: number = 17;
  selectedLat: number = null;
  selectedLng: number = null;

  mobileAppEnabled: boolean = false;

  cloudMode: boolean = true;
  storage: any = new Storage();      

  constructor(private modalCtrl: ModalController,
              private translate: TranslateService,
              private geolocation: Geolocation,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private middlewareCloud: MiddlewareCloud,
              private middleware: Middleware,
              private userSession: UserSession) {
    // Enable/disable insert new laundry option.
    this.updLauEnabled = this.userSession.getPermission('laundry-update');
    this.delLauEnabled = this.userSession.getPermission('laundry-delete');

    // Handle incoming data.
    this.dataSubs = this.cs.getData().subscribe(
      res => {
        if (res.dest !== 'laundry') return;
        this.lauConfigs = res.data;
        if (this.lauConfigs.name !== '') {
          this.lat = Number(this.lauConfigs.address.lat);
          this.lng = Number(this.lauConfigs.address.lng);
          this.fineAdjust = false;
          this.zoom = 17;
        } else {
           this.geolocation.getCurrentPosition().then((res) => {
           this.lat = Number(res.coords.latitude);
           this.lng = Number(res.coords.longitude);
           this.fineAdjust = false;
           this.zoom = 17;
          }).catch((err) => {});         
        }

        if (!this.lauConfigs.obj) {
          this.lauConfigs.obj = {
            changeEnabled: false,
            minRecharge: null,
            minCharge: null,
          };
        }

        this.storage.get('laundryInfo').then(laundryInfo => {
          if (laundryInfo && laundryInfo.laundryId === this.lauConfigs.laundryId) this.cloudMode = false;
        });

        this.ready = true;
      }
    );
    this.cs.setCommand({ src: 'laundry', dest: 'laundry-configuration', cmd: 'get-laundry-configs' });
  }

  ngOnDestroy() {
    if (this.dataSubs) this.dataSubs.unsubscribe();
  }

  edit() {
    this.readOnly = !this.readOnly;
  }

  save() {
    this.cs.setCommand({ src: 'laundry', dest: 'laundry-configuration', cmd: 'save' });
  }

  delete() {
    this.cs.setCommand({ src: 'laundry', dest: 'laundry-configuration', cmd: 'delete'});
  }

  sendLaundryConfigs() {
    this.cs.setData({ src: 'laundry', dest: 'laundry-configuration', data: this.lauConfigs });
  }

  rebootVmApp() {
    swal({
      title: this.translate.getTranslation('ALERT_REBOOT_TITLE'),
      text: this.translate.getTranslation('ALERT_REBOOT_MSG'),
      type: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',
      confirmButtonText: this.translate.getTranslation('YES'),
      cancelButtonText: this.translate.getTranslation('NO'),
    }).then(() => {
      if (this.cloudMode) {
        this.middlewareCloud.rebootPC();
      } else {
        this.middleware.rebootPC();
      }
    }).catch(swal.noop);
  }

  getOwners() {
    let modalArgs = {
      title: 'SELECT_OWNER_TITLE',
      list: [],
      titleKey: '',
      subTitleKey: '',
      type: 'OWNERS',
      getTitle: function(obj) {
        let nameLabel = this.translate.getTranslation('NAME');
        let name = obj.name;
        if (name === null || name === '') name = this.translate.getTranslation('SEM NOME');
        return `${nameLabel}: ${name}`;
      },
      getSubtitle: function(obj) {
        let nifLabel = this.translate.getTranslation('NIF');
        let nif = obj.nif;
        if (!nif) nif = '---';
        return `${nifLabel}: ${nif}`;
      },
    };
    let modalPage = this.modalCtrl.create(ListSeletionPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        if (!res) return;
        this.lauConfigs.userLaundries[0].user = res;
        this.sendLaundryConfigs();
      }
    );
    modalPage.present();
  }

  getAvailableVMs() {
    let modalArgs = {
      title: 'SELECT_VENDING_MACHINE_TITLE',
      list: [],
      titleKey: '',
      subTitleKey: '',
      type: 'AVAILABLE_VMS',
      getTitle: function(obj) {
        let name = this.translate.getTranslation('NAME');
        return `${name}: ${obj.type}`;
      },
      getSubtitle: function(obj) {
        let serialNumber = this.translate.getTranslation('SERIAL_NUMBER');
        return `${serialNumber}: ${obj.serialNumber}`;
      },
    };
    let modalPage = this.modalCtrl.create(ListSeletionPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        if (!res) return;
        this.lauConfigs.vendingMachines[0] = res;
        this.sendLaundryConfigs();
      }
    );
    modalPage.present();
  }

  deleteVM() {
    if (this.lauConfigs.vendingMachines[0].type !== '') {
      this.cs.setCommand({ src: 'laundry', dest: 'laundry-configuration', cmd: 'delete-vm'});
    }
  }

  centerChanged(ev) {
    this.selectedLat = ev.lat;
    this.selectedLng = ev.lng;
  }

  dragRealese(ev) {
    if (!this.edit) return;

    if (ev.target.localName !== 'img') {
      this.fineAdjust = true;
      this.lat = this.selectedLat;
      this.lng = this.selectedLng;

      // Get address form Google geocode service.
      this.backendApi.getAddress(this.lat, this.lng).subscribe(
        res => {
          if (res.results.length !== 0) {
            this.parseAddress(res.results[0], false);
          }
        },
        err => {}
      );
    }
  }

  getCoordinates(ev) {
    if (!ev.hasOwnProperty('target') || !ev.target.value) return; 

    this.backendApi.getCoordinates(ev.target.value).subscribe(
      res => {
        if (res.results.length !== 0) {
          this.lat = res.results[0].geometry.location.lat;
          this.lng = res.results[0].geometry.location.lng;
        }
      },
      err => {}
    );
  }

  parseAddress(addr, useResCoord) {
    let street_number = this.getAddressValue(addr, 'street_number');
    // Parse google geocode response.
    this.lauConfigs.address.addressLine1 = this.getAddressValue(addr, 'route');
    if (street_number) this.lauConfigs.address.addressLine1 += `, ${street_number}`;
    this.lauConfigs.address.stateProvince = this.getAddressValue(addr, 'administrative_area_level_1');
    this.lauConfigs.address.city = this.getAddressValue(addr, 'locality');
    this.lauConfigs.address.postalCode = this.getAddressValue(addr, 'postal_code');
    this.lauConfigs.address.country = this.getAddressValue(addr, 'country');

    // Save GPS coordinates.
    if (useResCoord) {
      this.lat = addr.geometry.location.lat;
      this.lng = addr.geometry.location.lng;
      this.lauConfigs.address.lat = addr.geometry.location.lat;
      this.lauConfigs.address.lng = addr.geometry.location.lng;

    } else {
      this.lat = this.selectedLat;
      this.lng = this.selectedLng;
      this.lauConfigs.address.lat = this.selectedLat;
      this.lauConfigs.address.lng = this.selectedLng;
    }
    this.zoom = 17;
  }

  getAddressValue(addr, type) {
    let el = addr.address_components.find(el => (el.types[0] === type));
    if (el) return el.long_name;
    return '';
  }

  clearAddr() {
    this.lauConfigs.address.addressLine1 = '';
    this.lauConfigs.address.stateProvince = '';
    this.lauConfigs.address.city = '';
    this.lauConfigs.address.postalCode = '';
    this.lauConfigs.address.country = '';

    this.lat = 39.399871;
    this.lng = -8.224454;
  }
}



