import { Injectable } from '@angular/core';

@Injectable()
export class AppConfig {

  appConfig: any;

  constructor() {
    this.appConfig = {
      username: '',
      laundryId: '',
      vendingMachineId: '',
      gmApiKey: 'AIzaSyDnx4wf-sYzK9GIVakK0X70nli_OzD4RzE',
      lang: 'pt',
      acst: 'qhsymjf57634TT!'
    }
  }

  getGMKey(): string {
    return this.appConfig.gmApiKey;
  }

  getLaundryId(): string {
    return this.appConfig.laundryId;
  }

  setLaundryId(laundryId) {
    this.appConfig.laundryId = laundryId;
  }

  getUsername(): string {
    return this.appConfig.username;
  }

  setUsername(username) {
    this.appConfig.username = username;
  }

  getVendingMachineId(): string {
    return this.appConfig.vendingMachineId;
  }

  setVendingMachineId(vendingMachineId) {
    this.appConfig.vendingMachineId = vendingMachineId;
  }

  getDefaultLang() {
    return this.appConfig.lang;
  }

  setDefaultLang(lang: string) {
    this.appConfig.lang = lang;
  }

}



