import { Component } from '@angular/core';
import { ViewController, NavParams } from 'ionic-angular';
import { Observable } from 'rxjs/Observable';
import * as moment from 'moment';
import 'rxjs/add/observable/forkJoin';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { UserSession } from '../../providers/user-session';

declare var swal: any;


@Component({
  selector: 'page-task-editor',
  templateUrl: 'task-editor.html'
})
export class TaskEditorPage {

  task: any = {
    type: 'CORRECTIVE',  // default value.
    priority: 'MEDIUM',
    obs: null,
    repairDate: null,
    laundry_laundryId: null,
    machine_machineId: null,  // maq. lavar/secar
    vending_machine_vendingMachineId: null,   // vending machine
    vending_machine_peripheral_peripheralId: null,  // vending machine peripheral
    laundry_peripheral_laundryPeripheralId: null,  // interfaces
    user_userId: null,
  };

  device: string = 'MACHINE';
  prevDevice: string = 'MACHINE';

  lDelayTimer = null;
  oDelayTimer = null;

  laundrySearch: string = '';
  operatorSearch: string = '';
  deviceSearch: string = '';

  laundryListHidden: boolean = true;
  fetchingLau: boolean = false;
  operatorListHidden: boolean = true;
  fetchingOpe: boolean = false;  
  deviceListHidden: boolean = true;

  filteredLaundryList: any = [];
  filteredOperatorList: any = [];
  filteredDeviceList: any = [];

  machineList: any = null;
  interfaceList: any = null;
  vm: any = null;
  vmList = null;
  vmPeripheralList: any = null;

  segmentDisabled: boolean = true;
  editMode: boolean = false;
  prefiledMode: boolean = false;

  searchPlcHld: string = 'SEARCH';
  reporter: string = null;
  del: boolean = true;
  hasVM: boolean = false;

  constructor(private viewCtrl: ViewController,
              private navParams: NavParams,
              private backendApi: BackendApiProvider,
              private translate: TranslateService,
              private userSession: UserSession) {
    this.del = this.userSession.getPermission('maintenance-delete');

    this.searchPlcHld = this.translate.getTranslation(this.searchPlcHld);

    if (this.navParams.data.hasOwnProperty('task')) {
      // Edit mode
      this.task.type = this.navParams.data.task.type;
      this.task.status = this.navParams.data.task.status;
      this.task.priority = this.navParams.data.task.priority;
      this.task.obs = this.navParams.data.task.obs;
      this.task.repairDate = this.navParams.data.task.repairDate;
      this.task.laundry_laundryId = this.navParams.data.task.laundry_laundryId;
      this.task.machine_machineId = this.navParams.data.task.machine_machineId;
      this.task.vending_machine_vendingMachineId = this.navParams.data.task.vending_machine_vendingMachineId;
      this.task.vending_machine_peripheral_peripheralId = this.navParams.data.task.vending_machine_peripheral_peripheralId;
      this.task.laundry_peripheral_laundryPeripheralId = this.navParams.data.task.laundry_peripheral_laundryPeripheralId;
      this.task.user_userId = this.navParams.data.task.user_userId;
      this.task.maintenanceId = this.navParams.data.task.maintenanceId;

      this.task.laundry = this.navParams.data.task.laundry;
      this.task.reporter = this.navParams.data.task.reporter;

      this.editMode = true;
    }

    if (this.navParams.data.hasOwnProperty('device')) {
      this.task.laundry_laundryId = this.navParams.data.laundryId;
      switch (this.navParams.data.device) {
        case 'INTERFACE':
          this.task.laundry_peripheral_laundryPeripheralId = this.navParams.data.deviceId;
          break;
        case 'VM':
          this.task.vending_machine_vendingMachineId = this.navParams.data.deviceId;
          break;
        case 'MACHINE':
          this.task.machine_machineId = this.navParams.data.deviceId;
          break;
        case 'PERIPHERAL':
          this.task.vending_machine_peripheral_peripheralId = this.navParams.data.deviceId;
          break;
      }
      this.prefiledMode = true;
    }

    if (this.task.laundry_laundryId) {
      if (this.editMode) {
        this.laundrySearch = this.task.laundry.name;
        this.reporter = this.task.reporter.name;
        if (this.task.user_userId) {
          this.backendApi.getUserDetails(this.task.user_userId).subscribe(
            res => { this.operatorSearch = res.name; },
            err => {},
          );
        }
        this.getLaundryInfo(this.task.laundry_laundryId);
      }
      if (this.prefiledMode) {
        this.getLaundryInfo(this.task.laundry_laundryId);
      }
    }
  }

  inputOnChange($event, field) {
    switch (field) {
      case 'LAUNDRY':
        clearTimeout(this.lDelayTimer);
        this.lDelayTimer = setTimeout(() => {
          if (this.laundrySearch === '' || this.laundrySearch === null) {
            this.laundryListHidden = true;
            this.filteredLaundryList = [];
            this.interfaceList = null;
            this.machineList = null;
            this.vm = null;
            this.vmPeripheralList = null;
          } else {
            if (this.laundrySearch.length <= 2) return;

            this.fetchingLau = true;
            this.laundryListHidden = false;
            this.backendApi.getLaundriesSearch(1, this.laundrySearch).subscribe(
              res => {
                if (res.hasOwnProperty('rows') && Array.isArray(res.rows)) { this.filteredLaundryList = res.rows; }
                this.fetchingLau = false;
              },
              err => { setTimeout(() => { this.fetchingLau = false; }, 200); }
            );
          }
        }, 700);
        break;
      case 'OPERATOR':
        clearTimeout(this.oDelayTimer);
        this.oDelayTimer = setTimeout(() => {
          if (this.operatorSearch === '' || this.operatorSearch === null) {
            this.operatorListHidden = true;
            this.filteredOperatorList = [];
            this.task.user_userId = null;
          } else {
            if (this.operatorSearch.length <= 2) return;

            this.fetchingOpe = true;
            this.operatorListHidden = false;  
            this.backendApi.getOperatorsSearch(1, this.operatorSearch).subscribe(
              res => {
                this.fetchingOpe = false;
                if (res.hasOwnProperty('rows') && Array.isArray(res.rows)) { this.filteredOperatorList = res.rows; }
              },
              err => { setTimeout(() => { this.fetchingOpe = false; }, 200); }
            );
          }
        }, 700);
        break;
      case 'DEVICE':
        if (this.deviceSearch === '') {
          this.deviceListHidden = true;
        } else {
          switch (this.device) {
            case 'MACHINE':
              this.filteredDeviceList = this.filterList(this.machineList, this.deviceSearch);
              this.deviceListHidden = false;
              break;
            case 'VM': break;
            case 'INTERFACE':
              this.filteredDeviceList = this.filterList(this.interfaceList, this.deviceSearch);
              this.deviceListHidden = false;
              break;
            case 'PERIPHERAL':
              this.filteredDeviceList = this.filterList(this.vmPeripheralList, this.deviceSearch);
              this.deviceListHidden = false;
              break;
          }
        }
        break;
    }
  }

  segmentChanged($event) {
    if (this.prevDevice === $event.value) return;

    this.deviceSearch = '';
    this.deviceListHidden = true;
    this.prevDevice = $event.value;
    switch ($event.value) {
      case 'MACHINE':
        break;
      case 'VM':
        this.deviceSearch = this.vm.type;
        this.task.vending_machine_vendingMachineId = this.vm.vendingMachineId;
        break;
      case 'INTERFACE':
        break;
      case 'PERIPHERAL':
        break;
    }
  }

  selectItem(item, field) {
    switch (field) {
      case 'LAUNDRY':
        this.laundrySearch = item.name;
        this.task.laundry_laundryId = item.laundryId;
        this.getLaundryInfo(this.task.laundry_laundryId);
        this.laundryListHidden = true;
        break;
      case 'OPERATOR':
        this.operatorSearch = item.name;
        this.task.user_userId = item.userId;
        this.operatorListHidden = true;
        break;
      case 'DEVICE':
        switch (this.device) {
          case 'MACHINE':
            this.deviceSearch = item.name;
            this.task.machine_machineId = item.machineId;
            break;
          case 'VM':
            break;
          case 'INTERFACE':
            this.deviceSearch = item.name;
            this.task.laundry_peripheral_laundryPeripheralId = item.laundryPeripheralId;
            break;
          case 'PERIPHERAL':
            this.deviceSearch = item.name;
            this.task.vending_machine_peripheral_peripheralId = item.peripheralId;
            break;
        }
        this.deviceListHidden = true;
        break;
    }
  }

  getLaundryInfo(laundryId) {
    if (!laundryId) {
      this.segmentDisabled = false;
      this.vm = this.vmList.find(el => (el.vendingMachineId === this.task.vending_machine_vendingMachineId));
      this.device = 'VM';
      this.deviceSearch = this.vm.type;
    } else {
      let machinesWasObs = this.backendApi.getMachinesConfigs(laundryId, 'wash');
      let machinesDryObs = this.backendApi.getMachinesConfigs(laundryId, 'dry');
      let interfacesObs = this.backendApi.getInterfacesConfigs(laundryId);
      let vmObs = this.backendApi.getLaundryInfo({ laundryId: laundryId });

      this.segmentDisabled = true;

      Observable.forkJoin([interfacesObs, machinesWasObs, machinesDryObs, vmObs]).subscribe(
        res => {
          this.interfaceList = res[0];
          this.machineList = res[1].concat(res[2]);
          this.vm = (res[3].vendingMachines.length > 0) ? res[3].vendingMachines[0] : null;
          this.hasVM = (this.vm !== null);
          this.segmentDisabled = false;
        },
        err => {},
        () => {
          if (this.vm === null || !this.vm.hasOwnProperty('vendingMachineId')) return;

          this.backendApi.getVendingMachine(this.vm.vendingMachineId).subscribe(
            res => {
              this.vmPeripheralList = res[0].vendingMachinePeripherals;
            },
            err => {},
            () => {
              // Format returned data from server.
              this.interfaceList.forEach(item => item.name = item.config.name);
              this.vmPeripheralList.forEach(item => item.name = this.translate.getTranslation(item.type));

              if (this.editMode || this.prefiledMode) {
                let keys = [
                  { id: 'vending_machine_vendingMachineId', value: 'VM' },
                  { id: 'vending_machine_peripheral_peripheralId', value: 'PERIPHERAL'},
                  { id: 'laundry_peripheral_laundryPeripheralId', value: 'INTERFACE' },
                  { id: 'machine_machineId', value: 'MACHINE' }
                ];
                let i = 0;
                keys.forEach((key, index) => {
                  if (this.task[key.id]) {
                    this.device = key.value;
                    this.prevDevice = key.value;
                    i = index;
                  }
                });
                switch (keys[i].value) {
                  case 'VM':
                    this.deviceSearch = this.vm.type;
                    break;
                  case 'PERIPHERAL':
                    this.deviceSearch = this.vmPeripheralList.find(item => (item.peripheralId === this.task.vending_machine_peripheral_peripheralId)).name;
                    break;
                  case 'MACHINE':
                    this.deviceSearch = this.machineList.find(item => (item.machineId === this.task.machine_machineId)).name;
                    break;
                  case 'INTERFACE':
                    this.deviceSearch = this.interfaceList.find(item => (item.laundryPeripheralId === this.task.laundry_peripheral_laundryPeripheralId)).name;
                    break;
                }
              }
            }
          );
        }
      );
    }
  }

  filterList(origList, searchTerm) {
    return origList.filter(item => {
      return Object.keys(item).some(k => (item[k] && typeof item[k] === 'string' && item[k].toLowerCase().includes(searchTerm.toLowerCase())));
    });
  }

  openSearchBox() {
    if (this.laundrySearch !== '' && this.device !== 'VM') {
      switch (this.device) {
        case 'MACHINE':
          this.filteredDeviceList = this.machineList;
          break;
        case 'VM':
          break;
        case 'INTERFACE':
          this.filteredDeviceList = this.interfaceList;
          break;
        case 'PERIPHERAL':
          this.filteredDeviceList = this.vmPeripheralList;
          break;
      }
      this.deviceListHidden = !this.deviceListHidden;
    }
  }

  cancel() {
    this.viewCtrl.dismiss();
  }

  delete() {
    if (this.del) {
      this.backendApi.deleteTask(this.task.maintenanceId).subscribe(
        res => {
          this.viewCtrl.dismiss({ cmd: 'DELETE', maintenanceId: this.task.maintenanceId });
        },
        err => {}
      );
    }
  }

  submit() {
    let keys = [
      { id: 'vending_machine_vendingMachineId', value: 'VM' },
      { id: 'vending_machine_peripheral_peripheralId', value: 'PERIPHERAL'},
      { id: 'laundry_peripheral_laundryPeripheralId', value: 'INTERFACE' },
      { id: 'machine_machineId', value: 'MACHINE' }
    ];
    keys.forEach(key => {
      if (this.device !== key.value) {
        this.task[key.id] = null;
      }
    });

    if (this.task.laundry_laundryId && (this.task.machine_machineId || this.task.vending_machine_vendingMachineId || this.task.vending_machine_peripheral_peripheralId || this.task.laundry_peripheral_laundryPeripheralId)) {
      if (this.editMode) {
        this.backendApi.updateTask(this.task).subscribe(
          res => {
              this.viewCtrl.dismiss({ cmd: 'REFRESH', task: res });
          },
          err => {}
        );
      } else {
        this.backendApi.createTask(this.task).subscribe(
          res => {
            this.viewCtrl.dismiss({ cmd: 'REFRESH', task: res });
          },
          err => {}
        );
      }
    } else {
      swal({
        title: this.translate.getTranslation('INCOMPLETE_FORM_TITLE'),
        text: this.translate.getTranslation('INCOMPLETE_FORM_MSG'),
        type: 'warning',
        confirmButtonColor: 'rgb(13, 51, 72)',
        confirmButtonText: 'OK',
      }).then(() => {}).catch(swal.noop);
    }
  }

  deviceSearchVK(event) {
    this.openSearchBox()
  }
}



