import { Injectable } from '@angular/core';
import { Observable } from 'rxjs/Rx';
import { Subject } from 'rxjs/Rx';

@Injectable()
export class VendingMachineApiProvider {

  connectionId: string;
  incomingDataObs: Subject<any>;


  constructor() {
    this.connectionId = '';
    this.incomingDataObs = new Subject<any>();

    // Add event listener for incoming data.
    (<any>document).addEventListener(
      (<any>window).tlantic.plugins.socket.receiveHookName,
      ev => this.incomingDataObs.next(JSON.parse(ev.metadata.data))
    );
  }

  connect(host: string, port: string) {
    (<any>window).tlantic.plugins.socket.connect(
      res => this.connectionId = res,
      err => {},
      host,
      port
    );
  }

  disconnect() {
    (<any>window).tlantic.plugins.socket.disconnect(
      () => {},
      () => {},
      this.connectionId
    );
  }

  disconnectAll() {
    (<any>window).tlantic.plugins.socket.disconnectAll(
      () => {},
      () => {}
    );
  }

  send(data) {
    let dataLength = JSON.stringify(data).length;
    let pkgLength = dataLength + dataLength.toString().length + 14;
    let pkg = {
      cl: `${pkgLength}`,
      c: data,
    };
    (<any>window).tlantic.plugins.socket.send(
      () => {},
      () => {},
      this.connectionId,
      pkg
    );
  }

  getIncomingData(): Observable<any> {
    return this.incomingDataObs.asObservable();
  }

}



