import { Component, OnInit, OnDestroy, HostListener, ChangeDetectionStrategy, Input } from '@angular/core';
import { NavController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';
import { Observable } from 'rxjs/Observable';
import 'rxjs/add/observable/of';
import 'rxjs/add/operator/do';
import 'rxjs/add/operator/map';
import * as $ from 'jquery';

// Page components.
import { VendingMachineConfigurationPage } from '../vending-machine-configuration/vending-machine-configuration';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';


@Component({
  selector: 'page-vending-machines',
  templateUrl: 'vending-machines.html',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class VendingMachinesPage {

  @Input('data') meals: string[] = [];
  asyncResults: Observable<any>;
  p: number = 1;
  total: number;
  itemsPerPage: number;

  searchTerm: string = null;
  search: string = null;

  loading: boolean = true;
  noResult: boolean = true;
  gettingPage = false;

  btnEnabled: boolean = true;

  newVMEnabled: boolean = false;

  vms: Array<any> = [];
  filteredVMs: Array<any> = [];
  displayMode: string = 'thumbnail';
  portraitMode: boolean = false;
  csSubs: Subscription;

  vmImg: string = "assets/img/vm-icon-big.png";  
  storage: any = new Storage();      

  tabletMode: boolean = false;


  constructor(private navCtrl: NavController,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession) {
    if (window.innerWidth < window.innerHeight) {
      this.displayMode = 'list';
      this.portraitMode = true;
    }

    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    }

    // Enable/disable insert new laundry option.
    this.newVMEnabled = this.userSession.getPermission('vending-machine-insert');

    this.csSubs = cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'vending-machines') return;
        switch (res.cmd) {
          case 'refresh':
            this.searchTerm = null;
            this.getPage(1);
            break;
        }
      }
    );
  }

  ngOnInit() {
      this.getPage(1);
  }

  getPage(page: number) {
    $('page-vending-machines .scroll-content').animate({ scrollTop: 0 }, "slow");

    this.gettingPage = true;
    this.asyncResults = this.backendApi.getVendingMachinesPage(page, this.searchTerm)
      .do(res => {
        res.rows.forEach(el => {
          el['ownerName'] = '---';
          if (el.laundry.hasOwnProperty('userLaundries') && Array.isArray(el.laundry.userLaundries) && el.laundry.userLaundries.length > 0 && el.laundry.userLaundries[0].user.name && el.laundry.userLaundries[0].user.name !== '') {
            el['ownerName'] = el.laundry.userLaundries[0].user.name;            
          }
          el['laName'] = '---';
          if (el.laundry.hasOwnProperty('name') && el.laundry.name && el.laundry.name !== '') {
            el['laName'] = el.laundry.name;
          }
        });

        res.rows = res.rows.sort((a, b) => {
          if (a.type.toLowerCase() > b.type.toLowerCase()) {
            return 1;
          } else {
            return -1;
          } 
        });

        if (!this.itemsPerPage) this.itemsPerPage = res.rows.length;
        this.total = res.totalPages * this.itemsPerPage;
        this.p = page;

        if (res.rows.length === 0) {
          this.noResult = true;
        } else {
          this.noResult = false;
        }
        this.loading = false;
        this.gettingPage = false;
      }, err => {
        this.gettingPage = false;
        this.cf.presentMsgNotification('error', 'RESOURCE_NOT_FOUND');
      })
      .map(res => res.rows);
  }

  ngOnDestroy() {
    if (this.csSubs) this.csSubs.unsubscribe();
  }

  addVM() {
    this.navCtrl.push(VendingMachineConfigurationPage, { vmConfigs: null });
  }

  configVM(vm) {
    if (!this.btnEnabled) return;

    this.btnEnabled = false;
    this.backendApi.getVendingMachine(vm.vendingMachineId).subscribe(
      res => {
        this.navCtrl.push(
          VendingMachineConfigurationPage,
          { vmConfigs: res[0] }
        );
        this.btnEnabled = true;        
      },
      err => this.btnEnabled = true 
    );
  }

  filterResults(e) {
    if (this.search.length === 0) {
      this.searchTerm = null;
      this.getPage(1);
    }
    if (this.search.length > 2) {
      this.searchTerm = (this.search === '') ? null : this.search;
      this.getPage(1);
    }
  }

  showAllResults(clearEv) {
    if (clearEv.type === 'click') {
      this.searchTerm = null;
      this.getPage(1);
    }
  }

  @HostListener('window:resize', ['$event'])
  onResize(event) {
    if (event.target.innerWidth < event.target.innerHeight) {
      this.displayMode = 'list';
    }

    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    } else {
      this.tabletMode = false;      
    }
  }

}



