import { Component, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { NavController, ViewController, ModalController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { NifConfirmationPage } from '../nif-confirmation/nif-confirmation';
import { AlertPage } from '../alert/alert';

// Service/provider components.
import { TranslateService } from '../../translate';
import { Orders } from '../../providers/orders';
import { Client } from '../../providers/client';
import { Inactivity } from '../../providers/inactivity';
import { Machines } from '../../providers/machines';
import { HelpTour } from '../../providers/help-tour'
import { AppSettings } from '../../providers/app-settings';


@Component({
  selector: 'page-bill-confirmation',
  templateUrl: 'bill-confirmation.html'
})
export class BillConfirmationPage implements OnDestroy {

  smCardImg: string = 'assets/img/sm-card.png';
  smCoinsImg: string = 'assets/img/sm-coins.png';

  processStateImg: string = 'assets/img/ambiente_1.png';
  deleteOrderImg: string = 'assets/img/remover.png';
  cardImg: string = 'assets/img/cartao-icon.png';
  coinImg: string = 'assets/img/moedas-icon.png';

  wasMachineImg: string =  'assets/img/washing-machine.jpg';
  dryMachineImg: string =  'assets/img/drying-machine.jpg';

  totalCost: number = 0.00;
  totalCostCard: number = 0.00;

  missingBalance: number = 0.00;
  balance: number = 0.00;
  balanceCard: number = 0.00;
  clientCard: boolean = false;
  clientSubs: Subscription = null;

  change: number = 0.00;
  changeValue: number = 0.00;

  actMsg: Array<any> = [];


  constructor(private navCtrl: NavController,
              private viewCtrl: ViewController,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private changeDetector: ChangeDetectorRef,
              private orders: Orders,
              private client: Client,
              private help: HelpTour,
              private appSet: AppSettings,              
              private machines: Machines) {
    this.setTotal();
    this.balance = this.client.getBalance();
    this.balanceCard = this.client.getBalanceCard();

    if ((this.client.getCardNumber() !== null)) {
      this.clientCard = true;
    }

    this.setMissingBalance();

    // Handle client updates.
    this.clientSubs = this.client.getClient().subscribe(
      client => {
        // if (client.hasOwnProperty('hasCard') && client.hasCard) this.clientCard = true;
        
        this.balance = this.client.getBalance();
        this.balanceCard = this.client.getBalanceCard();

        if ((this.client.getCardNumber() !== null) !== this.clientCard) {
          this.toggleClientCard();
        }
        this.setMissingBalance();
        this.changeDetector.detectChanges();


      }
    );
  }

  ngOnDestroy() {
    this.help.cancelTour();
    if (this.clientSubs) this.clientSubs.unsubscribe();
  }

  toggleClientCard() {
    this.clientCard = !this.clientCard;
  }

  setTotal() {
    // Compute total cost of orders in money.
    this.totalCost = this.orders.get()
      .map(el => el.program.selPrice)
      .reduce((prevVal, el) => prevVal + Number(el), 0.00);
    // Compute total cost of orders in money.
    this.totalCostCard = this.orders.get()
      .map(el => el.program.selPriceCard)
      .reduce((prevVal, el) => prevVal + Number(el), 0.00);
  }

  setMissingBalance() {
    let missingBalance = 0.00;
    if (this.clientCard) {
      this.changeValue = 0;
      missingBalance = this.totalCostCard - this.balanceCard;
    } else {
      missingBalance = this.totalCost - this.balance;
      if (missingBalance <= 0) { this.changeValue = this.balance - this.totalCost; }
    }
    missingBalance = Math.round(missingBalance * 100) / 100;          
    (missingBalance <= 0) ? this.missingBalance = 0.00 : this.missingBalance = missingBalance;
  }

  close() {
    this.help.cancelTour();
    if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
  }

  cancelOrder(order) {
    let pkg = {
      op: 'machine-res-canceled',
      data: {
        id: order.machine.config.intId,
        chn: order.machine.peripheral_has_machines[0].channel,
      }
    };
    this.machines.updateMachineState(pkg);

    this.orders.remove(order);
    if (this.orders.get().length === 0) {
      this.close();
    } else {
      this.setTotal();
      this.setMissingBalance();
    }
  }

  cancelOrders() {
    let pkg = {
      op: 'cancel-orders'
    };
    this.machines.updateMachineState(pkg);

    this.orders.reset();
    this.close();
  }

  completeOrder() {
    if (this.missingBalance > 0) {
      // this.help.hide();
      let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'INSUFFICIENT_BALANCE_TITLE', msg: 'INSUFFICIENT_BALANCE_MSG' });
      modalPage.present();
    } else {
      this.getChange();
      this.setActivationObj();
      this.help.next();
      this.navCtrl.push(NifConfirmationPage, { change: this.change, actMsg: this.actMsg, totalCost: this.totalCost });
    }
  }

  getChange() {
    if (this.clientCard) {
      this.change = this.balance;
    } else {
      this.change = this.balance - this.totalCost;
    }
  }

  setActivationObj() {
    this.orders.get().forEach((item, i) => {
      let act = {
        id: item.machine.config.intId,
        chn: item.machine.peripheral_has_machines[0].channel,
        impulses: (item.program.impulses) ? item.program.impulses.toString() : '1',
      };
      this.actMsg.push(act);
    });
  }

  goBack() {
    this.navCtrl.pop();
  }
}



