import { Component, OnInit, OnDestroy } from '@angular/core';
import { NavController, NavParams, ModalController } from 'ionic-angular';
import { Md5 } from 'ts-md5/dist/md5';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';

import { AlertPage } from '../alert/alert';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';

// Sweetalert2 variable declaration.
declare var swal: any;

// TODO: Input Validators, confirm password and email on create or update user.


@Component({
  selector: 'page-user',
  templateUrl: 'user.html'
})
export class UserPage implements OnInit, OnDestroy {

  cardReqBtn: boolean = false;
  newUser = true;  

  // Permissions.
  updUserEnabled: boolean = false;
  delUserEnabled: boolean = false;

  user: any;
  userHash: any = null;
  roles: Array<any> = null;
  activeSection: string = 'profile';
  selectedRole: string = '';
  emailConf: string = null;
  passConf: string = '';
  action: string = 'create';
  canLeave: boolean = false;
  pageTitle: string = 'USER_TITLE';
  selectEnabled: boolean = true;
  readOnly: boolean = false;
  clientMode: boolean = false;  

  middlewareSubs: Subscription = null;
  clientCardAvailable: boolean = true;

  storage: any = new Storage();  

  isVM: boolean = false;

  userCodeEnabled: boolean = false;

  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private middleware: Middleware,
              private middlewareCloud: MiddlewareCloud,
              private userSession: UserSession) {
    this.storage.get('isVM').then(isVM => {
      this.isVM = isVM;
    });

    // Send request to check for card availabilityin the dispenser.
    this.checkCardsAvailability();
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        switch (pkg.op) {
          case 'has-card':
            if (pkg.code === "200") {
              this.clientCardAvailable = true; 
            } else {
              this.clientCardAvailable = false;              
            }
            break;
        }
    });

    // Enable/disable insert new laundry option.
    this.updUserEnabled = this.userSession.getPermission('user-update');
    this.delUserEnabled = this.userSession.getPermission('user-delete');
  }

  ngOnInit() {
    let title = this.navParams.get('title');
    // Get user.
    this.user = this.navParams.get('user');
    this.roles = this.navParams.get('roles');

    if (this.navParams.get('userRole') === 'client') {
      this.clientMode = true;
      this.pageTitle = 'CLIENT_TITLE';
    }
    if (this.user) {
      this.enableCardBtn();
      this.newUser = false;
      this.emailConf = this.user.address.email;
      if (this.user.cards.length === 0) {
        this.user.cards.push({ cardNumber: null });
      }
      this.action = 'update';
      this.user.password = null;
    } else {
      this.newUser = true;
      this.edit();
      this.user = this.getEmptyUser();
    }
    if (this.roles.length === 1 && this.roles[0].role === 'client') {
      this.user.role_roleId = this.roles[0].roleId;
      this.selectEnabled = false;
    }
    // Store initial user state.
    this.userHash = Md5.hashAsciiStr(JSON.stringify(this.user));
  }

  ngOnDestroy() {
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe(); 
    this.cs.setCommand({ src: 'user', dest: 'start', cmd: 'CARD_HANLING_ON'});    
  }

  getEmptyUser() {
    return {
      name: '',
      username: '',
      password: '',
      userCode: null,
      nif: '',
      sex: '',
      birthDate: '',
      role_roleId: '',
      card: {
        cardNumber: 'x' + Date.now().toString(),
      },
      cards: [{
        cardNumber: '',
      }],
      address: {
        addressLine1: '',
        addressLine2: '',
        city: '',
        country: '',
        email: null,
        faxNumber: '',
        mobileNumber: '',
        phoneNumber: '',
        postalCode: '',
        stateProvince: '',
      }
    }
  }

  save() {
    // if (!this.confirm('PASSWORD') && this.newUser) {
    if (!this.confirm('PASSWORD')) {
      swal({
        title: 'Confirmar Password!',
        text: 'Os campos destinados à password selecionada tem de ser iguais.',
        type: 'warning',
        confirmButtonColor: 'rgb(13, 51, 72)',
        confirmButtonText: 'OK',
      }).then(() => {}).catch(swal.noop);
      return;
    }
    if (!this.confirm('EMAIL')) {
      swal({
        title: 'Confirmar Email!',
        text: 'Os campos destinados ao email selecionado tem de ser iguais.',
        type: 'warning',
        confirmButtonColor: 'rgb(13, 51, 72)',
        confirmButtonText: 'OK',
      }).then(() => {}).catch(swal.noop);
      return;
    }
    this.backendApi.setUser(this.user, this.action).subscribe(
      res => { this.newUser = false; },
      // TODO: handle fetching errors.
      err => {
        this.cf.presentNotification('failure');
      },
      () => {
        if (this.action === 'create') {
          this.user.cards[0].cardNumber = this.user.card.cardNumber;
          this.action = 'update';
        }
        this.cs.setCommand({ src: 'user', dest: 'user-list', cmd: 'refresh'});
        this.cf.presentNotification('success');
        this.enableCardBtn();
        // Store new user state.
        this.userHash = Md5.hashAsciiStr(JSON.stringify(this.user));
      }
    );
  }

  edit() {
    this.readOnly = !this.readOnly;
  }

  delete() {
    swal({
      title: this.translate.getTranslation('ALERT_DELETE_TITLE'),
      text: this.translate.getTranslation('ALERT_DELETE_MSG'),
      type: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#ff1a1a',
      cancelButtonColor: 'rgb(13, 51, 72)',
      confirmButtonText: this.translate.getTranslation('YES'),
      cancelButtonText: this.translate.getTranslation('NO'),
    }).then(() => {
      this.backendApi.setUser(this.user, 'delete').subscribe(
        res => {},
        // TODO: handle fetching errors.
        err => {
          this.cf.presentNotification('failure');
        },
        () => {
          this.cs.setCommand({ src: 'user', dest: 'user-list', cmd: 'refresh'});
          this.canLeave = true;
          if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
          swal({
            title: this.translate.getTranslation('DELETED'),
            text: this.translate.getTranslation('DELETED_CONFIGURATION_SUCCESS'),
            type: 'success',
            showConfirmButton: false,
            timer: 2000,
          }).catch(swal.noop);
        }
      );
    }).catch(swal.noop);
  }

  hasUnsavedChanges() {
    if (this.userHash !== Md5.hashAsciiStr(JSON.stringify(this.user))) return true;
    return false;
  }

  ionViewCanLeave() {
    if (!this.canLeave && this.hasUnsavedChanges()) {
      return new Promise((resolve, reject) => {
        swal({
          title: this.translate.getTranslation('ALERT_UNSAVED_TITLE'),
          text: this.translate.getTranslation('ALERT_UNSAVED_MSG'),
          type: 'warning',
          showCancelButton: true,
          confirmButtonColor: '#ff1a1a',
          cancelButtonColor: 'rgb(13, 51, 72)',
          confirmButtonText: this.translate.getTranslation('YES'),
          cancelButtonText: this.translate.getTranslation('NO'),
        }).then(() => {
          this.user.password = null;
          this.backendApi.setUser(this.user, this.action).subscribe(
            res => {},
            // TODO: handle fetching errors.
            err => {
              this.cf.presentNotification('failure');
              reject();
            },
            () => {
              this.cs.setCommand({ src: 'user', dest: 'user-list', cmd: 'refresh'});
              swal({
                title: this.translate.getTranslation('SAVED'),
                text: this.translate.getTranslation('SAVE_CONFIGURATION_SUCCESS'),
                type: 'success',
                showConfirmButton: false,
                timer: 2000,
              }).catch(() => {
                swal.noop;
                resolve();
              });
            }
          );
        }).catch(() => resolve());
      });
    }
    return new Promise((resolve, reject) => resolve());
  }





releaseCardRequest() {
  if (!this.clientCardAvailable) {
    // Present alert (Not client card in dispenser).
    let modalPage = this.modalCtrl.create(AlertPage, { type: 'alert', title: 'NO_CARDS_TITLE', msg: 'NO_CARDS_MSG_ADMIN' });
    modalPage.onDidDismiss(res => { 
      this.checkCardsAvailability();
      return;
    });
    modalPage.present();
  } else {
    this.cs.setCommand({ src: 'user', dest: 'start', cmd: 'CARD_HANLING_OFF'});
    let pkg = {
      op: 'card-release',
    }
    this.middleware.send(pkg);

    let ownerId = null;
    let role = this.roles.find(item => (item.roleId === this.user.role_roleId));
    if (role && role.hasOwnProperty('role') && role.role === 'owner') {
      ownerId = this.user.userId;
    } else {
      ownerId = 'ALL';
    }

    let cardData = {
      name: this.user.name,
      nif: this.user.nif,
      balance: null,
      cardId: null,
      ownerId: ownerId,
    }
    let insertCardPage = this.modalCtrl.create(AlertPage, { type: 'card-access', title: 'INSERT_CARD_TITLE', msg: 'INSERT_CARD_MSG', cardData: cardData });
    insertCardPage.onDidDismiss(
      confirm => {
        if (!confirm) {
          this.cs.setCommand({ src: 'user', dest: 'start', cmd: 'CARD_HANLING_ON'});
          return;
        };
        if (confirm.confirm) {
          this.user.cards[this.user.cards.length - 1].cardNumber = confirm.cardId;
          this.backendApi.newAccessCard(this.user.userId, confirm.cardId).subscribe(
            res => {
              this.save();
            },
            err => {}
          );
        }
        this.checkCardsAvailability();
      }
    );
    insertCardPage.present();
  }
}

  checkCardsAvailability() {
    // Send change request to low level.
    let pkg =   {
      op: 'has-card',
    };
    this.middleware.send(pkg);
  }

  enableCardBtn() {
    this.cardReqBtn = true;
  }

  confirm(type) {
    if (type === 'PASSWORD') {
      if (this.passConf === '') this.passConf = null;
      return (this.user.password == this.passConf);
    }
    if (type === 'EMAIL') {
      if (this.user.address.email === this.emailConf || (this.user.address.email === null && this.emailConf === '') || (this.user.address.email === '' && this.emailConf === null)) {
        return true;
      } else {
        return false;
      } 
    }
  }
}



