import { Component, OnDestroy, HostListener } from '@angular/core';
import { NavParams, ModalController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { PeripheralConfigurationPage } from '../peripheral-configuration/peripheral-configuration';
import { TaskEditorPage } from '../task-editor/task-editor';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { CommonFunctions } from '../../providers/common-functions';
import { UserSession } from '../../providers/user-session';
import { Middleware } from '../../providers/middleware';
import { MiddlewareCloud }  from '../../providers/middleware-cloud';


@Component({
  selector: 'page-vm-peripherals',
  templateUrl: 'vm-peripherals.html'
})
export class VmPeripheralsPage implements OnDestroy {

  // Permissions.
  updVMEnabled: boolean = false;
  readVMEnabled: boolean = false;
  delVMEnabled: boolean = false;

  genericPer: Array<any> = [];
  visiblePer: Array<any> = [];
  ready: boolean = false;
  perConfigs: Array<any> = [];

  perConfigsSubs: Subscription = null;
  middlewareSubs: Subscription = null;
  mwCloudSubs: Subscription = null;

  laundryId: string = null;

  tabletMode: boolean = false;

  isSaveEnabled: boolean = true;

  rows = [];
  n = 4;

  configEnabled: boolean = true;
  issueEnabled: boolean = true;

  storage: any = new Storage();      
  cloudMode: boolean = false;

  constructor(private navParams: NavParams,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private cf: CommonFunctions,
              private userSession: UserSession,
              private middlewareCloud: MiddlewareCloud,
              private middleware: Middleware) {
    if (window.innerWidth < window.innerHeight) {
      this.tabletMode = true;
      this.n = 3;
    }

    this.backendApi.getLaundry(this.navParams.data).subscribe(
      res => {
        if (res.laundry) {
          this.laundryId = res.laundry.laundryId;

          this.storage.get('laundryInfo').then(laundryInfo => {
            if (!laundryInfo || (laundryInfo && laundryInfo.laundryId !== this.laundryId)) {
              this.cloudMode = true;
              // Connect to remote vm (websockets cloud service). 
              this.middlewareCloud.connect(this.laundryId);
              // Subscribe to incomming packages from middleware cloud.
              this.mwCloudSubs = this.middlewareCloud.getPkg().subscribe(
                pkg => {
                  if (typeof pkg === 'object') {
                    if (!pkg.hasOwnProperty('code')) {
                      switch (pkg.op) {
                        case 'status_per':
                          if (pkg.hasOwnProperty('dev')) this.setStatus(pkg.dev);
                          break;
                      }
                    }
                  }
                }
              );
            } else {
              // Handle incoming data from the vending machine CPU.
              this.middlewareSubs = this.middleware.getPkg().subscribe(
                pkg => {
                  if (!pkg) return;

                  if (!pkg.hasOwnProperty('code')) {
                    switch (pkg.op) {
                      case 'status_per':
                      if (pkg.hasOwnProperty('dev')) this.setStatus(pkg.dev);
                        break;
                    }
                  }
                }
              );
            }
          }).then(() => {
            this.statusRequest();
          });
        }
      },
      err => {}
    );

    // Enable/disable insert new laundry option.
    this.updVMEnabled = this.userSession.getPermission('vending-machine-update');
    this.delVMEnabled = this.userSession.getPermission('vending-machine-delete');
    this.issueEnabled = this.userSession.getPermission('maintenance-insert');
    this.readVMEnabled = this.userSession.getPermission('vending-machine-read');

    // Get vending machine peripherals templates.
    this.backendApi.getGenericPeripherals().subscribe(
      res => {
        this.genericPer = res.filter(item => (item.enabled));
        this.genericPer.forEach(el => {
          el.visible = false;
          el.status = 'NOK';
        });
        this.ready = true;

        // Send peripherals configurations request.
        this.cs.setCommand({ src: 'vm-peripherals', dest: 'vending-machine-configuration', cmd: 'get-per-configs' });
      },
      err => {}
    );

    // Get incoming configurations.
    this.perConfigsSubs = this.cs.getPerConfigs().subscribe(
      res => {
        if (res.dest !== 'vm-peripherals') return;
        this.perConfigs = res.data;
        this.visiblePer = [];
        this.genericPer.forEach(el => {
          el.visible = false;
        });
        this.perConfigs.forEach(el1 => {
          let per = this.genericPer.find(el2 => (el2.type === el1.type));
          per.visible = true;
          this.visiblePer.push(per);
        });
        this.rows = [];
        this.cf.reshape(this.visiblePer, this.n).forEach((el, i) => {
          this.rows.push(i);
        });
        this.sortPerList();
        this.isSaveEnabled = true;
      }
    );
  }

  ionViewWillEnter() {
    setTimeout(() => {
      this.statusRequest();      
    }, 1000);
  }

  ngOnDestroy() {
    if (this.perConfigsSubs) this.perConfigsSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
    if (this.mwCloudSubs) this.mwCloudSubs.unsubscribe();
    this.middlewareCloud.disconnect();
  }

  sortPerList() {
    // Order peripheral list.
    this.visiblePer = this.visiblePer.sort((a, b) => {
      if (this.translate.getTranslation(a.type) < this.translate.getTranslation(b.type)) return -1;
      if (this.translate.getTranslation(a.type) >= this.translate.getTranslation(b.type)) return 1;
    });
  }

  // NOTE: ORIGINAL SAVE() FUNCTION
  sendConfig() {
    // Send configuration request to low-level and backend.
    if (this.isSaveEnabled) {
      this.cs.setCommand({ src: 'vm-peripherals', dest: 'vending-machine-configuration', cmd: 'config-save', perConfigReq: this.configRequest() });
      this.statusRequest();
    }
  }

  save() {
    // Send configuration request to backend.
    if (this.isSaveEnabled) {
      this.cs.setCommand({ src: 'vm-peripherals', dest: 'vending-machine-configuration', cmd: 'save', perConfigReq: this.configRequest() });
      this.statusRequest();
    }
  }

  delete() {
    this.cs.setCommand({ src: 'vm-peripherals', dest: 'vending-machine-configuration', cmd: 'delete', perConfigReq: this.configRequest() });
  }

  togglePerVisibility(peripheral) {
    this.visiblePer = this.genericPer.filter(el => (el.visible));
    this.rows = [];
    this.cf.reshape(this.visiblePer, this.n).forEach((el, i) => {
      this.rows.push(i);
    });
    this.sortPerList();
  }

  configPer(peripheral) {
    // Check user permission to interface configuration.
    if (!this.readVMEnabled || !this.configEnabled) return;

    let modalArgs = null;
    let modalPage = null;
    let perConfig = this.perConfigs.find(el => (el.type === peripheral.type));
    let perParams = this.getPerParams(peripheral, perConfig);
    // Setup modal for vending machine peripherlas configuration.
    modalArgs = {
      type: peripheral.type, 
      params: perParams,
      img: peripheral.imgPath,
      delete: this.delVMEnabled,
      update: this.updVMEnabled,
    };
    modalPage = this.modalCtrl.create(PeripheralConfigurationPage, modalArgs);
    modalPage.onDidDismiss(
      res => {
        if (!res || (res.action === 'delete' && !this.delVMEnabled)) return;
        // Delete peropheral configuration action.
        if (res.action === 'delete') {
          perConfig.action = 'delete';
          this.delete();
        }
        // Insert or Update peripheral configuration action.
        else {
          if (perConfig) {
            perConfig.action = 'update';
            res.params.forEach(el => {
              if (!el.config) {
                perConfig[el.key] = el.value;
              } else {
                perConfig.config[el.key] = el.value;
              }
            });
            // Update action.
          } else {
            // Insert action.
            let obj = {
              type: peripheral.type,
              action: 'insert',
              config: {},
            };
            res.params.forEach(el => {
              if (!el.config) {
                obj[el.key] = el.value;
              } else {
                obj.config[el.key] = el.value;
              }
            });
            // Store new periphral configurations.
            this.perConfigs.push(obj);
          }
        }
        // Send configuration to parent component.
        this.cs.setPerConfigs({src: 'vm-peripherals', dest: 'vending-machine-configuration', data: this.perConfigs});
      }
    );
    modalPage.present();
  }

  getPerParams(peripheral, perConfig) {
    let perParams = this.cf.getCopy(peripheral.config);
    perParams.forEach(el => {
      if (el.config) {
        (perConfig) ? el['value'] = perConfig.config[el.key] : el['value'] = '';
      } else {
        (perConfig) ? el['value'] = perConfig[el.key] : el['value'] = '';
      }
    });
    return perParams;
  }

  setStatus(status) {
    let newStatusObj = null;
    this.visiblePer.forEach(el1 => {
      newStatusObj = status.find(el2 => (el2.type === this.translatePeripheralType(el1.type)));
      if (newStatusObj) {
        (newStatusObj.active === '0') ? el1.status = 'NOK' : el1.status = 'OK';
      }
    });
  }

  getStatusClass(peripheral) {
    switch (peripheral.status) {
      case 'NOK':
        return 'status-n-ok';
      case 'OK':
        return 'status-ok';
    }
  }

  statusRequest() {
    // Send vending machine peripherals status request.
    let pkg = {
      op: 'status_per',
    };
    if (this.cloudMode) {
      this.middlewareCloud.send(pkg);
    } else {
      this.middleware.send(pkg);      
    }
  }

  configRequest(): any {
    let pkg = {
      op: 'config_per',
      per: [],
    };
    this.perConfigs.forEach(per => {
      let obj = {};
      if (per.action !== 'delete') {
        if (!per.config.hasOwnProperty('protocol')) {  // rfid w/r peripheral
          obj = {
            protocol: 'spi',
            type: this.translatePeripheralType(per.type),
          };
        } else {
          switch (per.config.protocol) {
            case 'cctalk':
              obj = {
                protocol: 'ccTalk',
                baudRate: '9600', //per.config.br,
                addr: per.config.addr,
                type: this.translatePeripheralType(per.type),
              };
              break;
            case 'MDB':
              obj = {
                protocol: 'MDB',
                baudRate: '9600', //per.config.br,
                addr: per.config.addr,
                type: this.translatePeripheralType(per.type),
              };
              break;
            case 'pulse':
              if (this.translatePeripheralType(per.type) === 'card-dispenser') {
                obj = {
                  protocol: 'pulse',
                  addr: per.config.addr,
                  type: this.translatePeripheralType(per.type),
                };
              }              
              break;
            case 'rs232':
              if (this.translatePeripheralType(per.type) === 'card-dispenser') {
                obj = {
                  protocol: 'rs232',
                  baudRate: per.config.br,
                  addr: per.config.addr,
                  type: this.translatePeripheralType(per.type),
                };
              } else {
                obj = {
                  protocol: 'rs232',
                  baudRate: per.config.br,
                  type: this.translatePeripheralType(per.type),
                };
              }
              break;
          } 
        }
      } else {
        if (!per.config.hasOwnProperty('protocol')) {  // rfid w/r peripheral
          obj = {
            type: this.translatePeripheralType(per.type),
            delete: true,
          };
        } else {
          switch (per.config.protocol) {
            case 'cctalk':
              obj = {
                addr: per.config.addr,
                type: this.translatePeripheralType(per.type),
                delete: true,
              };
              break;
            case 'MDB':
              obj = {
                addr: per.config.addr,
                type: this.translatePeripheralType(per.type),
                delete: true,
              };
              break;
            case 'rs232':
              if (this.translatePeripheralType(per.type) === 'card-dispenser') {
                obj = {
                  addr: per.config.addr,
                  type: this.translatePeripheralType(per.type),
                  delete: true,
                };
              } else {
                obj = {
                  type: this.translatePeripheralType(per.type),
                  delete: true,
                };
              }
              break;
          }
        }
      }
      pkg.per.push(obj);
    });
    return pkg;
  }

  reportIssue(peripheral) {
    this.configEnabled = false;
    let issueData = {
      laundryId: this.laundryId,
      deviceId: this.perConfigs.find(item => (item.type === peripheral.type)).peripheralId,
      device: 'PERIPHERAL',
    };
    let taskModal = this.modalCtrl.create(TaskEditorPage, issueData);
    taskModal.onDidDismiss(
      res => {
        this.configEnabled = true;
        if (!res) return;

        if (res.cmd === 'REFRESH') {
          // Do something...
        }
      }
    )
    taskModal.present();
  }

  @HostListener('window:resize', ['$event'])
  onResize(event) {
    if (event.target.innerWidth < event.target.innerHeight) {
      this.tabletMode = true;
    } else {
      this.tabletMode = false;
    }
  }

  // NOTE: Development Code
  translatePeripheralType(type) {
    switch (type) {
      case 'BILL_ACCEPTOR': return 'bill-acceptor';
      case 'CARD_DISPENSER': return 'card-dispenser';
      case 'COIN_ACCEPTOR': return 'coin-acceptor';
      case 'HOPPER': return 'hopper';
      case 'PRINTER': return 'printer';
      case 'RFID_RW': return 'rfid-rw';
    }
  }

}



