import { Component, OnDestroy } from '@angular/core';
import { NavParams, ViewController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';
import { Md5 } from 'ts-md5/dist/md5';

// Service/provider components.
import { TranslateService } from '../../translate';
import { CommonServices } from '../../providers/common-services';
import { Inactivity } from '../../providers/inactivity';
import { Middleware } from '../../providers/middleware';
import { Client } from '../../providers/client';


@Component({
  selector: 'page-alert',
  templateUrl: 'alert.html'
})
export class AlertPage implements OnDestroy {

  cardInserted: boolean = false;

  alertTimeout: number = 4*1000;  // [ms]

  dismissTimeout: number = 40*1000; // [ms] <-- Timeout to insert client card to be written.
  // dismissTimeout: number = 5*1000; // [ms] <-- Timeout to insert client card to be written.

  cmdSubs: Subscription = null;
  timerSubs: Subscription = null;
  middlewareSubs: Subscription = null;
  type: string = null;
  title: string = null;
  msg: string = null;

  isSpinnerOn: boolean = false;

  cardId: any = null;

  isBonusMsg: boolean = false;

  constructor(private viewCtrl: ViewController,
              private navParams: NavParams,
              private cs: CommonServices,
              private translate: TranslateService,
              private middleware: Middleware,
              private clientInt: Client,
              private inactivityTimer: Inactivity) {
    // Subscribe to inactivity timer event.
    this.timerSubs = this.inactivityTimer.getInactivitySignal().subscribe(signal => {
      if (signal.state === 'INACTIVE') this.cancel();
    });

    // Subscribe to commands from other components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'modal' && res.dest !== 'alert') return;

        switch(res.cmd) {
          case 'CLOSE':
            this.cancel();
            break;
        }
      }
    );

    // Get input parameters.
    this.type = this.navParams.data.type;
    this.title = this.navParams.data.title;
    this.msg = this.navParams.data.msg;

    // Check for bonus.
    if (this.navParams.data.hasOwnProperty('bonusValue')) {
      this.isBonusMsg = true;
    } 

    // Dismiss timeout
    if (this.type === 'alert' || this.type === 'warning-ok-btn' || this.type === 'success' || this.msg === 'NO_CHANGE_MSG') {
      setTimeout(() => this.cancel(), this.alertTimeout);
    }

    if (this.type === 'receipt') {
      setTimeout(() => this.cancel(), 3000);
    }

    if (this.type === 'card-charge' || this.type === 'card-recharge') {
      setTimeout(() => {
        if (!this.cardInserted) this.cancel();         
      }, this.dismissTimeout);
    }

    if (this.type === 'card-charge' || this.type === 'card-recharge' || this.type === 'card-access') {
      this.middlewareSubs = this.middleware.getPkg().subscribe(
        pkg => {
          if (!pkg) return;
          if (!pkg.hasOwnProperty('code')) {
            switch (pkg.op) {
              case 'card-inserted':
                this.cardInserted = true;
                this.cardId = pkg.data.cardId;
                // Send data to store in the client card.
                if (this.type === 'card-charge') {
                  // clear previous timer.
                  setTimeout(() => {
                    this.cancel();
                  }, this.dismissTimeout);
                  this.sendCardInfo('BUY');
                  this.presentChargingMsg();                  
                }
                if (this.type === 'card-recharge') {
                  this.sendCardInfo('RECHARGE');
                  this.presentChargingMsg();                  
                }
                if (this.type === 'card-access') {
                  this.sendCardInfo('ACCESS');
                  this.presentChargingMsg(); 
                }
                break;
            }
          } else {
            if (pkg.op === 'write-card' && pkg.code === '201') {
              this.confirm();
            }
            if (pkg.op === 'write-card' && pkg.code !== '200' && pkg.code !== '201') {
              this.cancel();
            }
          }
        }
      );

      if (this.type === 'card-recharge' && this.navParams.data.cardData.cardId) {
        if (this.navParams.data.hasOwnProperty('write') && this.navParams.data.write) {
          this.cardInserted = true;
          this.sendCardInfo('RECHARGE');
          this.presentWritingMsg();
        } else {
          this.cardInserted = true;
          this.sendCardInfo('RECHARGE');
          this.presentChargingMsg();
        }
      }
    }
  }

  presentChargingMsg() {
    this.title = 'RECHARGING_TITLE';
    this.msg = 'RECHARGING_MSG';
    this.isSpinnerOn = true;
  }

  presentWritingMsg() {
    this.title = 'WRITING_TITLE';
    this.msg = 'RECHARGING_MSG';
    this.isSpinnerOn = true;
  }

  sendCardInfo(type) {
    let pkg = null;
    switch (type) {
      case 'BUY':
        let cardBalanceBuy = (this.navParams.data.cardData.balance * 100);
        if (cardBalanceBuy < 0) cardBalanceBuy = 0;
        pkg =   {
          op: 'write-card',
          data: {
            cardId: this.navParams.data.cardData.cardId,
            name: this.navParams.data.cardData.name,
            nif: this.navParams.data.cardData.nif,
            balance: cardBalanceBuy.toString(),
            new: false,
            admin: false,
          },
        };
        break;
      case 'RECHARGE':
        if (this.navParams.data.cardData.cardId) {
          let cardBalanceRecharge = (this.navParams.data.cardData.balance * 100);
          if (cardBalanceRecharge < 0) cardBalanceRecharge = 0;          
          pkg =   {
            op: 'write-card',
            data: {
              cardId: this.navParams.data.cardData.cardId,
              name: this.navParams.data.cardData.name,
              nif: this.navParams.data.cardData.nif,
              balance: cardBalanceRecharge.toString(),
              new: false,
              admin: false,
            },
          };
        } else {
          let cardBalanceRecharge = ((this.clientInt.client.balanceCard + this.navParams.data.cardData.balance)*100);
          if (cardBalanceRecharge < 0) cardBalanceRecharge = 0;          
          pkg =   {
            op: 'write-card',
            data: {
              cardId: this.clientInt.client.cardNumber,
              name: this.clientInt.client.name,
              nif: this.clientInt.client.nif,
              balance: cardBalanceRecharge.toString(),
              new: false,
              admin: false,
            },
          };
        }
        break;
      case 'ACCESS':
        let cardBalanceAccess = (this.navParams.data.cardData.balance * 100);
        if (cardBalanceAccess < 0) cardBalanceAccess = 0;          
        pkg =   {
          op: 'write-card',
          data: {
            cardId: this.navParams.data.cardData.cardId,
            name: this.navParams.data.cardData.name,
            nif: this.navParams.data.cardData.nif,
            balance: cardBalanceAccess.toString(),
            ownerId: this.navParams.data.cardData.ownerId,
            new: false,
            admin: true,
          },
        };
        break;
    }
    this.middleware.send(pkg);
  }

  ngOnDestroy() {
    if (this.timerSubs) this.timerSubs.unsubscribe();
    if (this.cmdSubs) this.cmdSubs.unsubscribe();
    if (this.middlewareSubs) this.middlewareSubs.unsubscribe();
  }

  confirm() {
    this.viewCtrl.dismiss({ confirm: true, cardId: this.cardId })
  }

  cancel() {
    this.viewCtrl.dismiss({ confirm: false, cardId: this.cardId });
  }

}



