// Geolocation Services.
//
// -------------------------------------------------------------------------- //
  getCoordinates(address): Observable<any> {
    let outputFormat = 'json';
    let lang = 'pt-PT';
    address = address.replace(' ', '+');
    return this.http.get(`https://maps.googleapis.com/maps/api/geocode/${outputFormat}?language=${lang}&address=${address}&key=${this.googleKey}`)
      .map(res => res.json())
      .catch(err => Observable.throw(err.json()));
  }

  getAddress(lat, lng): Observable<any> {
    let outputFormat = 'json';
    let lang = 'pt-PT';
    return this.http.get(`https://maps.googleapis.com/maps/api/geocode/${outputFormat}?language=${lang}&latlng=${lat},${lng}&key=${this.googleKey}`)
      .map(res => res.json())
      .catch(err => Observable.throw(err.json()));
  }

