import { Component, OnDestroy, HostListener } from '@angular/core';
import { NavParams, ModalController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { Subscription } from 'rxjs/Rx';

// Page components.
import { TaskEditorPage } from '../task-editor/task-editor';

// Service/provider components.
import { TranslateService } from '../../translate';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { CommonServices } from '../../providers/common-services';
import { UserSession } from '../../providers/user-session';
import { MiddlewareCloud } from '../../providers/middleware-cloud';


@Component({
  selector: 'page-vending-machine',
  templateUrl: 'vending-machine.html'
})
export class VendingMachinePage implements OnDestroy {

  // Permissions.
  updVMEnabled: boolean = false;
  delVMEnabled: boolean = false;

  activeSection: string = 'vending-machine';
  laundry: any = null;
  readOnly: boolean = false;
  vmImg: string = "assets/img/vm-icon-big.png";  
  storage: any = null;

  form: Array<any> = [];

  issueEnabled: boolean = false;

  tabletMode: boolean = false;

  constructor(private navParams: NavParams,
              private modalCtrl: ModalController,
              private translate: TranslateService,
              private backendApi: BackendApiProvider,
              private cs: CommonServices,
              private userSession: UserSession,
              private middlewareCloud: MiddlewareCloud) {
    // Enable/disable insert new laundry option.
    this.updVMEnabled = this.userSession.getPermission('vending-machine-update');
    this.delVMEnabled = this.userSession.getPermission('vending-machine-delete');
    this.issueEnabled = this.userSession.getPermission('maintenance-insert');

    if (this.navParams.data.hasOwnProperty('vendingMachineId')) {
      this.issueEnabled = true;
      this.backendApi.getLaundry(this.navParams.data.vendingMachineId).subscribe(
        res => {
          this.laundry = res.laundry;
          this.storage = new Storage();
          this.storage.get('isVM').then(isVM => {
            if (!isVM && this.laundry) {
              this.middlewareCloud.connect(this.laundry.laundryId);
            }
          })
        },
        err => {}
      );
    } else {
      this.issueEnabled = false;
      this.readOnly = false;   
    }

    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    }
  }

  ngOnDestroy() {
    this.middlewareCloud.disconnect();
  }

  edit() {
    this.readOnly = !this.readOnly;
  }

  save() {
    this.cs.setCommand({ src: 'vending-machine', dest: 'vending-machine-configuration', cmd: 'save' });
  }

  delete() {
    this.cs.setCommand({ src: 'vending-machine', dest: 'vending-machine-configuration', cmd: 'delete' });
  }

  reportIssue(peripheral) {
    let issueData = {
      laundryId: (this.laundry) ? this.laundry.laundryId : null,
      deviceId: this.navParams.data.vendingMachineId,
      device: 'VM',
    };
    let taskModal = this.modalCtrl.create(TaskEditorPage, issueData);
    taskModal.onDidDismiss(
      res => {
        if (!res) return;

        if (res.cmd === 'REFRESH') {
          // Do something...
        }
      }
    )
    taskModal.present();
  }

  @HostListener('window:resize', ['$event'])
  onResize(event) {
    if (window.innerWidth <= 767) {
      this.tabletMode = true;
    } else {
      this.tabletMode = false;      
    }
  }

}



