import { Injectable } from '@angular/core';
import { Subject } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';
import { Observable } from 'rxjs/Observable';
import { Subscription } from 'rxjs/Rx';
import 'rxjs/add/observable/forkJoin';

import { BackendApiProvider } from './backend-api-provider';
import { Middleware } from './middleware';
import { OfflineData } from './offline-data';


@Injectable()
 export class Machines {

  reservationTimeout: number = 3*60*1000;  // [ms]

  storage = new Storage();
  machines: Array<any> = [];
  programs: Array<any> = [];
  resTimers: Array<any> = [];

  wasMachine: Subject<any> = null;
  dryMachine: Subject<any> = null;

  useOfflineData: boolean = false;

  constructor(private offlineData: OfflineData,
              private middleware: Middleware,
              private backendApi: BackendApiProvider) {
    this.useOfflineData = this.offlineData.useOfflineData;
    this.wasMachine = new Subject<any>();
    this.dryMachine = new Subject<any>();

    this.storage.get('laundryInfo').then(laundryInfo => {
      if (laundryInfo) {
        setTimeout(() => {
          this.getMachines(laundryInfo.laundryId);
        }, 500);
      } else {

      }
    });
  }

  getMachines(laundryId) {
    // Get all machines.
    if (!this.offlineData.useOfflineData) {
      let wasMachinesObs = this.backendApi.getMachinesConfigs(laundryId, 'wash');
      let dryMachinesObs = this.backendApi.getMachinesConfigs(laundryId, 'dry');
      let programsObs = this.backendApi.getPrograms(laundryId);
      let allProgramsObs = this.backendApi.getAllPrograms(laundryId);;

      Observable.forkJoin([wasMachinesObs, dryMachinesObs, programsObs, allProgramsObs]).subscribe(
        res => {
          // Save prev status.
          let machinesBckup = this.machines;
          this.machines = res[0].concat(res[1]);
          if (this.resTimers.length === 0) {
            this.machines.forEach((el, i) => {
              if (machinesBckup.length === 0) {
                el.status = 'OK';
              } else {
                el.status = machinesBckup[i].status;
              }
              this.resTimers.push({ intId: el.config.intId, channel: el.peripheral_has_machines[0].channel, resTimer: null, progDur: 0 });              
            });
          } else {
            this.machines.forEach((el, i) => {
              if (machinesBckup.length === 0) {
                el.status = 'OK';
              } else {
                el.status = machinesBckup[i].status;
              }
            });
          }
          this.programs = res[3];
        },
        err => {}
      );
    } else {
      // NOTE: REMOVE TIMEOUT
      setTimeout(() => {
        this.machines = this.offlineData.getData('wasMachines').concat(this.offlineData.getData('dryMachines'));
        if (this.resTimers.length === 0) {
          this.machines.forEach(el => {
            el.status = 'OK';
            this.resTimers.push({ intId: el.config.intId, channel: el.peripheral_has_machines[0].channel, resTimer: null, progDur: 0 });
          });
        } else {
          this.machines.forEach(el => {
            el.status = 'OK';
          });
        }
      }, 2000);
    }
  }

  updateMachineState(pkg) {
    let machine = null;
    let timer = null;
    if (pkg.op !== 'cancel-orders') {
      machine = this.machines.find(item => (item.config.intId === pkg.data.id && item.peripheral_has_machines[0].channel === pkg.data.chn));
      timer = this.resTimers.find(item => (item.intId === pkg.data.id && item.channel === pkg.data.chn));
    }

    switch (pkg.op) {
      case 'machine-issue':
        if (!machine) return;
        if (pkg.data.active === '0') {
          clearTimeout(timer.resTimer);          
          machine.status = 'ISSUE';

          this.sendMachineChanges(machine);
        } else {
          if (pkg.data.status[pkg.data.status.length - Number(pkg.data.chn)] === '0') { // Machine working.
            if (machine.hasOwnProperty('config') && machine.config.hasOwnProperty('activation') && machine.config.activation === 'high') {
              machine.status = 'OK';
            }

            if (machine.hasOwnProperty('config') && machine.config.hasOwnProperty('activation') && machine.config.activation === 'low') {
              machine.status = 'NOK';
            }
          } else { // Machine idle.
            if (machine.status !== 'RES') {
              if (machine.hasOwnProperty('config') && machine.config.hasOwnProperty('activation') && machine.config.activation === 'high') {
                machine.status = 'NOK';
              }
  
              if (machine.hasOwnProperty('config') && machine.config.hasOwnProperty('activation') && machine.config.activation === 'low') {
                machine.status = 'OK';
              }
            }
          }
        }
        return;
      case 'machine-started':
      case 'door-opened':
        this.middleware.send({ op: 'status_int' });
        break;
      case 'machine-reserved':
        if (!machine) return;
        // Set program duration.
        this.setMahineProgDuration(pkg.data.id, pkg.data.chn, pkg.data.progDur);
        machine.status = 'RES';

        timer.resTimer = setTimeout(() => {
            machine.status = 'OK';

            let machines = [];
            this.machines.forEach(item => {
              if (item.config.intId === machine.config.intId && item.peripheral_has_machines[0].channel === machine.peripheral_has_machines[0].channel) {
                machines.push(JSON.parse(JSON.stringify(machine)));
              } else {
                machines.push(item);
              }
            });
            this.machines = machines;
  
            timer.resTimer = null;
            this.sendMachineChanges(machine);
          
        }, this.reservationTimeout);
        break;
      case 'machine-res-canceled':
        machine.status = 'OK';
        if (machine.status === 'RES') {
          machine.status = 'OK';
        }
        break
      case 'cancel-orders':
        this.machines.forEach(machine => {
          if (machine.hasOwnProperty('status') && machine.status === 'RES') {
            machine.status = 'OK';
            this.sendMachineChanges(machine);
          }
        });
        break;
    }
    if (machine) {
      this.sendMachineChanges(machine);
    }
  }

  setMahineProgDuration(intId, chn, progDur) {
    let timer = this.resTimers.find(item => (item.intId === intId && item.channel === chn));
    timer.progDur = progDur;
  }

  sendMachineChanges(machine) {
    if (machine.type === 'wash') {
      this.wasMachine.next(machine);
    }

    if (machine.type === 'dry') {
      this.dryMachine.next(machine);
    }
  }

  getPrograms(type) {
    return this.programs.filter(el => (el.program.type === type));
  }

  getWasMachines() {
      return this.machines.filter(item => (item.type === 'wash'));
  }

  getDryMachines() {
    return this.machines.filter(item => (item.type === 'dry'));
  }

  getWasMachineStatus() {
    return this.wasMachine.asObservable();
  }

  getDryMachineStatus() {
    return this.dryMachine.asObservable();
  }

  setReservation(intId, chn) {
    let timer = this.resTimers.find(item => (item.intId === intId && item.channel === chn));
    clearTimeout(timer.resTimer);          
  }
}



