import { Injectable } from '@angular/core';


@Injectable()
export class UserSession {

  name: string = '';
  id: string = '';
  roleId: string = '';
  roleName: string = '';
  roleIdUser: string = '';
  permissions: any = null;

  constructor() {}

  clearSession() {
    this.name = '';
    this.id = '';
    this.roleId = '';
    this.roleName = '';
    this.roleIdUser = '';
    this.permissions = null;
  }

  setSessionAttr(decodedJWT) {
    this.name = decodedJWT.name;
    this.id = decodedJWT.id;
    this.roleId = decodedJWT.roleId;
    this.roleIdUser = decodedJWT.roleIdUser;
  }

  setPermissions(permissions) {
    this.permissions = permissions;
  }

  getPermissions() {
    return this.permissions;
  }

  getPermission(feature): boolean {
    switch (feature) {
      // Laundry section.
      case 'laundry-insert':
        return this.permissions.laundry.insert;
      case 'laundry-read':
        return this.permissions.laundry.read;
      case 'laundry-update':
        return this.permissions.laundry.update;
      case 'laundry-delete':
        return this.permissions.laundry.delete;

      // Machine section.
      case 'machine-insert':
        return this.permissions.machine.insert;
      case 'machine-read':
        return this.permissions.machine.read;
      case 'machine-update':
        return this.permissions.machine.update;
      case 'machine-delete':
        return this.permissions.machine.delete;
      case 'machine-program':
        return this.permissions.machine.program;
      case 'machine-price':
        return this.permissions.machine.price;

      // Vending machine section.
      case 'vending-machine-insert':
        return this.permissions.vendingMachine.insert;
      case 'vending-machine-read':
        return this.permissions.vendingMachine.read;
      case 'vending-machine-update':
        return this.permissions.vendingMachine.update;
      case 'vending-machine-delete':
        return this.permissions.vendingMachine.delete;
      case 'vending-machine-configDev':
        return this.permissions.vendingMachine.configDev;

      // User section.
      case 'user-insert':
        return this.permissions.user.insert;
      case 'user-read':
        return this.permissions.user.read;
      case 'user-update':
        return this.permissions.user.update;
      case 'user-delete':
        return this.permissions.user.delete;

      // Role section.
      case 'role-insert':
        // return this.permissions.role.insert;
        return false;
      case 'role-read':
        return this.permissions.role.read;
      case 'role-update':
        return this.permissions.role.update;
      case 'role-delete':
        return this.permissions.role.delete;

      // Maintenance section.
      case 'maintenance-insert':
        return this.permissions.maintenance.insert;
      case 'maintenance-read':
        return this.permissions.maintenance.read;
      case 'maintenance-update':
        return this.permissions.maintenance.update;
      case 'maintenance-delete':
        return this.permissions.maintenance.delete;
    }
    return false;
  }

}



