import { Component, OnDestroy } from '@angular/core';
import { NavParams, ViewController } from 'ionic-angular';
import { Subscription } from 'rxjs/Rx';

// Service/provider components.
import { TranslateService } from '../../translate';
import { CommonServices } from '../../providers/common-services';
import { Inactivity } from '../../providers/inactivity';
import { HelpTour } from '../../providers/help-tour'


@Component({
  selector: 'page-select-program',
  templateUrl: 'select-program.html'
})
export class SelectProgramPage implements OnDestroy {

  plusImg: string = 'assets/img/+.png';
  minusImg: string = 'assets/img/-.png';
  cardImg: string = 'assets/img/cartao-icon.png';
  coinImg: string = 'assets/img/moedas-icon.png';

  minDuration: number = null; // Minimum drying duration [min.]
  maxDuration: number = 120; // Maximum drying duration [min.] // NOTE: Drying machine parameter!? => goes into this.machine.config.
  duration: number = null;
  durStep: number = null;  // TODO: Congifured in the machine object (drying case)

  machineType: string = null;
  machine: any = null;
  programs: Array<any> = [];
  img: string = null;
  price: string = null;
  priceCard: string = null;
  // NOTE: Only used for drying machines.
  cost: number = null;
  costCard: number = null;

  cmdSubs: Subscription = null;
  timerSubs: Subscription = null;

  wasImpulses: number = 1;
  dryImpulses: number = 1;

  constructor(private navParams: NavParams,
              private viewCtrl: ViewController,
              private cs: CommonServices,
              private inactivityTimer: Inactivity,
              private help: HelpTour,
              private translate: TranslateService) {
    // Subscribe to inactivity timer event.
    this.timerSubs = this.inactivityTimer.getInactivitySignal().subscribe(signal => {
      if (signal.state === 'INACTIVE') {
        // dismiss modal component.
        this.close();
      }
    });

    // Subscribe to commands from other components.
    this.cmdSubs = this.cs.getCommand().subscribe(
      res => {
        if (res.dest !== 'modal' && res.dest !== 'select-program') return;

        switch(res.cmd) {
          case 'CLOSE':
            this.close();
            break;
        }
      }
    );

    this.machineType = this.navParams.data.type;
    this.machine = this.navParams.data.machine;
    this.programs = this.navParams.data.programs;

    if (this.machineType === 'washing-machine') {
      this.programs.forEach(el => {
        el.selected = false;

        if (!el.duration) {
          el.duration = el.program.duration.toString();
        }
      });
      // Set initial program.
      this.programs[0].selected = true;
      this.price = this.programs[0].price;
      this.priceCard = this.programs[0].priceCard;
    } else {
      this.minDuration = Number(this.machine.config.durPerImp);
      this.duration = this.minDuration;
      this.durStep = Number(this.machine.config.durPerImp);
      this.price = this.navParams.data.programs.price;
      this.priceCard = this.navParams.data.programs.priceCard;
      this.cost = Number(this.price);
      this.costCard = Number(this.priceCard);
    }
    this.img = this.navParams.data.img;
  }

  ngOnDestroy() {
    if (this.timerSubs) this.timerSubs.unsubscribe();
    if (this.cmdSubs) this.cmdSubs.unsubscribe();
  }

  close() {
    this.help.cancelTour();
    this.viewCtrl.dismiss();
  }

  submit(action) {
    let program = null;
    switch (this.machineType) {
      case 'washing-machine':
        program = this.programs.find(program => (program.selected));
        program.selPrice = program.price;
        program.selPriceCard = program.priceCard;

        // NOTE: program <-> impules equivalence
        program.impulses = this.wasImpulses.toString();
        break;
      case 'drying-machine':
        program = this.programs;
        program.selPrice = this.cost.toFixed(2);
        program.selPriceCard = this.costCard.toFixed(2);
        program.program.selDuration = `- ${this.duration} min.`;

        // NOTE: program <-> impules equivalence
        program.totalDuration = this.duration;
        program.impulses = this.dryImpulses.toString();
        break;
    }
    if (action === 'continue' && (String(this.help.tourType) === 'WASHING' || String(this.help.tourType) === 'DRYING')) {
      this.help.cancelTour();
      setTimeout(() => {
        this.help.startTour('RESERV');
      }, 450);
    }
    if (action === 'finalize') this.help.next();    

    this.viewCtrl.dismiss({
      machine: JSON.parse(JSON.stringify(this.machine)),
      program: JSON.parse(JSON.stringify(program)),
      action: JSON.parse(JSON.stringify(action)),
    });
  }

  updateDuration(action) {
    switch (action) {
      case 'increment':
        this.duration += this.durStep;
        this.dryImpulses++;
        if (this.duration > this.maxDuration) {
          this.duration -= this.durStep;
          this.dryImpulses--;
        }
        break;
      case 'decrement':
        if (this.duration > this.minDuration) {
          this.duration -= this.durStep;
          this.dryImpulses--;
        }
        break;
    }
    this.cost = (this.duration/this.durStep) * Number(this.price);
    this.costCard = (this.duration/this.durStep) * Number(this.priceCard);
  }

  selectProgram(program) {
    this.programs.forEach(program => {
      program.selected = false;
    });
    program.selected = !program.selected;
    // Update program price.
    this.price = program.price;
    this.priceCard = program.priceCard;
  }

}



