import { Injectable } from '@angular/core';
import { Observable } from 'rxjs/Rx';
import { Subject } from 'rxjs/Rx';
import { Storage } from '@ionic/storage';

import { TranslateService } from '../translate';

import * as io from "socket.io-client";

declare var swal: any;


@Injectable()
export class MiddlewareCloud {
  // host: string = 'https://lma-prod-websocket.azurewebsites.net';
  host: string = 'wss://wsapi.washstation.pt';
  // host: string = 'ws://lma-websocket.muvu.tech';
  // host: string = 'http://192.168.1.69:4000';
  socket: SocketIOClient.Socket = null;
  incomingPkgObs: Subject<any> = null;

  storage: any = new Storage();

  sessionToken: string = null;

  constructor(private translate: TranslateService) {
    this.incomingPkgObs = new Subject<any>();

    this.storage.get('id_token').then(idToken => { this.sessionToken = idToken; });
  }

  connect(laundryId) {
    if (this.socket) return;
    this.socket = io.connect(this.host,  { reconnection: true, reconnectionAttempts: 4 });

    this.socket.on('connect', () => {
      this.socket.emit('subscribe', { room: `cloud.${laundryId}` });
      this.socket.emit('vmconnected', `cloud.${laundryId}`);
    }).emit('authenticate', { token: this.sessionToken });

    this.socket.on('reconnect', () => {
      this.socket.emit('subscribe', { room: `cloud.${laundryId}` });
      this.socket.emit('vmconnected', `cloud.${laundryId}`);
      this.socket.emit('authenticate', { token: this.sessionToken });
    });

    // Incomming messages.
    this.socket.on('send', (pkg) => {
      try {
        this.incomingPkgObs.next(pkg);
      } catch (e) {}
    });
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
    }
  }

  send(pkg) {
    if (this.socket) {
      this.socket.emit('send1', pkg);      
    }
  }

  getPkg(): Observable<any> {
    return this.incomingPkgObs.asObservable();
  }

  rebootPC() {
    if (this.socket) {
      this.socket.emit('reboot');
    }
  }
}



