import { Component, OnDestroy } from '@angular/core';
import { NavController } from 'ionic-angular';
import { Storage } from '@ionic/storage';
import { JwtHelper } from 'angular2-jwt';

// Page components.
import { VendingAppPage } from '../vending-app/vending-app';

// Service/provider components.
import { AppSettings } from '../../providers/app-settings';
import { AppConfig } from '../../providers/app-config';
import { TranslateService } from '../../translate';
import { CommonServices } from '../../providers/common-services';
import { BackendApiProvider } from '../../providers/backend-api-provider';
import { Subscription } from 'rxjs/Rx';
import { Client } from '../../providers/client';
import { Machines } from '../../providers/machines'
import { Middleware } from '../../providers/middleware';
import { UnsavedOrders } from '../../providers/unsaved-orders';
import { Inactivity } from '../../providers/inactivity';
import { Orders } from '../../providers/orders';
import { HelpTour } from '../../providers/help-tour'

declare var swal: any;

@Component({
  selector: 'page-start',
  templateUrl: 'start.html'
})
export class StartPage implements OnDestroy {

  autoCharge: boolean = false;

  page: string = 'StartPage';

  adminCardRequest: boolean = false;

  logoImg = 'assets/img/logo.png';
  adminMode: boolean = false;
  vmMode: boolean = false;

  laundryId: string = null;
  vmId: string = null;
  vendingMachine: any = null;

  middlewareSubs: Subscription = null;
  csSubs: Subscription = null;
  jwtHelper: any = new JwtHelper();
  storage: any = new Storage();
  popToRoot: boolean = true;
  remoteMode: boolean = true;

  constructor(private navCtrl: NavController,
              private appSettings: AppSettings,
              private translate: TranslateService,
              private cs: CommonServices,
              private backendApi: BackendApiProvider,
              private client: Client,
              private appConfig: AppConfig,
              private machines: Machines,
              private orders: Orders,              
              private middleware: Middleware,
              private unsavedOrders: UnsavedOrders,
              private inactivityTimer: Inactivity,
              private help: HelpTour) {
    if (window.location.host.indexOf('localhost') !== -1) {
      this.remoteMode = false;
    }

    this.csSubs = this.cs.getCommand().subscribe(res => {
        if (res.dest !== 'start') return;
        switch (res.cmd) {
          case 'LOGOUT':
            this.client.resetCardInfo();
            if (this.adminMode) {
              this.cs.setCommand({ src: 'start', dest: 'app', cmd: 'LOGOUT' });
              this.adminMode = false;
            }
            // Go to app root page (if not already).
            if (this.navCtrl.getViews().length > 1) {
              this.cs.setCommand({ src: 'start', dest: 'modal', cmd: 'CLOSE' });
              this.navCtrl.popToRoot();
            }
            break;
          case 'CARD_HANLING_ON':
            this.adminCardRequest = false;
            break;
          case 'CARD_HANLING_OFF':
            this.adminCardRequest = true;
            break;
        }
      }
    );

    // Handle incoming data from the vending machine CPU.
    this.middlewareSubs = this.middleware.getPkg().subscribe(
      pkg => {
        if (!pkg.hasOwnProperty('code')) {
          let value = 0.00;

          switch (pkg.op) {
            case 'status_int':
              pkg.dev.forEach(item => {
                for (let i = 1; i <= 2; i++) {
                  let pkg = {
                    op: 'machine-issue',
                    data: {
                      id: item.id,
                      chn: i.toString(),
                      active: item.active,
                      status: item.status
                    }
                  };
                  this.machines.updateMachineState(pkg);
                }
              });
              break;
            case 'MIDDLEWARE_CONNECTED':
              // Enable/disable vending machine mode.
              this.storage.get('isVM').then(isVM => {
                this.storage.get('id_token').then(idToken => {
                  if (idToken) {
                    this.vmMode = isVM;

                    let decodedToken = this.jwtHelper.decodeToken(idToken);
                    if (decodedToken.hasOwnProperty('laundryId')) {
                      this.laundryId = decodedToken.laundryId;
                      // Save company info in local storage.
                      this.backendApi.getLaundryInfo({ laundryId: this.laundryId }).subscribe(
                        res => {
                          let ownerName = null;
                          let ownerNif = null;
                          let ownerPhone = null;
                          let ownerEmail = null;
                          if (res.hasOwnProperty('userLaundries') && res.userLaundries) {
                            if (res.userLaundries[0].user.hasOwnProperty('address')) {
                              ownerEmail = (res.userLaundries[0].user.address.email !== '') ? res.userLaundries[0].user.address.email : null;
                              ownerName = (res.userLaundries[0].user.name !== '') ? res.userLaundries[0].user.name : null;    
                              if (res.userLaundries[0].user.address.phoneNumber !== '') {
                                ownerPhone = res.userLaundries[0].user.address.phoneNumber;
                              }
                              if (res.userLaundries[0].user.address.mobileNumber !== '') {
                                ownerPhone = res.userLaundries[0].user.address.mobileNumber;
                              }
                            }
                            if (res.userLaundries[0].user.nif) {
                              ownerNif = res.userLaundries[0].user.nif;
                            }
                          }

                          this.storage.set('laundryInfo', {
                            laundryId: this.laundryId,
                            name: res.name,
                            addr: `${res.address.addressLine1}, ${res.address.postalCode}, ${res.address.city}, ${res.address.country}`,

                            ownerId: res.userLaundries[0].user_userId,

                            ownerName: ownerName,                            
                            nif: ownerNif,
                            phone: ownerPhone,
                            email: ownerEmail,

                            changeEnabled: res.obj.changeEnabled,
                            minCharge: res.obj.minCharge,
                            minRecharge: res.obj.minRecharge,
                            pricingObj: res.obj,
                            vm: res.vendingMachines,
                          });

                          // Get vending machine info (save on local storage??)
                          this.getVendingMachineInfo();

                          // Set software/hardware version
                          if (res.hasOwnProperty('vendingMachines') && Array.isArray(res.vendingMachines) && res.vendingMachines.length > 0) {
                            this.vmId = res.vendingMachines[0].vendingMachineId;

                            this.storage.get('appVersion').then(appVersion => {
                              if (appVersion) {
                                // Set app/software version
                                this.backendApi.setVersion('SOFTWARE', appVersion, this.vmId).subscribe(
                                  res => {},
                                  err => {}
                                );
                              }
                            });

                            // Send hardware version request to cpu
                            this.middleware.send({ op: 'get-version' });
                          }
                        },
                        err => {}
                      );
                    }
                    this.unsavedOrders.init();
                  } else {
                    this.vmMode = false;
                  }
                });
              });
              break;
            case 'get-version':
              // Set hardware version
              if (pkg.hasOwnProperty('data'))
              this.backendApi.setVersion('HARDWARE', pkg.data, this.vmId).subscribe(
                res => {},
                err => {}
              );
              break;
            case 'SET_LAUNDRY_ID':
              this.laundryId = pkg.laundryId;
              break;
            case  'bill-inserted':

              value = (this.appSettings.billEqTable.find(el => (el.key === pkg.data))) ? this.appSettings.billEqTable.find(el => (el.key === pkg.data)).value : null;

              this.storage.get('laundryInfo').then(laundryInfo => {
                let elBonus = 0;
                if (laundryInfo && laundryInfo.pricingObj.hasOwnProperty('rechargeBillBonus') && Number(laundryInfo.pricingObj.rechargeBillBonus) <= 100 && Number(laundryInfo.pricingObj.rechargeBillBonus) > 0) {
                  elBonus = value*(Number(laundryInfo.pricingObj.rechargeBillBonus)/100);
                  this.client.client['bonus'] = this.client.client['bonus'] + elBonus;
                }

// Send charge cmd to level
if (laundryInfo && laundryInfo.pricingObj.hasOwnProperty('autoCharge') && laundryInfo.pricingObj.autoCharge && this.navCtrl.getActive().name !== 'BuyCardPage' && this.navCtrl.getActive().name !== 'RechargeCardPage') {
  this.autoCharge = true;
  if (!this.client.client.hasOwnProperty('bonusArr')) {
    this.client.client['bonusArr'] = [];
    this.client.client['moneyArr'] = [];
    this.client.client['chargedArr'] = [];    
  }
  this.client.client['bonusArr'].push(elBonus);
  this.client.client['moneyArr'].push(value);
  if (this.client.client['bonusArr'].length === 1) {
    this.sendChargeRequest();  
  }
}
                
              });
              // value = (this.appSettings.billEqTable.find(el => (el.key === pkg.data))) ? this.appSettings.billEqTable.find(el => (el.key === pkg.data)).value : null;
            case 'remote-credits':
            case 'coin-inserted':
              if (pkg.op === 'coin-inserted' || pkg.op === 'remote-credits') {

// REMOTE CREDITS CODE
if (pkg.op === 'remote-credits') {
  value = (pkg.data) ? Math.round(Number(pkg.data)) / 100 : 0;
  this.client.client['credits'] = value;

  // SEND FEEDBACK WEBAPP
  this.middleware.send({ op: 'remote-credits-res', data: value.toString() });
} else {
  value = (this.appSettings.coinEqTable.find(el => (el.key === pkg.data))) ? this.appSettings.coinEqTable.find(el => (el.key === pkg.data)).value : null;
}

                  this.storage.get('laundryInfo').then(laundryInfo => {
                  let elBonus = 0;
                  if (pkg.op !== 'remote-credits' && laundryInfo && laundryInfo.pricingObj.hasOwnProperty('rechargeCoinBonus') && Number(laundryInfo.pricingObj.rechargeCoinBonus) <= 100 && Number(laundryInfo.pricingObj.rechargeCoinBonus) > 0) {
                    elBonus = value*(Number(laundryInfo.pricingObj.rechargeCoinBonus)/100);
                    this.client.client['bonus'] = this.client.client['bonus'] + elBonus;
                  }

                  // Send charge cmd to lovel
                  if (laundryInfo && laundryInfo.pricingObj.hasOwnProperty('autoCharge') && laundryInfo.pricingObj.autoCharge && this.navCtrl.getActive().name !== 'BuyCardPage' && this.navCtrl.getActive().name !== 'RechargeCardPage') {
                    this.autoCharge = true;  
                    if (!this.client.client.hasOwnProperty('bonusArr')) {
                      this.client.client['bonusArr'] = [];
                      this.client.client['moneyArr'] = [];
                      this.client.client['chargedArr'] = [];
                    }
                    this.client.client['bonusArr'].push(elBonus);
                    this.client.client['moneyArr'].push(value);
                    if (this.client.client['bonusArr'].length === 1) {
                      this.sendChargeRequest();  
                    }
                  }

                });
                // value = (this.appSettings.coinEqTable.find(el => (el.key === pkg.data))) ? this.appSettings.coinEqTable.find(el => (el.key === pkg.data)).value : null;
              }
              this.client.addToBalance(value);

              // Go to vending machine page if start page is on top of the navigation stack.
              if (this.navCtrl.getViews().length === 1) {
                this.goToActionSelectionPage();
              }
              break;





            case 'card-inserted':
            if (this.adminCardRequest) break; 

            this.client.setClientInfoByCard(pkg.data);

if (this.navCtrl.getActive().name !== 'BuyCardPage' && this.navCtrl.getActive().name !== 'RechargeCardPage') {
  this.sendChargeRequest();
} else {
  this.client.client['bonusArr'] = [];
  this.client.client['moneyArr'] = [];
  this.client.client['chargedArr'] = [];
}

            if (pkg.data.cardId) {
                // Check for admin mode
                if (pkg.data.admin === 'true') {
                  this.adminMode = true;
                  if (this.navCtrl.getActive().instance.page !== this.page) {
                    this.navCtrl.popToRoot();
                  }
                }

                // Check for staff card.
                this.backendApi.getCardPermissions(pkg.data.cardId).subscribe(
                  res => {},
                  err => {},
                  () => {
                    if (!this.adminMode) {
                      // Get client data from backend API.
                      this.backendApi.getClientInfo(pkg.data.cardId).subscribe(
                        res => {
                          if (res.hasOwnProperty('succes') && !res.success) {

                          } else {
                            this.client.setName(res.user.name);
                            this.client.setNif(res.user.nif);  
                          }
                        },
                        err => {}
                      );
                      // Go to vending machine page if start page is on top of the navigation stack.
                      if (this.navCtrl.getViews().length === 1) {
                        this.goToActionSelectionPage();
                      }
                    }
                  }
                );
              }

              break;
            case 'card-removed':
              if (this.adminCardRequest || this.navCtrl.getActive().instance.page === 'cardRechargePage') {
                break;
              }

              this.client.resetCardInfo();

              // Change machine state to not reserved (OK). REMOVE RESERVATION OF MACHINES IF THERE IS ORDERS!
              if (this.orders.orders.length > 0) {
                this.orders.orders.forEach(item => {
                  this.machines.updateMachineState({ op: 'machine-res-canceled', data: { id: item.machine.config.intId, chn: item.machine.peripheral_has_machines[0].channel }});
                });             
              }
              this.orders.reset();

              if (this.adminMode) {
                this.cs.setCommand({ src: 'start', dest: 'app', cmd: 'LOGOUT' });
                this.adminMode = false;
              }

              // Go to app root page (if not already).
              if (this.navCtrl.getViews().length > 1 && this.popToRoot) {
                this.popToRoot = false;
                setTimeout(() => { this.popToRoot = true; }, 300);
                this.cs.setCommand({ src: 'start', dest: 'modal', cmd: 'CLOSE' });

                if (this.navCtrl.getActive().instance.page !== 'NifConfirmationPage') {
                  this.navCtrl.popTo(this.navCtrl.getByIndex(0));
                }
              }
              break;
            case 'machine-started':
              this.machines.updateMachineState(pkg);
              break;
            case 'door-opened':
              this.machines.updateMachineState(pkg);
              break;
            case 'per-notification':
              if (this.vendingMachine) {
                let per = this.vendingMachine.vendingMachines[0].vendingMachinePeripherals.find(el => (el.type === this.translatePeripheralType(pkg.data.type)));
                let notification = {
                  code: pkg.data.code,
                  msg: pkg.data.msg,
                  vending_machine_vendingMachineId: this.vendingMachine.vendingMachines[0].vendingMachineId, 
                  vending_machine_peripheral_peripheralId: per.peripheralId,
                };
                // Send request to backend.
                this.backendApi.createLaundryNotification(this.laundryId, notification).subscribe(
                  res => {},
                  err => {}
                );
              }
case 'admin-mode':
  if (pkg.enabled === 'true') this.adminMode = true;
  break;
          } 
        } else {

if (pkg.op === 'hopper-status' && pkg.code !== '200') {
  this.appSettings.hopperOK = false;            
}

  if (pkg.op === 'write-card' && this.autoCharge  && this.navCtrl.getActive().name !== 'BuyCardPage' && this.navCtrl.getActive().name !== 'RechargeCardPage' && this.navCtrl.getActive().name !== 'NifConfirmationPage') {
    if (pkg.code === '201' && this.client.client['moneyArr'].length > 0) {
        // Success charging...
        let chargedValue = this.client.client['moneyArr'][0];
        let chargedBonus = this.client.client['bonusArr'][0];
        this.client.client['moneyArr'].shift();
        this.client.client['bonusArr'].shift();
        this.client.client['chargedArr'].push(chargedValue);
        this.client.client['balanceCard'] = this.client.client['balanceCard'] + chargedValue + chargedBonus;
        if (this.client.client['balanceCard'] < 0) this.client.client['balanceCard'] = 0;  
        this.client.client['balance'] = this.client.client['balance'] - chargedValue;
        if (this.client.client['balance'] < 0) this.client.client['balance'] = 0;  

        this.client.setClient();

        this.sendChargeRequest();
    }
    if (pkg.code !== '200' && pkg.code !== '201') {
      // Error charging
    }
  } 

        }
        // Reset inactivity timer.
        this.inactivityTimer.resetTimer();
      }
    );
  }

  simpleChangeRequest(change) {
    if (change >= 0.10) {
      let pkg =   {
        op: 'get-change',
        data: `${parseInt(Math.round(change*100).toString())}`,
      };
      this.middleware.send(pkg);
    }
  }

  ngOnDestroy() {
    this.middlewareSubs.unsubscribe();
    this.csSubs.unsubscribe();
  }

  toggleMenu() {
    this.cs.setCommand({ src: 'start', dest: 'app', cmd: 'TOGGLE_MENU' });
  }

  setAppLanguage(selectedLang) {
    this.cs.setCommand({ src: 'start', dest: 'app', cmd: 'SET_LANG', param: selectedLang });
  }

  goToActionSelectionPage() {
    if (this.vmMode) {
      this.navCtrl.push(VendingAppPage, { adminMode: this.adminMode, laundryId: this.laundryId });
    }
  }

  // NOTE: SAVE THIS ON LOCAL STORAGE TO BY AVAILABLE OFFLINE
  getVendingMachineInfo() {
    this.backendApi.getVmByLaundry(this.laundryId).subscribe(
      res => {
        this.vendingMachine = res;
      },
      err => {}
    );
  }

  translatePeripheralType(type) {
    switch (type) {
      case 'bill-acceptor': return 'BILL_ACCEPTOR';
      case 'card-dispenser': return 'CARD_DISPENSER';
      case 'coin-acceptor': return 'COIN_ACCEPTOR';
      case 'hopper': return 'HOPPER';
      case 'printer': return 'PRINTER';
      case 'rfid-rw': return 'RFID_RW';
    }
  }

  sendChargeRequest() {
    if (this.client.client.hasOwnProperty('admin') && this.client.client.admin) return;

    if (this.autoCharge && this.client.client.hasCard && Array.isArray(this.client.client['bonusArr']) && this.client.client['bonusArr'].length > 0) {
      let chargeValue = this.client.client.moneyArr[this.client.client.moneyArr.length - 1] + this.client.client.bonusArr[this.client.client.bonusArr.length - 1];
      let pkg =   {
        op: 'write-card',
        data: {
          cardId: this.client.client.cardNumber,
          name: this.client.client.name,
          nif: this.client.client.nif,
          balance: ((this.client.client.balanceCard + chargeValue) * 100).toString(),
          new: false,
          admin: false,
        },
      };

      this.middleware.send(pkg);
    }
  }


}



