import { Component, OnInit } from '@angular/core';
import { NavController, NavParams, AlertController } from 'ionic-angular';

// Page components.
import { LaundryPage } from '../laundry/laundry';
import { InterfacesPage } from '../interfaces/interfaces';
import { WashingMachinesPage } from '../washing-machines/washing-machines';
import { DryingMachinesPage } from '../drying-machines/drying-machines';

// Service/provider components.
import { TranslateService } from '../../translate';
import { VendingMachineApiProvider } from '../../providers/vending-machine-api-provider';


@Component({
  selector: 'page-machine-configuration',
  templateUrl: 'machine-configuration.html'
})
export class MachineConfigurationPage implements OnInit {

  browserMode: boolean = true;

  vendingMachineApi: any;
  tabs: Array<any>;
  tabsParams: any;

  constructor(private navCtrl: NavController,
              private navParams: NavParams,
              private alertCtrl: AlertController,
              private translate: TranslateService) {
    this.browserMode ? this.vendingMachineApi = null : this.vendingMachineApi = new VendingMachineApiProvider();
    this.tabs = [{
      page: LaundryPage,
      title: 'LAUNDRY_TAB_TITLE',
      iconName: 'home',
    },{
      page: InterfacesPage,
      title: 'INTERFACE_TAB_TITLE',
      iconName: 'pulse',
    }, {
      page: WashingMachinesPage,
      title: 'WASHING_MACHINE_TAB_TITLE',
      iconName: 'shirt',
    }, {
      page: DryingMachinesPage,
      title: 'DRYING_MACHINE_TAB_TITLE',
      iconName: 'thermometer',
    }];
    this.tabsParams = {
      laundry: this.navParams.get('laundry'),
      saved: true,
      vendingMachineApi: this.vendingMachineApi,
    };
  }

  ngOnInit() {
    if (!this.browserMode) {
      // Establish connection with the vending machine.
      this.vendingMachineApi.connect('13.69.12.56', '16852');
    }
  }

  ionViewCanLeave(): boolean {
    let alert;
    if (!this.tabsParams.saved) {
      alert = this.alertCtrl.create({
        title: this.translate.getTranslation('ALERT_UNSAVED_TITLE'),
        message: this.translate.getTranslation('ALERT_UNSAVED_MSG'),
        buttons: [{
          text: this.translate.getTranslation('YES'),
          // Leave without saving changes.
          handler: () => {
            this.tabsParams.saved = true;
            if (this.navCtrl.getViews().length > 1) this.navCtrl.pop();
          }
        },{
          // Go back to configuration page to save changes.
          text: this.translate.getTranslation('NO'),
          handler: () => {
            this.tabsParams.saved = false;
          }
        }],
      });
      alert.present();
      return false;
    }
    return true;
  }

}



